window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0012", [{"word":"debate","ipa_uk":"/dɪˈbeɪt/","ipa_us":"/dɪˈbeɪt/","definition_zh":"辩论；争论；辩论赛；斟酌","definition_en":"to argue about a question from opposing sides, or to weigh a choice in the mind","core_image":"两个人隔着一张桌子，把同一个问题来回击打，谁也不肯先松手","scene":"Two students grip the podium and the moderator says: The debate on school uniforms starts in one minute.","sceneCN":"这里 debate 是「辩论赛」（第 1 个义项：正反双方按规则就同一动议交锋）；句意：关于校服的辩论赛一分钟后开始。画面里有讲台、计时器和正反双方的名牌。","pos":[{"tag":"n.","zh":"辩论；辩论赛；争论"},{"tag":"v.","zh":"公开辩论；斟酌；（古）争执、交战"}],"collocations":[{"phrase":"a heated debate","zh":"激烈的辩论"},{"phrase":"debate over something","zh":"就某事展开争论"},{"phrase":"debate whether to do","zh":"斟酌是否要做"},{"phrase":"open to debate","zh":"尚有争议"},{"phrase":"a televised debate","zh":"电视辩论"}],"forms":[{"label":"三单","form":"debates"},{"label":"过去式","form":"debated"},{"label":"过去分词","form":"debated"},{"label":"现在分词","form":"debating"}],"derivatives":[{"word":"debater","pos":"n.","zh":"辩论者；辩手"},{"word":"debatable","pos":"adj.","zh":"有争议的；可争辩的"},{"word":"debating","pos":"n./adj.","zh":"辩论（的）；辩论活动"},{"word":"debatably","pos":"adv.","zh":"有争议地"},{"word":"battle","pos":"n./v.","zh":"战斗；搏斗（同出 battuere“击打”）"}],"senses":[{"no":"01","title":"Formal contest: two sides strike a motion","titleCN":"辩论赛：正反双方就有争议的动议交锋","definition":"a formal discussion in which two people or teams argue opposite sides of a question","definitionCN":"两人或两队就某一问题分别持相反立场、按规则进行的正式辩论","example":"The final debate between the two candidates drew millions of viewers.","exampleCN":"两位候选人之间的最后一场辩论吸引了数百万观众。","why":"The noun is recorded from early 15c. as 'a formal dispute, a debating contest'. It grew from the older sense 'contention by argument', which itself came out of a quarrel: two sides strike the same question until one gives way.","whyCN":"名词从 15 世纪初起记录为“正式争论、辩论比赛”。它由更早的“以论辩相争”长出来，而那一层又源自争吵：两方击打同一个问题，直到一方退让。"},{"no":"02","title":"Public argument: a question argued across society","titleCN":"公共争论：全社会都在争的那个问题","definition":"an ongoing public argument about a topic, with many people taking sides","definitionCN":"围绕某一话题持续进行、各方站队的公共争论","example":"The debate over gene editing is far from settled.","exampleCN":"关于基因编辑的争论远未尘埃落定。","why":"The noun's 'contention by argument' sense dates from late 14c. Once a quarrel leaves the room and enters public speech, it becomes an ongoing debate rather than a single contest.","whyCN":"名词“以论辩相争”的义项可追溯到 14 世纪后期。争吵一旦离开房间、进入公共言论，就从一场比赛变成持续进行的争论。"},{"no":"03","title":"Argue in public: take one side and defend it","titleCN":"公开辩论：站定一方并为其辩护","definition":"to argue for or against a proposal in public, especially in a formal setting","definitionCN":"公开为某项主张辩护或反对，尤指在正式场合","example":"She debated the motion with confidence and won the round.","exampleCN":"她自信地为该动议辩护，赢下了这一轮。","why":"'To argue for or against in public' is recorded from the 1520s. The older verb meant 'to contend about in argument' (mid-15c.); speaking the case aloud turns inner contention into a public performance.","whyCN":"“公开为某方辩护或反对”记录于 16 世纪 20 年代。更早的动词义是“就某事在论证中相争”（15 世纪中期）；把案子说出口，就把内心相争变成公开表演。"},{"no":"04","title":"Weigh in the mind: debate a choice with yourself","titleCN":"斟酌：在心里反复掂量一个选择","definition":"to think carefully about the pros and cons of a choice before deciding","definitionCN":"在作决定前仔细权衡一个选择的正反两面","example":"I'm still debating whether to accept the offer.","exampleCN":"我还在斟酌要不要接受这个提议。","why":"From late 14c. debate also meant 'discuss, deliberate upon the pros and cons'. The same back-and-forth moves inside one head: the self takes both sides and strikes the question alone.","whyCN":"从 14 世纪后期起，debate 也指“讨论、反复权衡利弊”。同一个来回被搬进一个人的脑袋：自我分成两方，独自击打这个问题。这就是“斟酌”。"},{"no":"05","title":"Quarrel: voices raised, no rules","titleCN":"争执：抬高嗓门、没有规则的吵","definition":"a heated disagreement or quarrel, now usually literary or archaic","definitionCN":"激烈的分歧或争吵，现多为书面或古旧用法","example":"The brothers fell into a bitter debate over the family land.","exampleCN":"兄弟俩为家里的土地陷入了激烈的争执。","why":"The noun began in early 14c. as 'a quarrel, dispute, disagreement'. Only later was it tamed into argument; the old heat survives in literary use.","whyCN":"名词在 14 世纪初本是“争吵、纠纷、不合”。后来才被驯化成“论证”；旧日的火气仍留在书面语里。"},{"no":"06","title":"Do battle: the oldest sense, to fight","titleCN":"交战：最古老的一义，真刀真枪地打","definition":"to fight or make war, an archaic sense of the verb","definitionCN":"打斗、交战，动词的古旧义","example":"In the old ballad, the two lords debate the field with steel.","exampleCN":"在那首古老的歌谣里，两位领主用刀剑争夺这片战场。","why":"Late 14c. records the verb as 'to combat, fight, make war'. It comes from Old French debatre 'to fight', literally de- 'down, completely' plus batre 'to beat': to beat an enemy down.","whyCN":"14 世纪后期记录动词义“格斗、作战”。它来自古法语 debatre“打斗”，字面是 de-“向下、彻底”加 batre“打”：把对手彻底打倒。这就是最古老的一层。"},{"no":"07","title":"Open question: still struck from both sides","titleCN":"尚有争议：问题仍被两边来回击打","definition":"the state of being unsettled or disputed, as in the phrase open to debate","definitionCN":"尚未有定论、仍有争议的状态，如短语 open to debate","example":"Whether the policy actually reduced poverty remains open to debate.","exampleCN":"该政策是否真的减少了贫困，仍可争议。","why":"When a question is still 'open to debate', the contest has not stopped. Debatable (1530s) names the same condition from the adjective side: a matter that can still be struck at.","whyCN":"当一个问题仍 open to debate，说明这场交锋没有停。debatable（16 世纪 30 年代）从形容词一侧命名同一状态：一件仍可被击打的事。"},{"no":"08","title":"Debate as a skill: training the tongue","titleCN":"辩论术：把口舌练成手艺","definition":"the activity or skill of arguing formally, taught and practised as an exercise","definitionCN":"正式论辩的活动或技巧，作为训练内容被教授与练习","example":"Debate taught him to listen to the other side before answering.","exampleCN":"辩论训练让他学会在回应前先听对方的说法。","why":"Once the formal contest (sense 01) is repeated in schools and clubs, the match turns into a trainable craft. The word then names the practice, not just one event.","whyCN":"当正式的辩论赛（第 1 义）在学校和社团里反复进行，比赛就变成一门可训练的手艺。这个词于是命名这种实践，而不只是某一场比赛。"},{"no":"09","title":"The chamber's argument: debate on the floor","titleCN":"议会辩论：议事厅里的正式交锋","definition":"a formal discussion of a proposal in a parliament or assembly before a vote","definitionCN":"议会或立法机构在表决前对提案进行的正式讨论","example":"The bill passed after six hours of debate on the floor.","exampleCN":"经过六小时的议会辩论，该法案通过了。","why":"Legislatures inherited the formal-dispute sense and gave it a procedure: a motion, two sides, a vote. The chamber's debate is sense 01 written into law.","whyCN":"立法机构继承了“正式争论”这一层，并给它配上程序：动议、两方、表决。议事厅里的辩论，就是把第 1 义写进法律程序。"}],"etymology":{"intro":{"en":"Debate is Latin 'to beat down'. It entered English through Old French debatre, first meaning actual fighting, then argument, and only later the calm weighing of a choice.","cn":"debate 是拉丁语“往下打”。它经古法语 debatre 进入英语，先指真正的打斗，再指言语相争，最后才指冷静权衡一个选择。"},"items":[{"era":"LATIN (before 1C AD)","en":"Battuere meant 'to beat, strike'. Its deeper origin is not established; etymologists sometimes call it Gaulish or imitative, so the step below it is source uncertain.","cn":"battuere 意为“打、击”。其更深来源未被确立，词源学家有时称它来自高卢语或拟声，因此它下面的一层“来源不确定”。"},{"era":"OLD FRENCH (13c.)","en":"Debatre meant 'to fight, contend', from de- 'down, completely' plus batre 'to beat'. The word still carried the physical blow.","cn":"debatre 意为“打斗、相争”，由 de-“向下、彻底”加 batre“打”构成，词里仍带着实打实的一击。"},{"era":"LATE 14c. ENGLISH","en":"The verb is first recorded as 'to quarrel, dispute' and 'to combat, fight, make war'; the noun appears in early 14c. as 'a quarrel, disagreement'.","cn":"动词最早记录为“争吵、争执”和“格斗、作战”；名词在 14 世纪初出现，意为“争吵、不合”。"},{"era":"MID-15c. ENGLISH","en":"The transitive sense 'to contend about in argument' appears mid-15c., and the noun's 'contention by argument' from late 14c. grows beside it.","cn":"及物义“就某事在论证中相争”出现于 15 世纪中期；名词“以论辩相争”的义项从 14 世纪后期起在旁生长。"},{"era":"1520s ENGLISH","en":"'To argue for or against in public' is recorded from the 1520s, and the noun's 'formal dispute, debating contest' from early 15c.","cn":"“公开为某方辩护或反对”记录于 16 世纪 20 年代；名词“正式争论、辩论比赛”记录于 15 世纪初。"},{"era":"ORIGIN UNCERTAIN","en":"The chain stops at Latin battuere 'to beat'. No written record establishes anything earlier, so the deepest step is marked source uncertain rather than given an invented root.","cn":"这条链停在拉丁语 battuere“打”上。没有任何书面记录能确立更早的来源，所以最深层标为“来源不确定”，而不给它编造词根。"}]},"similar":{"note":{"en":"The first group is chosen for spelling and sound, the second for meaning, so that form and sense stay separate.","cn":"第一组按拼写和读音挑选，第二组按词义挑选，这样词形和词义不会混在一起。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"rebate","ipa":"/ˈriːbeɪt/","tag":"prefix swap","definition":"a sum of money paid back or taken off a price. It swaps de- for re- and keeps the -bate ending.","definitionCN":"退款；折扣。它把 de- 换成 re-，保留 -bate 词尾。"},{"word":"abate","ipa":"/əˈbeɪt/","tag":"same root","definition":"to become less intense or widespread. It comes from Old French abatre 'to beat down', the same batre.","definitionCN":"减弱；消退。它来自古法语 abatre“打倒”，同出 batre。"},{"word":"debase","ipa":"/dɪˈbeɪs/","tag":"one letter","definition":"to lower the value or quality of something. It differs from debate in the final consonant.","definitionCN":"贬低；降低价值。它与 debate 只差最后那个辅音。"}]},{"heading":"NEAR MEANING","entries":[{"word":"argument","ipa":"/ˈɑːɡjumənt/","tag":"clash of reasons","definition":"a set of reasons given for or against a position. It names the content, while debate names the exchange.","definitionCN":"论点；论证。它命名内容，而 debate 命名一来一往的交锋。"},{"word":"discussion","ipa":"/dɪˈskʌʃn/","tag":"exchange","definition":"a conversation in which people share views. It is calmer and less adversarial than debate.","definitionCN":"讨论。它比 debate 更平和，也更少对抗性。"},{"word":"dispute","ipa":"/dɪˈspjuːt/","tag":"sharp disagreement","definition":"a disagreement that may become angry or legal. It is closer to the old quarrel sense of debate.","definitionCN":"争端；纠纷。它更接近 debate 古老的“争吵”义。"},{"word":"deliberation","ipa":"/dɪˌlɪbəˈreɪʃn/","tag":"weighing","definition":"long and careful consideration before a decision. It matches the private, mental sense of debate.","definitionCN":"审议；深思熟虑。它对应 debate 私下、心里的那一义。"},{"word":"contend","ipa":"/kənˈtend/","tag":"argue a side","definition":"to argue strongly for a position, or to compete. It stresses the effort of the side taken.","definitionCN":"主张；争夺。它强调为所站一方付出的力气。"}]}]},"mnemonics":{"normalIntro":{"en":"These links are real: the Latin batre 'to beat', the Old French debatre, and the English words that grew from the same blow.","cn":"这些联想都是真实的：拉丁语 batre“打”、古法语 debatre，以及从同一击里长出的英语词。"},"normal":[{"en":"debate = de- 'down' + batre 'to beat': two sides beat the same question down until one side yields.","cn":"debate = de-“向下”+ batre“打”：两方把同一个问题往下打，直到一方让步。"},{"en":"The same batre gives battle, batter, combat and abate: every one of them is a form of beating.","cn":"同一个 batre 给出 battle、batter、combat、abate：每一个都是某种“打”。"},{"en":"A debate and a battle share a root, which is why we still speak of attacking an argument and defending a position.","cn":"debate 与 battle 同根，所以我们至今会说“攻击一个论点”“捍卫一个立场”。"},{"en":"When you debate a choice alone, you are holding a two-sided contest inside one head.","cn":"当你独自斟酌一个选择，你是在一个脑袋里举行一场两方的比赛。"},{"en":"open to debate means the exchange is still live: the question has not stopped being struck.","cn":"open to debate 意为交锋仍在进行：这个问题还没有停止被击打。"}],"abstract":[{"en":"The core is repeated impact: words take the place of blows, but the rhythm is the same, back and forth.","cn":"核心是反复的撞击：言语取代了拳头，但节奏相同，一来一往。"},{"en":"The word moves from fist to voice to mind: first a fight, then a public argument, then a private weighing.","cn":"这个词从拳头走到声音，再走到心里：先是打斗，再是公开争论，最后是私下权衡。"},{"en":"So quarrel, contest, discussion and deliberation are one exchange seen at four levels of heat.","cn":"所以争吵、比赛、讨论、斟酌是同一场交锋在四种热度下的样子。"}]},"examples":[{"en":"The class debated whether school uniforms should be required.","cn":"班上就是否应该要求穿校服展开了辩论。"},{"en":"She is debating whether to study abroad or stay home.","cn":"她在斟酌是出国留学还是留在国内。"},{"en":"The debate over the new highway lasted for years.","cn":"关于新高速公路的争论持续了多年。"}],"dict_mnemonic":{"note":"谐音联想 · 非词源","text":"de（得）+ bate（beat 打）——两个人互相打嘴仗，打得谁也说服不了谁 → debate 辩论","word":"debate"},"root":"源自拉丁语 battuere“击打”，经古法语 debatre“打斗”于 14 世纪进入英语：de-“彻底”+ batre“打”，核心是“反复击打同一个问题”。","sensesIntro":{"en":"Nine senses of debate, all built on one back-and-forth blow: a fight, a quarrel, a public argument, a formal contest, a mind weighing a choice, and a chamber settling a law.","cn":"debate 的九个义项都建在同一次来回击打上：打斗、争吵、公共争论、正式比赛、心里权衡一个选择，以及议事厅里议定一条法律。"},"semanticMap":{"core":{"en":"CORE IMAGE: one question struck back and forth between two sides.","cn":"核心意象：同一个问题在两边之间被来回击打。"},"chain":["STRIKE THE QUESTION","TRADE BLOWS","CLASH IN WORDS","ARGUE A SIDE","WEIGH IN THE MIND","STAY OPEN OR SETTLE"],"branches":[{"senses":"S01 · S09","en":"THE FORMAL FRAME: a contest of two sides, and the chamber's procedure that inherits it.","cn":"正式框架：两方的比赛，以及承继它的议事厅程序。"},{"senses":"S02 · S07","en":"A LIVE QUESTION: public argument across society, and the state of being still open.","cn":"活的问题：全社会范围内的公共争论，以及仍未定论的状态。"},{"senses":"S03 · S08","en":"THE PRACTISED VOICE: arguing in public, and the skill trained by repetition.","cn":"练出来的声音：公开辩护，以及靠反复练习得来的技巧。"},{"senses":"S04","en":"THE PRIVATE ARENA: both sides of a choice struck inside one mind.","cn":"私人赛场：一个选择的正反两面在一个人心里交锋。"},{"senses":"S05 · S06","en":"THE OLD HEAT: a quarrel in words, and the oldest sense, actual fighting.","cn":"旧日的火气：言语上的争吵，以及最古老的实打。"}]},"affixes":{"intro":{"en":"Debate is de- plus batre. Its family shows the prefixes de-, re-, com- and a-, the root bat- 'beat', and the suffixes -er, -able and -ing.","cn":"debate 是 de- 加 batre。它的词族展示前缀 de-、re-、com-、a-，词根 bat-“打”，以及后缀 -er、-able、-ing。"},"latinIntro":{"en":"Latin battuere 'to beat' is the base of battle, battery and combat; the same verb, with prefixes, yields abate and debate.","cn":"拉丁语 battuere“打”是 battle、battery、combat 的基础；同一个动词加前缀，给出 abate 与 debate。"},"items":[{"word":"debate","structure":"de- (down, completely) + batre (to beat)","meaning":"to argue a question from opposing sides","meaningCN":"辩论；斟酌（de- 彻底，batre 打）","example":"They debated the budget for two hours.","exampleCN":"他们辩论预算辩论了两个小时。"},{"word":"debater","structure":"debate + -er (person)","meaning":"a person who takes part in debates","meaningCN":"辩手；辩论者（-er 表人）","example":"She is the best debater on the team.","exampleCN":"她是队里最好的辩手。"},{"word":"debatable","structure":"debate + -able (worthy of)","meaning":"open to argument; not settled","meaningCN":"有争议的（-able 表值得……的）","example":"Whether the plan will work is debatable.","exampleCN":"这个计划是否奏效还有争议。"},{"word":"debating","structure":"debate + -ing (activity noun)","meaning":"the activity of arguing formally","meaningCN":"辩论活动（-ing 构成动名词）","example":"He joined the debating society.","exampleCN":"他加入了辩论社。"},{"word":"batter","structure":"batre (to beat) + -er","meaning":"to hit again and again","meaningCN":"连续猛击（同出 batre 打）","example":"Waves battered the seawall all night.","exampleCN":"海浪整夜拍打海堤。"},{"word":"battle","structure":"Latin battualia (fighting exercises) via Old French","meaning":"a fight between armed forces","meaningCN":"战斗（源自 battualia 操练）","example":"The battle lasted until dawn.","exampleCN":"战斗持续到黎明。"},{"word":"combat","structure":"com- (together) + battuere (to beat)","meaning":"fighting between opposing forces","meaningCN":"战斗；格斗（com- 共同 + 打）","example":"The soldiers were trained in hand-to-hand combat.","exampleCN":"士兵们受过徒手格斗训练。"},{"word":"abate","structure":"a- (ad-, to) + batre (to beat down)","meaning":"to become less strong","meaningCN":"减弱（打倒 → 势头下去）","example":"The storm abated by morning.","exampleCN":"到早晨风暴减弱了。"},{"word":"battery","structure":"battre (to beat) + -ery (noun)","meaning":"a set of guns, or a device that stores power","meaningCN":"炮组；电池（原指连续击打的一排炮）","example":"The battery died after an hour.","exampleCN":"电池一小时后就没电了。"}],"latinEntries":[{"word":"battuere","structure":"battuere (verb)","meaning":"to beat, strike","meaningCN":"击打"},{"word":"battualia","structure":"battuere + -alia (neuter plural)","meaning":"fighting exercises","meaningCN":"格斗操练"},{"word":"combattere","structure":"com- + battuere (Late Latin)","meaning":"to fight together against","meaningCN":"共同击打；交战"}]}},{"word":"decline","ipa_uk":"/dɪˈklaɪn/","ipa_us":"/dɪˈklaɪn/","definition_zh":"下降；衰退；婉拒；变格；倾斜","definition_en":"to move or fall downward, to grow weaker, or to refuse politely","core_image":"脚下原本平直的路面开始向下倾斜，站上去的人只能一路往下走","scene":"A doctor looks at the chart and tells the family: Her memory has declined sharply this year.","sceneCN":"这里 decline 是「（能力、健康）衰退」（第 2 个义项：身体或心智功能逐渐变弱）；句意：她的记忆力今年急剧衰退。画面里有病历曲线、医生和家属。","pos":[{"tag":"vi.","zh":"下降；衰退；倾斜；变格"},{"tag":"vt.","zh":"婉言谢绝"},{"tag":"n.","zh":"下降；衰退；晚年"}],"collocations":[{"phrase":"decline sharply","zh":"急剧下降"},{"phrase":"decline an invitation","zh":"谢绝邀请"},{"phrase":"decline to comment","zh":"拒绝置评"},{"phrase":"a decline in sales","zh":"销量下滑"},{"phrase":"in decline","zh":"处于衰退之中"}],"forms":[{"label":"三单","form":"declines"},{"label":"过去式","form":"declined"},{"label":"过去分词","form":"declined"},{"label":"现在分词","form":"declining"}],"derivatives":[{"word":"declination","pos":"n.","zh":"倾斜；偏差；偏角"},{"word":"declension","pos":"n.","zh":"变格；词形变化"},{"word":"declinable","pos":"adj.","zh":"可变格的"},{"word":"indeclinable","pos":"adj.","zh":"不变格的"},{"word":"declining","pos":"adj.","zh":"下降的；衰退中的"}],"senses":[{"no":"01","title":"Numbers fall: the line bends down","titleCN":"数量下降：曲线向下弯","definition":"to become smaller in amount, number, or rate","definitionCN":"数量、数目或比率变小","example":"Sales declined by twelve percent in the third quarter.","exampleCN":"第三季度销售额下降了百分之十二。","why":"The verb is recorded in late 14c. as 'sink to a lower level'. The image is geometric: de- 'down' plus clinare 'to bend', so a line that was level bends downward.","whyCN":"动词在 14 世纪后期记录为“降到更低的水位”。意象是几何的：de-“向下”加 clinare“弯”，原本水平的一条线于是向下弯。"},{"no":"02","title":"Strength fades: the body heads downhill","titleCN":"体力衰退：身体走下坡","definition":"of health, memory, or physical power, to grow gradually weaker","definitionCN":"健康、记忆或体力逐渐变弱","example":"His hearing began to decline in his fifties.","exampleCN":"他五十多岁时听力开始衰退。","why":"Late 14c. also gives the figurative 'fall to an inferior or impaired condition'. A body at its peak stands on level ground; age tilts the ground and the powers go down the slope.","whyCN":"14 世纪后期也给出了比喻义“落入较差或受损的状态”。身体在巅峰时站在平地上；年龄把地面倾斜，各种能力便顺着坡往下走。"},{"no":"03","title":"A system loses its height","titleCN":"体系衰落：整体失去高度","definition":"of a society, economy, or institution, to lose vigor and importance over time","definitionCN":"（社会、经济或机构）随时间失去活力与重要性","example":"The empire declined slowly, not in a single battle.","exampleCN":"这个帝国是慢慢衰落的，不是在一场战役中垮掉的。","why":"The same downhill movement is scaled up from a body to a civilization. Decline is gradual by definition: the slope is long, and no single step explains the whole fall.","whyCN":"同一个下坡运动从身体放大到文明。decline 天生是渐进的：坡很长，没有哪一步能解释整个下落。"},{"no":"04","title":"A polite no: bend away from the request","titleCN":"婉拒：从请求前侧身让开","definition":"to refuse an invitation or offer politely","definitionCN":"礼貌地拒绝邀请或提议","example":"She declined the invitation with a warm note of thanks.","exampleCN":"她婉言谢绝了邀请，并附上一封诚挚的感谢信。","why":"The 'politely refuse' sense is recorded from the 1630s. To decline is to bend away from what is offered instead of meeting it head-on: de- 'from' plus clinare 'to bend', a bow that steps aside.","whyCN":"“婉言拒绝”这一义记录于 17 世纪 30 年代。decline 是朝旁边弯开、不去正面接住对方递来的东西：de-“离开”加 clinare“弯”，一个侧身让开的鞠躬。"},{"no":"05","title":"Grammar: the word bends away from its base","titleCN":"变格：词形从原形上弯开","definition":"in grammar, to inflect a noun, pronoun, or adjective into its cases","definitionCN":"语法上把名词、代词或形容词按格变化","example":"Latin nouns decline into six cases, each with its own ending.","exampleCN":"拉丁语名词变格为六个格，每个格都有自己的词尾。","why":"Grammar took the word in late 14c. Latin declinare meant 'to bend from, inflect': each case is the base form bent away in a new direction. English still calls the set of forms a declension.","whyCN":"语法在 14 世纪后期借用了这个词。拉丁语 declinare 意为“从……弯开、变格”：每一个格都是原形朝新方向弯出去的形状。英语至今把这整套形式叫作 declension。"},{"no":"06","title":"The sun slants down: bending toward the horizon","titleCN":"西斜：太阳朝地平线弯下去","definition":"to slope or bend downward, or of the sun, to move toward setting","definitionCN":"向下倾斜；或指太阳西斜、将落","example":"The declining sun turned the fields a deep gold.","exampleCN":"西斜的太阳把田野染成深金色。","why":"The intransitive 'bend or slant down' is recorded from c. 1400. This sense keeps the physical core intact: a thing that declines is not falling yet, only tilting toward the low side.","whyCN":"不及物义“向下弯、向下斜”记录于约 1400 年。这一层保留着物理核心：declining 的东西还没有掉下来，只是朝低处倾斜。"},{"no":"07","title":"A drop named: the fall as a fact","titleCN":"跌幅：被命名的那一次下降","definition":"a reduction in amount, number, or rate","definitionCN":"数量、数目或比率的减少","example":"There was a sharp decline in road accidents last year.","exampleCN":"去年道路事故数量大幅下降。","why":"The noun, recorded from early 14c., took the verb's downward movement and named it. What was an event in time becomes a measurable quantity: a decline of ten percent.","whyCN":"名词从 14 世纪初起记录，接过动词的下行运动并把它命名。原本发生在时间里的动作，变成一个可测量的量：百分之十的降幅。"},{"no":"08","title":"The evening of life: the last downward stretch","titleCN":"晚年：人生最后一段下坡","definition":"the later part of life, when physical and mental powers are failing","definitionCN":"人生后期，体力和心力渐衰的阶段","example":"He wrote his best poems in the decline of his life.","exampleCN":"他在晚年写出了最好的诗。","why":"The phrase decline of life is recorded by 1711 and was shortened to decline. A life is imagined as a slope: the last stretch is still life, but it is the part that goes down.","whyCN":"短语 decline of life 在 1711 年前已有记录，后缩略为 decline。人生被想象成一道坡：最后一段仍是人生，只是那一段在往下走。"},{"no":"09","title":"Deterioration: the state of having slipped lower","titleCN":"衰败：已经滑到更低处的状态","definition":"a gradual worsening in quality, strength, or condition","definitionCN":"质量、力量或状况逐渐变差","example":"The report describes the decline of the city's public services.","exampleCN":"报告描述了这座城市公共服务的衰败。","why":"The noun began in early 14c. as 'deterioration, degeneration, a sinking into an impaired condition'. Here the downward movement is finished: what is named is the lower state itself.","whyCN":"名词在 14 世纪初本是“恶化、退化、陷入受损状态”。在这一义里，下行运动已经完成：命名的是那个更低的处境本身。"}],"etymology":{"intro":{"en":"Decline is Latin 'to bend away'. Every sense keeps the geometry of a line tilting from the level: numbers, health, empires, grammar forms and even a polite refusal all move off the straight path.","cn":"decline 是拉丁语“弯开去”。每个义项都保留一条线偏离水平面的几何形状：数字、健康、帝国、语法形式乃至礼貌的拒绝，都离开了直路。"},"items":[{"era":"LATIN","en":"Declinare meant 'to lower; avoid, deviate; bend from, inflect', from de- 'from' plus clinare 'to bend'. It already carried both the physical slant and the grammatical case sense.","cn":"declinare 意为“降低；避开、偏离；从……弯开、变格”，由 de-“离开”加 clinare“弯”构成。它同时带着物理倾斜与语法变格两层意思。"},{"era":"OLD FRENCH","en":"Decliner meant 'to sink, decline, degenerate, turn aside'. Old French passed the downward and the turning-away senses together into English.","cn":"decliner 意为“下沉、衰退、退化、转向一旁”。古法语把“向下”和“转开”两层一起传入英语。"},{"era":"LATE 14c. ENGLISH","en":"The verb appears as 'to turn aside, deviate' (now archaic), 'sink to a lower level', and figuratively 'fall to an inferior or impaired condition'. Grammar also adopts it for inflection.","cn":"动词出现，意为“转向一旁、偏离”（今已古旧）、“降到更低的水位”，以及比喻义“落入较差或受损的状态”。语法也借它表示变格。"},{"era":"c. 1400 ENGLISH","en":"The intransitive 'bend or slant down' is recorded, and the noun is already in use from early 14c. for 'deterioration, degeneration'.","cn":"不及物义“向下弯、向下斜”得到记录；名词从 14 世纪初已用于“恶化、退化”。"},{"era":"1630s–1711","en":"The polite refusal sense is recorded from the 1630s. The phrase decline of life is in use by 1711 and later shortened to decline.","cn":"礼貌拒绝义记录于 17 世纪 30 年代。短语 decline of life 在 1711 年前已在使用，后来缩略为 decline。"},{"era":"ORIGIN UNCERTAIN","en":"The slope stops at Latin clinare 'to bend'. The usual earlier form is the reconstructed PIE root *klei- 'to lean', which has no written record, so the step below Latin is marked source uncertain.","cn":"这道坡停在拉丁语 clinare“弯”。更早通常写作重构的原始印欧语词根 *klei-“倚、倾”，它没有书面记录，因此拉丁语下面的一层标为“来源不确定”。"}]},"similar":{"note":{"en":"The first group is chosen for spelling and sound, the second for meaning, so that form and sense stay separate.","cn":"第一组按拼写和读音挑选，第二组按词义挑选，这样词形和词义不会混在一起。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"incline","ipa":"/ɪnˈklaɪn/","tag":"same root, opposite direction","definition":"to lean or tend toward something. It is in- 'toward' plus clinare 'to bend', the mirror of decline.","definitionCN":"倾向；倾斜。它是 in-“朝向”加 clinare“弯”，正是 decline 的镜像。"},{"word":"recline","ipa":"/rɪˈklaɪn/","tag":"same root","definition":"to lean back in a relaxed position. It is re- 'back' plus clinare, bending backward rather than down.","definitionCN":"斜倚；后靠。它是 re-“向后”加 clinare，向后弯而不是向下弯。"},{"word":"declension","ipa":"/dɪˈklenʃn/","tag":"derived noun","definition":"the set of case forms of a noun or adjective. It is the noun built on the grammatical sense of decline.","definitionCN":"变格；词形变化表。它是 decline 语法义的名词形式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"decrease","ipa":"/dɪˈkriːs/","tag":"go down","definition":"to become less in size or number. It is the plain neutral word for sense 01.","definitionCN":"减少。它是第 1 义最普通的中性词。"},{"word":"drop","ipa":"/drɒp/","tag":"sudden fall","definition":"to fall suddenly or steeply. It adds speed that decline usually does not have.","definitionCN":"骤降。它加上了 decline 通常没有的突然与陡峭。"},{"word":"refuse","ipa":"/rɪˈfjuːz/","tag":"say no","definition":"to say that one will not do or accept something. It is blunt where decline is polite.","definitionCN":"拒绝。它直截了当，而 decline 更客气。"},{"word":"deteriorate","ipa":"/dɪˈteriəreɪt/","tag":"get worse","definition":"to become worse in quality or condition. It matches the qualitative noun sense 09.","definitionCN":"恶化。它对应第 9 义的质变用法。"},{"word":"diminish","ipa":"/dɪˈmɪnɪʃ/","tag":"grow less","definition":"to become gradually smaller or weaker. It stresses slow loss rather than a measured rate.","definitionCN":"逐渐减少、减弱。它强调缓慢损耗，而非可测量的比率。"}]}]},"mnemonics":{"normalIntro":{"en":"These links are real: de- plus clinare 'to bend', the incline and recline family, and the grammatical term declension.","cn":"这些联想都是真实的：de- 加 clinare“弯”、incline 与 recline 词族，以及语法术语 declension。"},"normal":[{"en":"decline = de- 'down' + clinare 'to bend': a line that bends downward is already on its way down.","cn":"decline = de-“向下”+ clinare“弯”：一条向下弯的线，已经在往下走了。"},{"en":"The same clinare gives incline and recline: leaning toward, or leaning back. Decline leans down.","cn":"同一个 clinare 给出 incline 与 recline：朝前倾、向后靠。decline 则向下弯。"},{"en":"Grammar: cases bend the word away from its base form, which is why the whole set is a declension.","cn":"语法：各格把词从原形弯开，所以整套形式叫 declension。"},{"en":"A polite no is a bow aside: you decline an invitation by bending away from it, not by pushing it back.","cn":"礼貌的拒绝是一个侧身礼：你婉拒邀请，是朝旁边弯开，而不是把它推回去。"},{"en":"decline of life, shortened to decline, draws old age as the last downhill stretch of a slope.","cn":"decline of life 缩略为 decline，把晚年画成一道坡最后的下行段。"}],"abstract":[{"en":"The core is departure from the horizontal: nothing breaks, the line simply stops being level.","cn":"核心是离开水平面：没有东西断裂，只是那条线不再平了。"},{"en":"The same bend is applied to quantity, body, empire, word form and social request.","cn":"同一个弯被用在数量、身体、帝国、词形和社会请求上。"},{"en":"So a falling rate, failing health, a fading empire, a case ending and a polite no are one tilt seen from five angles.","cn":"所以下滑的比率、衰退的健康、衰落的帝国、格词尾和礼貌的拒绝，是同一个倾斜的五个侧面。"}]},"examples":[{"en":"Demand for printed newspapers has declined for years.","cn":"多年来，纸质报纸的需求一直在下降。"},{"en":"She declined the job offer because it required too much travel.","cn":"她谢绝了那份工作，因为它要求频繁出差。"},{"en":"The decline of the small farm changed the whole valley.","cn":"小农场的衰落改变了整个山谷。"}],"dict_mnemonic":{"note":"拆分联想 · 非词源","text":"de（向下）+ cline（倾斜）——地面向下倾斜，人只能一路往下走 → decline 下降、衰退、婉拒","word":"decline"},"root":"源自拉丁语 declinare“降低、偏离、弯开、变格”，由 de-“离开”+ clinare“弯”构成，核心是“从水平线上弯下去”。","sensesIntro":{"en":"Nine senses of decline, all cut from one slope: a rate bends down, a body loses height, a system sinks, a word form bends, the sun slants, and a polite no steps aside.","cn":"decline 的九个义项都从同一道坡上切下：比率向下弯、身体失去高度、体系下沉、词形弯开、太阳西斜，以及礼貌的拒绝侧身让开。"},"semanticMap":{"core":{"en":"CORE IMAGE: ground that was level tilts, and everything on it moves lower.","cn":"核心意象：原本水平的地面向下倾斜，上面的东西随之下行。"},"chain":["STAND ON LEVEL GROUND","BEND FROM THE LEVEL","SLANT DOWNWARD","SINK LOWER","LOSE POWER","TURN ASIDE FROM A REQUEST"],"branches":[{"senses":"S01 · S07","en":"MEASURED DOWNWARD: a rate falls, and the noun names the size of the drop.","cn":"可测量的下行：比率下降，名词命名这次下降的幅度。"},{"senses":"S02 · S08","en":"THE BODY'S SLOPE: powers fade in a person, and life's last stretch is called decline.","cn":"身体的坡：人的能力衰退，人生最后一段被称为晚年。"},{"senses":"S03 · S09","en":"WHOLE SYSTEMS LOWER: a civilization loses vigor, and the noun names the worsened state.","cn":"整个体系下行：文明失去活力，名词命名恶化后的状态。"},{"senses":"S04 · S05","en":"BENDING ASIDE: a polite refusal and a grammatical case both turn away from the straight line.","cn":"侧弯让开：礼貌的拒绝与语法中的格，都从直线上转开。"},{"senses":"S06","en":"THE PHYSICAL CORE: the sun slants down without falling.","cn":"物理核心：太阳只是向下斜，并没有坠落。"}]},"affixes":{"intro":{"en":"Decline is de- plus clinare. Its family shows the prefixes de-, in- and re-, the root clin- 'lean, bend', and the suffixes -ation, -sion and -able.","cn":"decline 是 de- 加 clinare。它的词族展示前缀 de-、in-、re-，词根 clin-“倾、弯”，以及后缀 -ation、-sion、-able。"},"latinIntro":{"en":"Latin clinare 'to bend' yields declinare, inclinare and reclinare; their English descendants are decline, incline and recline, with declension and declination as nouns.","cn":"拉丁语 clinare“弯”给出 declinare、inclinare、reclinare；它们的英语后代是 decline、incline、recline，名词则是 declension 与 declination。"},"items":[{"word":"decline","structure":"de- (down, from) + clinare (to bend)","meaning":"to go down; to weaken; to refuse politely","meaningCN":"下降；衰退；婉拒（de- 向下，clinare 弯）","example":"Profits declined for the third year.","exampleCN":"利润连续第三年下降。"},{"word":"declination","structure":"de- + clinare + -ation (noun of action)","meaning":"a downward slope; a deviation; an angle","meaningCN":"倾斜；偏差；偏角（-ation 构成动作名词）","example":"The declination of the needle was measured at noon.","exampleCN":"指针的偏角是在正午测量的。"},{"word":"declension","structure":"de- + clinare + -sion (noun)","meaning":"the set of case forms of a word","meaningCN":"变格；词形变化（-sion 构成名词）","example":"This noun belongs to the third declension.","exampleCN":"这个名词属于第三变格。"},{"word":"declinable","structure":"decline + -able (capable of)","meaning":"able to be inflected in cases","meaningCN":"可变格的（-able 表能够）","example":"In Latin, most nouns are declinable.","exampleCN":"在拉丁语中，大多数名词可变格。"},{"word":"indeclinable","structure":"in- (not) + declinable","meaning":"not changed in form for case","meaningCN":"不变格的（in- 表否定）","example":"Some pronouns are indeclinable.","exampleCN":"有些代词是不变格的。"},{"word":"incline","structure":"in- (toward) + clinare (to bend)","meaning":"to lean toward; to tend","meaningCN":"倾向；倾斜（in- 朝向 + 弯）","example":"I incline to the second option.","exampleCN":"我倾向于第二个选项。"},{"word":"recline","structure":"re- (back) + clinare (to bend)","meaning":"to lean back","meaningCN":"向后靠；斜倚（re- 向后 + 弯）","example":"He reclined on the sofa and closed his eyes.","exampleCN":"他斜靠在沙发上，闭上了眼睛。"},{"word":"declining","structure":"decline + -ing (participle or adjective)","meaning":"falling; weakening","meaningCN":"下降的；衰退中的（-ing 构成分词或形容词）","example":"The declining birth rate worries planners.","exampleCN":"下降的出生率让规划者担忧。"},{"word":"declined","structure":"decline + -ed (past participle)","meaning":"went down; was refused","meaningCN":"已下降的；被谢绝的（-ed 构成过去分词）","example":"The declined offer was never discussed again.","exampleCN":"那个被谢绝的提议再未被谈起。"}],"latinEntries":[{"word":"declinare","structure":"de- + clinare","meaning":"to lower; deviate; bend from; inflect","meaningCN":"降低；偏离；弯开；变格"},{"word":"clinare","structure":"clinare (verb)","meaning":"to bend, lean","meaningCN":"弯；倾"},{"word":"declinatio","structure":"declinare + -tio","meaning":"a bending away; inflection","meaningCN":"弯开；变格"}]}},{"word":"define","ipa_uk":"/dɪˈfaɪn/","ipa_us":"/dɪˈfaɪn/","definition_zh":"给……下定义；界定；规定；使轮廓清晰","definition_en":"to state exactly what something is or means, and so mark its limits","core_image":"拿粉笔在地上画一道闭合的线，把一样东西圈在里头，线外就不算它","scene":"The editor leans over the draft and says: Define your terms before you make the argument.","sceneCN":"这里 define 是「给词语下定义」（第 1 个义项：说明一个词的确切含义）；句意：在展开论证之前，先把你用的术语定义清楚。画面里有稿纸、红笔和编辑的手。","pos":[{"tag":"vt.","zh":"给……下定义；界定；规定；使轮廓清晰"}],"collocations":[{"phrase":"define a term","zh":"给术语下定义"},{"phrase":"define the problem","zh":"界定问题"},{"phrase":"clearly defined","zh":"界定清楚的"},{"phrase":"define the boundary","zh":"划定边界"},{"phrase":"define somebody's role","zh":"规定某人的职责"}],"forms":[{"label":"三单","form":"defines"},{"label":"过去式","form":"defined"},{"label":"过去分词","form":"defined"},{"label":"现在分词","form":"defining"}],"derivatives":[{"word":"definition","pos":"n.","zh":"定义；释义；清晰度"},{"word":"definitive","pos":"adj.","zh":"决定性的；最终的；权威的"},{"word":"definable","pos":"adj.","zh":"可定义的"},{"word":"indefinite","pos":"adj.","zh":"不确定的；不限定的"},{"word":"redefine","pos":"v.","zh":"重新定义；重新界定"}],"senses":[{"no":"01","title":"Say what a word means: draw its edge","titleCN":"释义：给一个词画出边界","definition":"to state the exact meaning of a word or phrase","definitionCN":"说明单词或短语的确切含义","example":"The dictionary defines 'home' as the place where one lives.","exampleCN":"词典把 home 定义为一个人居住的地方。","why":"Late 14c. records define as 'state the signification of, explain what is meant by'. Latin definire is de- 'completely' plus finire 'to bound': a meaning is fixed by drawing a line around it.","whyCN":"14 世纪后期记录 define 为“说明其含义、解释所指”。拉丁语 definire 是 de-“彻底”加 finire“划界”：给一个意义画上边界，它就固定下来。"},{"no":"02","title":"Make the problem exact: cut away the vague part","titleCN":"界定问题：把含糊的部分切掉","definition":"to state precisely what a problem, goal, or situation consists of","definitionCN":"精确说明问题、目标或状况包含什么","example":"The first task is to define the problem before proposing a solution.","exampleCN":"第一步是在提出方案之前先把问题界定清楚。","why":"A problem left vague has no edges, so no solution can fit it. Defining it borrows the boundary image: the unclear part is cut off until only the real question remains.","whyCN":"含糊的问题没有边，方案就套不上去。define 借用了划界的意象：把不清楚的部分切掉，只剩真正的问题。"},{"no":"03","title":"Fix the limit: where one thing ends and another begins","titleCN":"划定界限：一物到此为止的地方","definition":"to mark or fix the boundary or limits of something","definitionCN":"标出或确定某事物的边界或范围","example":"A low fence defines the line between the two gardens.","exampleCN":"一道矮篱笆划出了两个花园之间的界线。","why":"From c. 1400 define meant 'determine, declare, or mark the limit of'. This is the literal core: finis is a boundary, and definire is to put the boundary all the way around.","whyCN":"从约 1400 年起，define 意为“确定、宣告或标出……的界限”。这是字面核心：finis 是边界，definire 就是把边界整圈放好。"},{"no":"04","title":"Set the terms: duties written into a frame","titleCN":"规定：把职责写进框里","definition":"to set out officially what a role, rule, or agreement includes","definitionCN":"正式规定某一职责、规则或协议包含什么","example":"The contract defines what counts as a breach.","exampleCN":"合同规定了什么算违约。","why":"A contract or job description works only if its edges are fixed. The legal use keeps the old 'establish authoritatively' sense recorded in late 14c.: the limit is not described but imposed.","whyCN":"合同或岗位说明只有在边界固定时才管用。法律用法保留了 14 世纪后期记录的“权威地确立”之义：界限不是被描述出来，而是被规定下来。"},{"no":"05","title":"Be the essence: what marks a thing as itself","titleCN":"成为本质特征：把一物标记为它自己","definition":"to be the quality or feature that makes something recognizably itself","definitionCN":"成为使某物可被认出是其本身的性质或特征","example":"Her patience defines the way she teaches.","exampleCN":"她的耐心塑造了她教学的方式。","why":"If a boundary marks what belongs inside, then the feature that holds a thing inside its own shape is what defines it. The word shifts from the line drawn to the trait doing the drawing.","whyCN":"如果边界标出什么属于圈内，那么把一物维持在自己形状里的那个特征，就是 define 它的东西。词义从“被画的线”转到“画线的那项特质”。"},{"no":"06","title":"Stand out against the sky: an outline made clear","titleCN":"轮廓凸显：在背景上显出清晰边线","definition":"to show the outline or shape of something clearly against a background","definitionCN":"在背景前清晰地显出某物的轮廓或形状","example":"The pine trees were sharply defined against the evening sky.","exampleCN":"松树在暮色天空的映衬下轮廓分明。","why":"A shape becomes visible when its edge separates from what lies behind it. The same boundary that fixes a meaning fixes a silhouette: define is what makes an outline readable.","whyCN":"当一个形状的边线与背后的东西分开，它就变得可见。固定意义的同一条边界，也固定轮廓：define 就是让轮廓变得可读。"},{"no":"07","title":"Code: give a name a fixed value","titleCN":"编程：给一个名字定下取值","definition":"in computing, to set the type, name, or value of a variable, function, or constant","definitionCN":"计算机中指设定变量、函数或常量的类型、名称或取值","example":"You must define the variable before you use it.","exampleCN":"使用变量之前必须先定义它。","why":"A program cannot use a name whose limits are unknown. Defining a variable is the old act of fixing a boundary, moved into memory: the name is given exactly one range of values.","whyCN":"程序无法使用一个范围未知的名字。定义变量就是把古老的“划定边界”搬进内存：给这个名字指定唯一一段取值。"},{"no":"08","title":"Grammar: a clause that draws the referent tight","titleCN":"语法：把所指圈紧的限制性从句","definition":"in grammar, of a relative clause, to identify exactly which person or thing is meant","definitionCN":"语法上指关系从句限定所指，明确是哪一个","example":"In 'the book that I lost', the clause defines which book is meant.","exampleCN":"在 the book that I lost 中，这个从句限定了指的是哪一本书。","why":"A defining clause narrows the noun to one referent, exactly as a fence narrows a field. Grammar borrowed the boundary sense and made it syntactic: the clause draws the line inside the sentence.","whyCN":"限制性从句把名词缩小到唯一所指，正如篱笆把田缩小。语法借用了划界义，并把它变成句法：从句在句子内部画出那条线。"},{"no":"09","title":"Define yourself: draw a line between you and the rest","titleCN":"自我定位：在自己与其余之间画一条线","definition":"to establish one's own identity or position, especially in relation to others","definitionCN":"确立自己的身份或立场，尤指相对于他人而言","example":"She defined herself as an artist, not a critic.","exampleCN":"她把自己定位为艺术家，而不是评论家。","why":"The boundary image turns inward: to define oneself is to draw a line between who one is and who one is not. Identity is named by the same act of separation that fixes a meaning.","whyCN":"划界的意象转向内部：define oneself 就是在“自己是谁”与“自己不是谁”之间画一条线。身份由同一种分离动作命名，正如意义被固定。"}],"etymology":{"intro":{"en":"Define is Latin 'to put a boundary all the way around'. The word starts with a physical limit, then names the act of stating a meaning, and finally the clear outline of a thing.","cn":"define 是拉丁语“把边界整圈放好”。这个词从物理界限出发，然后命名说明意义的动作，最后指一物清晰的轮廓。"},"items":[{"era":"LATIN","en":"Finis meant 'boundary, end, limit', figuratively 'highest point'. Its own origin is unknown; etymologists only suggest a possible link to figere 'to fasten', which is not established.","cn":"finis 意为“边界、终点、限度”，比喻义为“顶点”。它本身的来源不明，词源学家只提出可能与 figere“固定”有关，但未获确立。"},{"era":"LATIN","en":"Definire meant 'to limit, determine, explain', from de- 'completely' plus finire 'to bound, limit'. The prefix makes the enclosing total rather than partial.","cn":"definire 意为“限制、确定、解释”，由 de-“彻底”加 finire“划界、限制”构成。前缀使围合成为整圈的，而不是部分的。"},{"era":"OLD FRENCH","en":"Defenir and definir meant 'to finish, conclude, come to an end; define, determine with precision'. The 'finish' sense shows how close a boundary is to an ending.","cn":"defenir 与 definir 意为“结束、收尾、走到尽头；定义、精确确定”。“结束”这一层说明边界与终点有多近。"},{"era":"LATE 14c. ENGLISH","en":"The verb appears as 'to specify; to fix or establish authoritatively', and of words, 'state the signification of, explain what is meant by'.","cn":"动词出现，意为“明确规定；权威地确立”，用于词语时则是“说明其含义、解释所指”。"},{"era":"c. 1400 ENGLISH","en":"Define also comes to mean 'determine, declare, or mark the limit of', which keeps the physical boundary visible in the modern word.","cn":"define 也转而意为“确定、宣告或标出……的界限”，让物理边界在现代词里仍然可见。"},{"era":"ORIGIN UNCERTAIN","en":"The chain stops at Latin finis. No written record establishes an earlier root, so the deepest step is marked source uncertain and no PIE form is asserted.","cn":"这条链停在拉丁语 finis。没有书面记录能确立更早的词根，所以最深层标为“来源不确定”，也不断言任何原始印欧语形式。"}]},"similar":{"note":{"en":"The first group is chosen for spelling and sound, the second for meaning, so that form and sense stay separate.","cn":"第一组按拼写和读音挑选，第二组按词义挑选，这样词形和词义不会混在一起。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"definite","ipa":"/ˈdefɪnət/","tag":"same family, adjective","definition":"fixed, clear and certain. It is the adjective built on the same definit- stem.","definitionCN":"确定的；明确的。它是同一 definit- 词干构成的形容词。"},{"word":"refine","ipa":"/rɪˈfaɪn/","tag":"prefix swap","definition":"to make something purer or more exact. It swaps de- for re- and keeps the fin- root.","definitionCN":"精炼；使精确。它把 de- 换成 re-，保留 fin- 词根。"},{"word":"deficit","ipa":"/ˈdefɪsɪt/","tag":"near spelling","definition":"the amount by which money spent exceeds money received. It shares the def- opening but not the fin- root.","definitionCN":"赤字；亏损。它同样以 def- 开头，但词根不是 fin-。"}]},{"heading":"NEAR MEANING","entries":[{"word":"specify","ipa":"/ˈspesɪfaɪ/","tag":"name exactly","definition":"to state something exactly and in detail. It matches sense 02 and 04.","definitionCN":"明确规定；详述。它对应第 2、4 义。"},{"word":"describe","ipa":"/dɪˈskraɪb/","tag":"say what it is like","definition":"to say what someone or something is like. It gives features rather than a boundary.","definitionCN":"描述。它给出特征，而不是边界。"},{"word":"clarify","ipa":"/ˈklærɪfaɪ/","tag":"make clear","definition":"to make something easier to understand. It removes fog but does not fix limits.","definitionCN":"澄清。它驱散迷雾，但不固定界限。"},{"word":"demarcate","ipa":"/dɪˈmɑːkeɪt/","tag":"mark a boundary","definition":"to mark the limits of something. It is the closest word to the literal sense 03.","definitionCN":"划界。它最贴近第 3 义的字面用法。"},{"word":"characterize","ipa":"/ˈkærəktəraɪz/","tag":"mark the nature","definition":"to describe the distinctive nature of something. It matches the essence sense 05.","definitionCN":"刻画特征。它对应第 5 义的本质用法。"}]}]},"mnemonics":{"normalIntro":{"en":"These links are real: de- plus finis 'boundary', the finite and infinite family, and the legal phrase define the limits.","cn":"这些联想都是真实的：de- 加 finis“边界”、finite 与 infinite 词族，以及法律短语 define the limits。"},"normal":[{"en":"define = de- 'completely' + finire 'to bound': to define is to put a fence entirely around a meaning.","cn":"define = de-“彻底”+ finire“划界”：下定义就是给一个意义围上整圈篱笆。"},{"en":"The fin- root also gives finite, infinite, confine and finish: every one of them is about an end or a border.","cn":"fin- 词根还给出 finite、infinite、confine、finish：每一个都与终点或边界有关。"},{"en":"A contract defines duties the way a fence defines a garden: it says where yours stops.","cn":"合同规定职责，正如篱笆划定花园：它说明你的范围到哪儿为止。"},{"en":"A silhouette is defined against the sky because its edge separates from what is behind it.","cn":"轮廓能在天空前显现，是因为它的边线与背后的东西分开了。"},{"en":"To define yourself is to draw the same line inward: this is me, and that is not.","cn":"define yourself 是把同一条线画向内部：这是我，那不是我。"}],"abstract":[{"en":"The core operation is enclosure: before a thing can be known, its edge must be drawn.","cn":"核心动作是围合：一样东西要被认识，先得画出它的边。"},{"en":"The line is applied to meaning, to problems, to duties, to silhouettes, to code and to the self.","cn":"这条线被用在意义、问题、职责、轮廓、代码和自我上。"},{"en":"So a dictionary entry, a clear problem, a contract, an outline and a variable declaration are one act of drawing a border.","cn":"所以词典释义、清晰的问题、合同、轮廓和变量声明，都是同一个画边界的动作。"}]},"examples":[{"en":"The report defines poverty as income below half the median.","cn":"报告把贫困定义为收入低于中位数的一半。"},{"en":"A good photograph defines the shape of a face with light and shadow.","cn":"一张好照片用光影勾勒出脸的轮廓。"},{"en":"The new law defines the powers of the agency.","cn":"新法律规定了该机构的权限。"}],"dict_mnemonic":{"note":"拆分联想 · 非词源","text":"de（底）+ fine（界限）——把底线画出来，范围就定死了 → define 下定义、界定","word":"define"},"root":"源自拉丁语 definire“限制、确定、解释”，由 de-“彻底”+ finire“划界”构成，finis 意为“边界、终点”，核心是“把边界整圈画好”。","sensesIntro":{"en":"Nine senses of define, all one act of enclosure: a word gets its meaning, a problem its shape, a duty its frame, a figure its outline, a variable its value, and a person an identity.","cn":"define 的九个义项都是同一个围合动作：词得到意义，问题得到形状，职责得到框架，身影得到轮廓，变量得到取值，人得到身份。"},"semanticMap":{"core":{"en":"CORE IMAGE: a closed line drawn around something, so that inside and outside are settled.","cn":"核心意象：围绕一物画一条闭合的线，使内外分明。"},"chain":["DRAW A LINE","FIX THE LIMIT","SAY WHAT IT MEANS","MAKE IT EXACT","MARK ITS CHARACTER","SHOW THE OUTLINE"],"branches":[{"senses":"S01 · S03","en":"THE LINE ITSELF: a word's meaning and a field's boundary are both fixed by an edge.","cn":"线本身：词的意义与田地的边界，都靠一条边固定。"},{"senses":"S02 · S04","en":"THE FRAME THAT HOLDS: a problem and a contract become usable once their edges are fixed.","cn":"承住的框架：问题与合同一旦边界固定，就能派上用场。"},{"senses":"S05 · S09","en":"IDENTITY DRAWN: the trait that marks a thing, and the line one draws around oneself.","cn":"画出的身份：标记一物的特质，以及围绕自己画的那条线。"},{"senses":"S06","en":"THE VISIBLE EDGE: an outline appears where shape separates from background.","cn":"可见的边：形状与背景分开之处，轮廓就出现了。"},{"senses":"S07 · S08","en":"THE EDGE IN CODE AND GRAMMAR: a name gets one range of values, a clause narrows to one referent.","cn":"代码与语法中的边：名字得到唯一一段取值，从句缩小到唯一所指。"}]},"affixes":{"intro":{"en":"Define is de- plus finire. Its family shows the prefixes de-, in-, re-, con- and the root fin- 'boundary, end', with suffixes -ition, -ive and -able.","cn":"define 是 de- 加 finire。它的词族展示前缀 de-、in-、re-、con-，词根 fin-“边界、终点”，以及后缀 -ition、-ive、-able。"},"latinIntro":{"en":"Latin finis 'boundary, end' and finire 'to limit' are the base of definire, definitio and confinium; English draws define, definition, finite and confine from the same stem.","cn":"拉丁语 finis“边界、终点”与 finire“限制”是 definire、definitio、confinium 的基础；英语从同一词干取出 define、definition、finite、confine。"},"items":[{"word":"define","structure":"de- (completely) + finire (to bound)","meaning":"to state the meaning; to fix the limits","meaningCN":"下定义；界定（de- 彻底 + 划界）","example":"The rules define what counts as cheating.","exampleCN":"规则界定了什么算作弊。"},{"word":"definition","structure":"de- + finit- (bound) + -ion (noun)","meaning":"a statement of meaning; clearness of outline","meaningCN":"定义；清晰度（-ion 构成名词）","example":"The definition was too narrow to apply.","exampleCN":"这个定义太窄，无法适用。"},{"word":"definitive","structure":"definit- + -ive (adjective)","meaning":"final and authoritative","meaningCN":"决定性的；权威的（-ive 构成形容词）","example":"The court gave a definitive ruling.","exampleCN":"法院作出了最终裁定。"},{"word":"definable","structure":"define + -able (capable of)","meaning":"able to be defined","meaningCN":"可定义的（-able 表能够）","example":"The concept is definable in simple terms.","exampleCN":"这个概念可以用简单的说法定义。"},{"word":"indefinite","structure":"in- (not) + definite","meaning":"not fixed or clearly bounded","meaningCN":"不确定的；无限期的（in- 表否定）","example":"The project was postponed for an indefinite period.","exampleCN":"项目被无限期推迟。"},{"word":"redefine","structure":"re- (again) + define","meaning":"to define again in a new way","meaningCN":"重新定义（re- 表再次）","example":"The company redefined its market.","exampleCN":"公司重新定义了自己的市场。"},{"word":"confine","structure":"con- (together) + finis (boundary)","meaning":"to keep within limits","meaningCN":"限制；禁闭（con- 共同 + 边界）","example":"Please confine your remarks to the topic.","exampleCN":"请把你的发言限制在主题范围内。"},{"word":"finite","structure":"finire (to limit) + -ite (adjective)","meaning":"having limits; not infinite","meaningCN":"有限的（-ite 构成形容词）","example":"The planet has finite resources.","exampleCN":"这颗行星的资源是有限的。"},{"word":"infinite","structure":"in- (not) + finite","meaning":"without limits","meaningCN":"无限的（in- 表否定）","example":"The sequence continues to infinity.","exampleCN":"这个数列一直延伸到无穷。"},{"word":"finish","structure":"finis via Latin finire and Old French finir","meaning":"to bring or come to an end","meaningCN":"结束；完成（由 finis 终点而来）","example":"She finished the report at midnight.","exampleCN":"她在午夜完成了报告。"}],"latinEntries":[{"word":"finis","structure":"finis (noun)","meaning":"boundary, end, limit","meaningCN":"边界；终点；限度"},{"word":"finire","structure":"finis + -ire (verb)","meaning":"to bound, limit; to end","meaningCN":"划界；限制；结束"},{"word":"definitio","structure":"definire + -tio","meaning":"a defining; a boundary","meaningCN":"定义；界限"}]}},{"word":"definite","ipa_uk":"/ˈdefɪnət/","ipa_us":"/ˈdefənət/","definition_zh":"确定的；明确的；有固定界限的；（语法）定冠词的","definition_en":"fixed, clear, and not open to doubt, with limits that are known","core_image":"一圈已经画好的线，线内线外清清楚楚，没有一块模糊地带","scene":"She checks her calendar twice and says: I need a definite answer by Friday.","sceneCN":"这里 definite 是「明确的、确定的」（第 1、2 个义项：不再含糊、可以依赖的答复）；句意：周五之前我需要一个明确的答复。画面里有日历、手机和写满备注的便签。","pos":[{"tag":"adj.","zh":"确定的；明确的；有限的；（语法）定冠词的"}],"collocations":[{"phrase":"a definite answer","zh":"明确的答复"},{"phrase":"definite plans","zh":"确定的计划"},{"phrase":"a definite improvement","zh":"明显的改善"},{"phrase":"the definite article","zh":"定冠词"},{"phrase":"definite and indefinite","zh":"定与不定"}],"forms":[{"label":"比较级","form":"more definite"},{"label":"最高级","form":"most definite"}],"derivatives":[{"word":"definitely","pos":"adv.","zh":"肯定地；明确地"},{"word":"definiteness","pos":"n.","zh":"确定性；明确性"},{"word":"definition","pos":"n.","zh":"定义；清晰度"},{"word":"definitive","pos":"adj.","zh":"决定性的；最终的"},{"word":"indefinite","pos":"adj.","zh":"不确定的；无限期的"}],"senses":[{"no":"01","title":"Certain: no doubt left","titleCN":"确定无疑：没有疑问剩下","definition":"known for certain; not doubtful","definitionCN":"确知的；毫无疑问的","example":"There is no definite proof that he was there.","exampleCN":"没有确凿证据证明他在场。","why":"Definite entered English c. 1500 as 'fixed, established; certain, precise'. A thing is certain when its boundary is fixed: nothing outside the line can still be claimed.","whyCN":"definite 于约 1500 年进入英语，意为“固定的、确立的；确定的、精确的”。一物确定，就是它的边界已经固定：线外的东西再也不能被算进来。"},{"no":"02","title":"Precise: every edge legible","titleCN":"明确：每条边都看得清","definition":"clear and exact in meaning or detail","definitionCN":"含义或细节清楚而准确","example":"The instructions were definite: leave the key under the mat.","exampleCN":"指示很明确：把钥匙留在门垫下面。","why":"The 1550s add 'having fixed limits'. Precision is what a fixed limit looks like from the inside: each part knows where it stops, so nothing has to be guessed.","whyCN":"16 世纪 50 年代又添“有固定界限”一义。精确就是固定边界从内部看的样子：每一部分都知道自己到哪儿为止，因此不必猜。"},{"no":"03","title":"Bounded: the line is not movable","titleCN":"有限定：这条线不能挪","definition":"having limits that are fixed and known","definitionCN":"具有固定且已知的界限","example":"The study covers a definite period of ten years.","exampleCN":"这项研究覆盖明确的十年期限。","why":"This is the literal Latin sense: definitus is the past participle of definire, 'to bound'. The adjective first names a thing that has been enclosed by a boundary.","whyCN":"这是拉丁语字面义：definitus 是 definire“划界”的过去分词。这个形容词最初命名一件被边界围住的东西。"},{"no":"04","title":"The definite article: the one already picked out","titleCN":"定冠词：已经圈定的那一个","definition":"in grammar, the article 'the', used for a specific thing already identified","definitionCN":"语法上的定冠词 the，用于已确定的那一特定事物","example":"English uses the definite article in 'the book on the table'.","exampleCN":"英语在 the book on the table 中使用定冠词。","why":"Grammar adopted the term in 1727. A definite article marks a noun as already bounded to one known referent, unlike a or an, which leaves the boundary open.","whyCN":"语法在 1727 年采用这个术语。定冠词把名词标为已经圈定到某个已知所指，而不定冠词 a/an 则把边界留着不封口。"},{"no":"05","title":"Firm: a yes that will not bend","titleCN":"坚定：一个不会弯掉的“是”","definition":"firm and unwavering in intention or commitment","definitionCN":"意图或承诺坚定、不动摇","example":"He gave a definite no and would not discuss it further.","exampleCN":"他给了一个坚定的“不”，不愿再谈。","why":"A commitment with fixed limits cannot be stretched by pressure. Definite shifts from what is known to what is willed: the decision has the same hard edge as a measured fact.","whyCN":"有固定界限的承诺不会被压力拉长。definite 从“已知”转到“意志”：决定与测得的事实一样，有一条硬的边。"},{"no":"06","title":"Plain to see: a difference you cannot miss","titleCN":"明显：一眼就看得出的差别","definition":"clearly noticeable or pronounced","definitionCN":"明显可察的；显著的","example":"There has been a definite improvement in her writing.","exampleCN":"她的写作有了明显的进步。","why":"When a change is definite, its outline stands out from the background of ordinary variation. The same legibility that makes a shape clear makes an improvement unmistakable.","whyCN":"当变化是 definite 的，它的轮廓就从日常波动的背景里凸显出来。让形状清晰的同一种可读性，也让进步变得不容看错。"},{"no":"07","title":"Mathematics: a value that is fixed","titleCN":"数学：取定不变的量","definition":"having a fixed value, as in a definite quantity or a definite integral","definitionCN":"具有固定取值的，如定值或定积分","example":"A definite integral is taken between two fixed limits.","exampleCN":"定积分是在两个固定限之间求取的。","why":"Mathematics keeps the oldest image in its purest form: a definite integral is literally bounded by two limits. Nothing vague can enter between them.","whyCN":"数学把最古老的意象保留得最纯：定积分字面上就是被两个限围住。在这两个限之间，任何含糊的东西都进不来。"},{"no":"08","title":"Specific: this one, at this known point","titleCN":"特定：就是这一个，在已知的那一点","definition":"particular and identified exactly, as in at a definite time or place","definitionCN":"特定的、被精确指明的，如确定的时间或地点","example":"The meeting has no definite time or place yet.","exampleCN":"会议还没有确定的时间和地点。","why":"To specify is to point to one item inside the boundary. A definite time is not any time but the one marked on the line, which is why the word pairs naturally with dates and places.","whyCN":"指定就是在边界内点出某一项。确定的时间不是任何时间，而是线上被标出的那一个，所以这个词天然与日期、地点搭配。"},{"no":"09","title":"Logic: the description that picks out one thing","titleCN":"逻辑：只圈定唯一对象的摹状词","definition":"in logic, of a description, picking out exactly one object, as in 'the definite description'","definitionCN":"逻辑学中摹状词精确指称唯一对象，如“限定摹状词”","example":"Russell analysed 'the present king of France' as a definite description.","exampleCN":"罗素把“当今法国国王”分析为限定摹状词。","why":"Logic made the boundary explicit: a definite description claims there is exactly one thing inside the circle and no other. The article 'the' carries that claim.","whyCN":"逻辑学把边界说得明白：限定摹状词声称圈内恰好有一个东西，别无其他。冠词 the 就承担这个断言。"}],"etymology":{"intro":{"en":"Definite is the past participle of the Latin verb that means 'to bound'. It names whatever has had a line drawn around it, and so is sure, precise, limited and, in grammar, pointed to by the.","cn":"definite 是拉丁语“划界”动词的过去分词。它命名一切被画上边界的东西，因此确定、精确、有限，语法上则由 the 指出来。"},"items":[{"era":"LATIN","en":"Finis meant 'boundary, end, limit'. Its origin is unknown; a link to figere 'to fasten' has been suggested but never established.","cn":"finis 意为“边界、终点、限度”。它的来源不明；与 figere“固定”的联系曾被提出，但从未确立。"},{"era":"LATIN","en":"Definire 'to limit, determine, explain' comes from de- 'completely' plus finire 'to bound'. Its past participle definitus means 'defined, bounded, limited'.","cn":"definire“限制、确定、解释”来自 de-“彻底”加 finire“划界”。其过去分词 definitus 意为“已界定、有界、有限”。"},{"era":"c. 1500 ENGLISH","en":"Definite appears as 'fixed, established; certain, precise'. This sense still dominates: the boundary is fixed, so the answer can be trusted.","cn":"definite 出现，意为“固定的、确立的；确定的、精确的”。这一义至今占主导：边界已定，所以答案可信。"},{"era":"1550s ENGLISH","en":"A second sense, 'having fixed limits', is recorded. It keeps the Latin participle visible: the thing is literally bounded.","cn":"第二个义项“有固定界限”得到记录。它让拉丁语分词仍然可见：这东西字面上是被围住的。"},{"era":"1727 ENGLISH","en":"Grammar adopts definite for articles that mark a known referent, giving the pair definite and indefinite article.","cn":"语法采用 definite 指标记已知所指的冠词，于是有了定冠词与不定冠词这一对。"},{"era":"ORIGIN UNCERTAIN","en":"The chain stops at finis 'boundary'. No written record establishes anything earlier, so the deepest step is marked source uncertain and no root is invented.","cn":"这条链停在 finis“边界”。没有书面记录能确立更早的来源，所以最深层标为“来源不确定”，也不编造词根。"}]},"similar":{"note":{"en":"The first group is chosen for spelling and sound, the second for meaning, so that form and sense stay separate.","cn":"第一组按拼写和读音挑选，第二组按词义挑选，这样词形和词义不会混在一起。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"definitive","ipa":"/dɪˈfɪnətɪv/","tag":"same stem, different job","definition":"final, authoritative and not to be changed. Definite means clear; definitive means settling the matter.","definitionCN":"决定性的；最终的。definite 是“清楚”，definitive 是“把事情定下来”。"},{"word":"infinite","ipa":"/ɪnˈfɪnət/","tag":"negative prefix","definition":"without limits. It is in- 'not' plus finite, the direct opposite of bounded.","definitionCN":"无限的。它是 in-“不”加 finite，正与“有界”相反。"},{"word":"defiant","ipa":"/dɪˈfaɪənt/","tag":"near spelling","definition":"openly refusing to obey. It looks close to definite but comes from a different root.","definitionCN":"公然违抗的。它拼写接近 definite，但词根不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"certain","ipa":"/ˈsɜːtn/","tag":"no doubt","definition":"sure beyond question. It matches sense 01 but says nothing about limits.","definitionCN":"确定的。它对应第 1 义，但不涉及界限。"},{"word":"clear","ipa":"/klɪə(r)/","tag":"easy to understand","definition":"easy to see or understand. It covers the precision of sense 02.","definitionCN":"清楚的。它覆盖第 2 义的精确性。"},{"word":"precise","ipa":"/prɪˈsaɪs/","tag":"exact","definition":"exact down to small details. It is sharper than definite about measurement.","definitionCN":"精确的。在测量方面，它比 definite 更锐利。"},{"word":"explicit","ipa":"/ɪkˈsplɪsɪt/","tag":"stated openly","definition":"stated plainly and leaving nothing implied. It matches the clear-statement side of definite.","definitionCN":"明确的；直言的。它对应 definite 明白陈述的一面。"},{"word":"specific","ipa":"/spəˈsɪfɪk/","tag":"this one","definition":"particular and clearly identified. It matches sense 08.","definitionCN":"特定的；具体的。它对应第 8 义。"}]}]},"mnemonics":{"normalIntro":{"en":"These links are real: definitus 'bounded', the definite article, and the definite/indefinite pair in grammar and mathematics.","cn":"这些联想都是真实的：definitus“有界的”、定冠词，以及语法与数学中的定/不定配对。"},"normal":[{"en":"definite = de- 'completely' + finis 'boundary': what is completely bounded cannot be vague.","cn":"definite = de-“彻底”+ finis“边界”：被彻底围住的东西不可能含糊。"},{"en":"The definite article 'the' says the noun is already bounded to one known thing.","cn":"定冠词 the 表示这个名词已经被圈定到某个已知的东西。"},{"en":"A definite integral is bounded by two limits, which is the Latin image in plain mathematics.","cn":"定积分被两个限围住，这就是拉丁意象在数学里的直白样子。"},{"en":"A definite no has the same hard edge as a definite proof: neither can be stretched.","cn":"一个坚定的“不”与一个确定的证据有同样的硬边：两者都拉不长。"},{"en":"A definite improvement has a visible outline against the background of ordinary days.","cn":"明显的进步在平常日子的背景上有清楚的轮廓。"}],"abstract":[{"en":"The core is a closed boundary: what lies inside is known, what lies outside is excluded.","cn":"核心是一条闭合的边界：线内的已知，线外的被排除。"},{"en":"The same boundary is read as certainty, precision, firmness, grammatical pointing and logical uniqueness.","cn":"同一条边界被读成确定、精确、坚定、语法指称和逻辑唯一性。"},{"en":"So a sure fact, a sharp instruction, a firm refusal and a 'the' are one ring seen from five sides.","cn":"所以确定的事实、明确的指示、坚定的拒绝和一个 the，是同一个圈的五面。"}]},"examples":[{"en":"We still have no definite date for the opening.","cn":"我们还没有确定的开幕日期。"},{"en":"There is a definite difference between the two samples.","cn":"两个样本之间有明显的差别。"},{"en":"The definite article changes how the noun is read.","cn":"定冠词会改变名词的解读方式。"}],"dict_mnemonic":{"note":"拆分联想 · 非词源","text":"de（底）+ fin（界限）+ ite——底线已经画好，范围清清楚楚 → definite 确定的、明确的","word":"definite"},"root":"源自拉丁语 definitus“已界定、有界的”，是 definire“划界、确定”的过去分词，由 de-“彻底”+ finis“边界”构成，核心是“边界已经画好”。","sensesIntro":{"en":"Nine senses of definite, all read from one closed boundary: certainty, precision, fixed limits, the article 'the', firm will, visible change, a fixed value, a particular point, and a logical description.","cn":"definite 的九个义项都从一条闭合边界读出：确定、精确、固定界限、冠词 the、坚定意志、可见变化、定值、特定之点，以及逻辑摹状词。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ring already drawn, with nothing vague left inside it.","cn":"核心意象：一圈已经画好，圈内不留任何含糊。"},"chain":["DRAW THE LINE","CLOSE THE RING","FIX THE LIMIT","REMOVE DOUBT","MAKE IT STAND OUT","POINT TO ONE"],"branches":[{"senses":"S01 · S05","en":"WHAT IS KNOWN AND WILLED: certain proof and a firm no both have a hard edge.","cn":"已知与意志：确定的证据与坚定的拒绝都有硬边。"},{"senses":"S02 · S06","en":"WHAT IS LEGIBLE: exact instructions and a visible improvement stand clear of the background.","cn":"可读之物：明确的指示与可见的进步，都从背景中清楚立出。"},{"senses":"S03 · S07","en":"THE MEASURED EDGE: fixed limits become a definite period and a definite integral.","cn":"被测量的边：固定界限变成确定期限与定积分。"},{"senses":"S04 · S09","en":"THE POINTED ONE: the article and the logical description both pick out exactly one.","cn":"被指出的那一个：冠词与逻辑摹状词都精确圈定唯一对象。"},{"senses":"S08","en":"THE MARKED SPOT: a definite time is one point on the line.","cn":"被标出的点：确定的时间是线上的一点。"}]},"affixes":{"intro":{"en":"Definite is the adjective of definire. Its family shows the root fin- 'boundary, end', the prefixes de-, in- and the suffixes -ite, -ly, -ness and -ition.","cn":"definite 是 definire 的形容词。它的词族展示词根 fin-“边界、终点”，前缀 de-、in-，后缀 -ite、-ly、-ness、-ition。"},"latinIntro":{"en":"Latin definitus 'bounded' is the participle behind definite; finis and finire also give definitive, finite and infinite through the same stem.","cn":"拉丁语 definitus“有界的”是 definite 背后的分词；finis 与 finire 还通过同一词干给出 definitive、finite、infinite。"},"items":[{"word":"definite","structure":"definit- (bounded) + -e (adjective)","meaning":"fixed, clear, certain","meaningCN":"确定的；明确的（源自“有界”）","example":"We need a definite answer today.","exampleCN":"我们今天需要一个明确的答复。"},{"word":"definitely","structure":"definite + -ly (adverb)","meaning":"certainly; without doubt","meaningCN":"肯定地；明确地（-ly 构成副词）","example":"I will definitely be there.","exampleCN":"我肯定会到。"},{"word":"definiteness","structure":"definite + -ness (quality noun)","meaning":"the quality of being fixed or clear","meaningCN":"确定性；明确性（-ness 构成名词）","example":"The definiteness of the rule left no room for argument.","exampleCN":"规则的确定性没有留下争辩空间。"},{"word":"definition","structure":"de- + finit- + -ion (noun)","meaning":"a statement of meaning; sharpness of outline","meaningCN":"定义；清晰度（-ion 构成名词）","example":"The photograph has great definition.","exampleCN":"这张照片的清晰度很高。"},{"word":"definitive","structure":"definit- + -ive (adjective)","meaning":"final and authoritative","meaningCN":"决定性的；最终的（-ive 构成形容词）","example":"This is the definitive history of the city.","exampleCN":"这是关于这座城市最权威的历史著作。"},{"word":"indefinite","structure":"in- (not) + definite","meaning":"not fixed; without a clear limit","meaningCN":"不确定的；无限期的（in- 表否定）","example":"The talks ended with an indefinite delay.","exampleCN":"会谈以无限期推迟告终。"},{"word":"define","structure":"de- (completely) + finire (to bound)","meaning":"to state the meaning; to fix limits","meaningCN":"下定义；界定（de- 彻底 + 划界）","example":"The law defines the term narrowly.","exampleCN":"法律对这个词作了狭义界定。"},{"word":"finite","structure":"finire (to limit) + -ite","meaning":"having limits","meaningCN":"有限的（-ite 构成形容词）","example":"Finite resources cannot fund infinite growth.","exampleCN":"有限的资源无法支撑无限的增长。"},{"word":"infinite","structure":"in- (not) + finite","meaning":"without limits","meaningCN":"无限的（in- 表否定）","example":"The sky seemed infinite.","exampleCN":"天空看上去无边无际。"}],"latinEntries":[{"word":"definitus","structure":"definire + -tus (past participle)","meaning":"defined, bounded, limited","meaningCN":"已界定的；有界的；有限的"},{"word":"definire","structure":"de- + finire","meaning":"to limit, determine, explain","meaningCN":"限制；确定；解释"},{"word":"finis","structure":"finis (noun)","meaning":"boundary, end, limit","meaningCN":"边界；终点；限度"}]}},{"word":"demonstrate","ipa_uk":"/ˈdemənstreɪt/","ipa_us":"/ˈdemənstreɪt/","definition_zh":"证明；论证；演示；表露；示威","definition_en":"to show something clearly, whether by evidence, by example, or by taking to the streets","core_image":"把一样东西举到众人眼前，伸手指着说：看这里","scene":"A teacher holds up a small circuit and says: Let me demonstrate how the switch closes the loop.","sceneCN":"这里 demonstrate 是「演示、示范」（第 3 个义项：一边操作一边讲解给人看）；句意：我来演示这个开关如何闭合回路。画面里有电路板、电池和围成一圈的学生。","pos":[{"tag":"vt.","zh":"证明；论证；演示；表露"},{"tag":"vi.","zh":"示威游行"}],"collocations":[{"phrase":"demonstrate that","zh":"证明……"},{"phrase":"demonstrate how","zh":"演示如何……"},{"phrase":"demonstrate against","zh":"示威反对"},{"phrase":"demonstrate a technique","zh":"示范一项技术"},{"phrase":"demonstrate commitment","zh":"表现出投入"}],"forms":[{"label":"三单","form":"demonstrates"},{"label":"过去式","form":"demonstrated"},{"label":"过去分词","form":"demonstrated"},{"label":"现在分词","form":"demonstrating"}],"derivatives":[{"word":"demonstration","pos":"n.","zh":"证明；演示；示威"},{"word":"demonstrative","pos":"adj.","zh":"说明性的；感情外露的"},{"word":"demonstrator","pos":"n.","zh":"演示者；示威者"},{"word":"demonstrable","pos":"adj.","zh":"可证明的；可示范的"},{"word":"remonstrate","pos":"v.","zh":"抗议；规劝"}],"senses":[{"no":"01","title":"Prove by argument: make the truth stand up","titleCN":"论证：用理由把结论立起来","definition":"to show that something is true by giving reasons or evidence","definitionCN":"通过给出理由或证据证明某事为真","example":"The study demonstrates that early reading predicts later success.","exampleCN":"该研究论证了早期阅读能预测后来的成功。","why":"The 'establish the truth by argument or deduction' sense is recorded from the 1570s. Latin demonstrare meant 'point out' and then 'prove': a proof points at the conclusion and makes it visible to reason.","whyCN":"“以论证或演绎确立真理”这一义记录于 16 世纪 70 年代。拉丁语 demonstrare 先指“指出来”，再指“证明”：证明就是把结论指出来，让它对理性可见。"},{"no":"02","title":"Prove by experiment: let the specimen speak","titleCN":"实证：让标本自己说话","definition":"to establish a fact scientifically by experiment, specimen, or systematic observation","definitionCN":"通过实验、标本或系统观察科学地确立一个事实","example":"The team demonstrated the effect in a controlled trial.","exampleCN":"该团队在对照试验中证实了这一效应。","why":"From the 1680s demonstrate meant 'describe and explain scientifically by specimens or experiment'. The pointing hand becomes the experiment: nature is made to show itself under controlled conditions.","whyCN":"从 17 世纪 80 年代起，demonstrate 指“用标本或实验科学地描述与解释”。指着的手变成了实验：让自然在受控条件下自己显示出来。"},{"no":"03","title":"Show how it works: run the machine in front of you","titleCN":"演示：当着你的面把机器跑一遍","definition":"to show how a device, process, or technique is used by doing it in front of others","definitionCN":"当众操作，展示器械、流程或技术的用法","example":"The technician demonstrated the new printer to the staff.","exampleCN":"技术员向员工演示了新打印机。","why":"The 'exhibition and explanation of practical operations' sense is recorded by 1807. The abstract proof turns concrete: instead of proving that it can work, you make it work while others watch.","whyCN":"“实际操作的展示与讲解”这一义记录于 1807 年。抽象的证明变得具体：不是证明它能工作，而是让别人看着它工作。"},{"no":"04","title":"Take to the streets: show disagreement in public","titleCN":"示威：把不同意见摆到大街上","definition":"to take part in a public march or gathering in support of or against a cause","definitionCN":"参加公开游行或集会，以支持或反对某一事业","example":"Thousands demonstrated outside the ministry against the new tax.","exampleCN":"数千人在部门外示威，反对新税。","why":"The 'public demonstration' sense is recorded by 1888. A crowd showing its numbers is a demonstration in the old sense: the sheer visibility of bodies is the argument.","whyCN":"“公开示威”这一义记录于 1888 年。人群亮出自己的数量，就是旧义上的 demonstrate：身体本身的可见性就是论据。"},{"no":"05","title":"Show what you feel: let a quality become visible","titleCN":"表露：让某种情感或品质显现出来","definition":"to show a quality, feeling, or skill through behavior","definitionCN":"通过行为显示出某种品质、情感或技能","example":"He demonstrated remarkable patience with the new students.","exampleCN":"他对新来的学生表现出非凡的耐心。","why":"From the 1550s the verb meant 'point out, indicate, exhibit'. A feeling is demonstrated when it leaves the inside and becomes something others can point to in your conduct.","whyCN":"从 16 世纪 50 年代起，这个动词意为“指出、表明、展示”。一种情感被 demonstrate，就是它离开内心，变成别人能在你行为里指认出来的东西。"},{"no":"06","title":"Point it out: the oldest gesture","titleCN":"指出：最古老的那个手势","definition":"to indicate or exhibit something plainly, an original sense now rare","definitionCN":"明白地指出或展示某物，原始义，现已罕用","example":"The guide demonstrated the peak with a sweep of his arm.","exampleCN":"向导挥臂指出那座山峰。","why":"The 1550s sense was literally 'point out, indicate, exhibit', now obsolete in ordinary use. The whole family still carries that gesture: a finger, an omen, a thing made visible.","whyCN":"16 世纪 50 年代的义项字面就是“指出、指示、展示”，今日日常中已废。整个词族仍带着这个手势：一根手指、一个征兆、一件被弄成可见的东西。"},{"no":"07","title":"Sell by showing: the product demo","titleCN":"产品演示：靠展示来卖","definition":"to show a product or service in use in order to persuade buyers","definitionCN":"展示产品或服务的使用过程以说服买家","example":"The company demonstrated the software to a room of buyers.","exampleCN":"公司向满屋买家演示了这款软件。","why":"Commercial demonstration grows from the 1807 'practical operations' sense. A buyer who sees the thing work is being shown the proof, and the proof is also the sales pitch.","whyCN":"商业演示从 1807 年“实际操作展示”一义长出来。买家看见东西真的能用，既是在看证据，也是在听推销。"},{"no":"08","title":"Show force: a fleet that makes a point","titleCN":"显示武力：让舰队替外交说话","definition":"to display military force openly as a warning or threat","definitionCN":"公开显示军事力量，作为警告或威胁","example":"The navy demonstrated its presence in the disputed waters.","exampleCN":"海军在争议海域显示了它的存在。","why":"A military demonstration is a show whose argument is capability. The oldest 'make visible' sense turns strategic: the enemy is asked to see what would happen if the warning is ignored.","whyCN":"军事示威是一场以能力为论据的展示。最古老的“使之可见”义变成战略：让对手看见，如果无视警告会发生什么。"},{"no":"09","title":"Teach by specimen: let the object do the explaining","titleCN":"标本讲解：让实物替老师说话","definition":"to explain a structure or process to students by showing a specimen or worked example","definitionCN":"通过展示标本或完整范例向学生解释结构或过程","example":"The lecturer demonstrated the heart's valves on a model.","exampleCN":"讲师在模型上讲解了心脏瓣膜。","why":"Teaching uses the 1680s scientific sense in the classroom: a specimen is pointed at, and the pointing is the lesson. Here demonstrate is explanation, not proof.","whyCN":"教学把 17 世纪 80 年代的科学义搬进课堂：指着标本，指的动作就是课。这一义里 demonstrate 是讲解，不是证明。"}],"etymology":{"intro":{"en":"Demonstrate is Latin 'to point out'. The finger comes first, then the proof, then the working machine, and finally the crowd in the street: each step makes something visible to others.","cn":"demonstrate 是拉丁语“指出来”。先是手指，再是证明，再是运转的机器，最后是街上的人群：每一步都把某样东西弄成别人可见的。"},"items":[{"era":"LATIN","en":"Monstrare meant 'to point out, show', from monstrum 'divine omen, wonder'. Monstrum comes from monere 'to remind, warn, instruct', whose PIE base *men- 'to think' is reconstructed only.","cn":"monstrare 意为“指出、展示”，来自 monstrum“神兆、奇观”。monstrum 又来自 monere“提醒、警告、教导”，其原始印欧语词根 *men-“思考”只是重构形式。"},{"era":"LATIN","en":"Demonstrare meant 'to point out, indicate, demonstrate', and figuratively 'to prove, establish', from de- 'entirely' plus monstrare 'to show'.","cn":"demonstrare 意为“指出、指示、展示”，比喻义为“证明、确立”，由 de-“彻底”加 monstrare“显示”构成。"},{"era":"1550s ENGLISH","en":"The verb appears as 'point out, indicate, exhibit'. This literal gesture is now rare in ordinary speech but survives across the whole word family.","cn":"动词出现，意为“指出、指示、展示”。这个字面手势如今在日常口语中罕用，却存留在整个词族里。"},{"era":"1570s–1680s ENGLISH","en":"'Establish the truth by argument or deduction' is recorded from the 1570s; 'describe and explain scientifically by specimens or experiment' from the 1680s.","cn":"“以论证或演绎确立真理”记录于 16 世纪 70 年代；“用标本或实验科学地描述与解释”记录于 17 世纪 80 年代。"},{"era":"1807–1888 ENGLISH","en":"'Exhibition and explanation of practical operations' is recorded by 1807; the public political demonstration and the verb 'take part in one' by 1888.","cn":"“实际操作的展示与讲解”记录于 1807 年；政治性公开示威及动词“参加示威”记录于 1888 年。"},{"era":"ORIGIN UNCERTAIN","en":"The certain chain ends at Latin monere and monstrum. The PIE root *men- 'to think' is a reconstruction with no written record, so the step below Latin is marked source uncertain.","cn":"可靠的链条停在拉丁语 monere 与 monstrum。原始印欧语词根 *men-“思考”是没有书面记录的重构，因此拉丁语下面的一层标为“来源不确定”。"}]},"similar":{"note":{"en":"The first group is chosen for spelling and sound, the second for meaning, so that form and sense stay separate.","cn":"第一组按拼写和读音挑选，第二组按词义挑选，这样词形和词义不会混在一起。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"remonstrate","ipa":"/rɪˈmɒnstreɪt/","tag":"prefix swap","definition":"to protest or argue in complaint. It is re- plus monstrare, and looks like demonstrate with a different prefix.","definitionCN":"抗议；规劝。它是 re- 加 monstrare，与 demonstrate 只差前缀。"},{"word":"demonize","ipa":"/ˈdiːmənaɪz/","tag":"same opening","definition":"to portray someone as evil. It begins with demo- but comes from demon, not from monstrare.","definitionCN":"妖魔化。它同样以 demo- 开头，却来自 demon，而非 monstrare。"},{"word":"demolish","ipa":"/dɪˈmɒlɪʃ/","tag":"near spelling","definition":"to tear a building down. It shares the de- and m- opening but has a different root.","definitionCN":"拆除；摧毁。它同样以 de- 和 m- 开头，但词根不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"show","ipa":"/ʃəʊ/","tag":"general","definition":"to make something visible or known. It is the plain word behind every sense of demonstrate.","definitionCN":"展示；表明。它是 demonstrate 一切义项背后最普通的词。"},{"word":"prove","ipa":"/prəʊv/","tag":"establish truth","definition":"to establish that something is true. It matches senses 01 and 02.","definitionCN":"证明。它对应第 1、2 义。"},{"word":"display","ipa":"/dɪˈspleɪ/","tag":"put on view","definition":"to put something where it can be seen. It matches the exhibit side, sense 06.","definitionCN":"陈列；展示。它对应“展出”一面，即第 6 义。"},{"word":"illustrate","ipa":"/ɪˈlʌstreɪt/","tag":"explain by example","definition":"to explain by giving examples or pictures. It matches the teaching sense 09.","definitionCN":"举例说明；图解。它对应教学义第 9 义。"},{"word":"protest","ipa":"/prəˈtest/","tag":"public objection","definition":"to say or show publicly that one disagrees. It matches the street sense 04.","definitionCN":"抗议。它对应街头示威义第 4 义。"}]}]},"mnemonics":{"normalIntro":{"en":"These links are real: Latin monstrare 'to show', the monstrum and monere family, and the English words demonstration and remonstrate.","cn":"这些联想都是真实的：拉丁语 monstrare“显示”、monstrum 与 monere 词族，以及英语的 demonstration、remonstrate。"},"normal":[{"en":"demonstrate = de- 'entirely' + monstrare 'to show': to show something all the way, until no doubt is left.","cn":"demonstrate = de-“彻底”+ monstrare“显示”：把某物彻底显示出来，直到不留疑问。"},{"en":"A demonstration is a showing; a demonstrator is a person who shows, whether a machine or a grievance.","cn":"demonstration 是一次展示；demonstrator 是展示的人，展示的可以是机器，也可以是不满。"},{"en":"monster comes from monstrum 'omen': a monster was originally a sign pointed out by the gods.","cn":"monster 来自 monstrum“征兆”：怪物最初是神明指给人看的一个信号。"},{"en":"monitor and admonish come from monere 'to warn': all three words involve pointing something out to someone.","cn":"monitor 与 admonish 来自 monere“警告”：这三个词都涉及把某事指给某人看。"},{"en":"A street demonstration is a proof made of bodies: the crowd points at itself so the government must see it.","cn":"街头示威是用身体做出的证明：人群指向自己，让政府不得不看见。"}],"abstract":[{"en":"The core is visibility: something is moved from hidden or doubtful to plainly seen.","cn":"核心是可见性：某物从隐藏或可疑，被移到众目之下。"},{"en":"The showing changes medium: a finger, a proof, a machine, a specimen, a crowd, a fleet.","cn":"展示不断更换媒介：手指、证明、机器、标本、人群、舰队。"},{"en":"So prove, demo, explain and protest are one gesture of pointing, aimed at four different audiences.","cn":"所以证明、演示、讲解、示威是同一个指认手势，指向四种不同的观众。"}]},"examples":[{"en":"The experiment demonstrates how pressure changes with depth.","cn":"这个实验演示了压强如何随深度变化。"},{"en":"She demonstrated the dance move slowly for the beginners.","cn":"她为初学者慢慢示范了这个舞蹈动作。"},{"en":"Hundreds demonstrated for cleaner air in the city.","cn":"数百人示威，要求城市空气更清洁。"}],"dict_mnemonic":{"note":"拆分联想 · 非词源","text":"de（得）+ monstrate（monster 怪物）——把怪物牵出来给大家看，就是展示、证明 → demonstrate","word":"demonstrate"},"root":"源自拉丁语 demonstrare“指出、展示、证明”，由 de-“彻底”+ monstrare“显示”构成，monstrare 又出自 monstrum“征兆”、monere“提醒、警告”，核心是“把某物指给人看”。","sensesIntro":{"en":"Nine senses of demonstrate, all one gesture of pointing: at a conclusion, at an experiment, at a working machine, at a crowd, at a feeling, at a peak, at a product, at a fleet, at a specimen.","cn":"demonstrate 的九个义项都是同一个指认手势：指向结论、指向实验、指向运转的机器、指向人群、指向情感、指向山峰、指向产品、指向舰队、指向标本。"},"semanticMap":{"core":{"en":"CORE IMAGE: a thing lifted into view and pointed at until others see it.","cn":"核心意象：把某物举到视野里，指着它，直到别人看见。"},"chain":["POINT AT IT","MAKE IT VISIBLE","RUN IT IN FRONT OF YOU","SHOW THAT IT IS TRUE","SHOW WHAT YOU FEEL","TAKE IT TO THE STREET"],"branches":[{"senses":"S01 · S02","en":"THE PROOF: argument and experiment both make a truth visible.","cn":"证明：论证与实验都把真理弄成可见。"},{"senses":"S03 · S07","en":"THE WORKING DEMO: a machine runs before watchers, and a product is shown to buyers.","cn":"运转中的演示：机器在观看者面前运行，产品向买家展示。"},{"senses":"S05 · S06","en":"THE VISIBLE QUALITY: a feeling shows in behavior, and a hand points out the thing itself.","cn":"可见的品质：情感在行为中显现，手则指出事物本身。"},{"senses":"S04 · S08","en":"FORCE MADE PUBLIC: a crowd and a fleet both argue by being seen.","cn":"公开的力量：人群与舰队都靠“被看见”来论证。"},{"senses":"S09","en":"THE LESSON: a specimen is pointed at so that students see the structure.","cn":"课堂：指着标本，让学生看见结构。"}]},"affixes":{"intro":{"en":"Demonstrate is de- plus monstrare. Its family shows the root monstr- 'show', the prefixes de-, re-, ad-, sub- and the suffixes -tion, -ive, -or and -able.","cn":"demonstrate 是 de- 加 monstrare。它的词族展示词根 monstr-“显示”，前缀 de-、re-、ad-、sub-，以及后缀 -tion、-ive、-or、-able。"},"latinIntro":{"en":"Latin monstrare 'to show' and monere 'to warn' share the stem mon-; they yield demonstrate, demonstration, remonstrate, admonish, monitor, summon and monster.","cn":"拉丁语 monstrare“显示”与 monere“警告”共享 mon- 词干；它们给出 demonstrate、demonstration、remonstrate、admonish、monitor、summon、monster。"},"items":[{"word":"demonstrate","structure":"de- (entirely) + monstrare (to show)","meaning":"to show clearly; to prove; to protest publicly","meaningCN":"证明；演示；表露；示威（de- 彻底 + 显示）","example":"Let me demonstrate the process step by step.","exampleCN":"让我一步步演示这个过程。"},{"word":"demonstration","structure":"demonstrate + -ion (noun of action)","meaning":"a proof, a demo, or a public protest","meaningCN":"证明；演示；示威（-ion 构成动作名词）","example":"The demonstration drew a crowd of thousands.","exampleCN":"这场示威聚集了数千人。"},{"word":"demonstrative","structure":"demonstrate + -ive (adjective)","meaning":"showing feelings openly; pointing out","meaningCN":"感情外露的；指示的（-ive 构成形容词）","example":"He is unusually demonstrative with his family.","exampleCN":"他对家人格外感情外露。"},{"word":"demonstrator","structure":"demonstrate + -or (person)","meaning":"a person who shows or protests","meaningCN":"演示者；示威者（-or 表人）","example":"The demonstrator explained each step.","exampleCN":"演示者讲解了每一步。"},{"word":"demonstrable","structure":"demonstrate + -able (capable of)","meaning":"able to be shown or proved","meaningCN":"可证明的；可示范的（-able 表能够）","example":"The benefits are demonstrable in the data.","exampleCN":"这些好处在数据中可以得到证明。"},{"word":"remonstrate","structure":"re- (against) + monstrare (to show)","meaning":"to protest or argue in complaint","meaningCN":"抗议；规劝（re- 反对 + 显示）","example":"She remonstrated with him about the delay.","exampleCN":"她就延误一事向他提出抗议。"},{"word":"admonish","structure":"ad- (to) + monere (to warn)","meaning":"to warn or reprimand gently","meaningCN":"告诫；警告（ad- 朝向 + 警告）","example":"The teacher admonished the class for being late.","exampleCN":"老师告诫全班不要迟到。"},{"word":"monitor","structure":"monere (to warn) + -or (person or device)","meaning":"to watch and check; a screen or watcher","meaningCN":"监控；监视器（原指“提醒者”）","example":"The nurse monitors his heart rate.","exampleCN":"护士监测他的心率。"},{"word":"summon","structure":"sub- (under, privately) + monere (to warn)","meaning":"to call someone to come","meaningCN":"召唤；传唤（私下提醒 → 召来）","example":"The judge summoned the witness.","exampleCN":"法官传唤了证人。"},{"word":"monster","structure":"monstrum (divine omen, wonder)","meaning":"a frightening creature, originally an omen","meaningCN":"怪物（原指神兆、奇观）","example":"The story ends with a monster under the bed.","exampleCN":"故事以床下的怪物收尾。"}],"latinEntries":[{"word":"monstrare","structure":"monstrare (verb)","meaning":"to point out, show","meaningCN":"指出；显示"},{"word":"monstrum","structure":"monere + -trum","meaning":"divine omen, wonder","meaningCN":"神兆；奇观"},{"word":"monere","structure":"monere (verb)","meaning":"to remind, warn, instruct","meaningCN":"提醒；警告；教导"}]}},{"word":"denote","ipa_uk":"/dɪˈnəʊt/","ipa_us":"/dɪˈnoʊt/","definition_zh":"表示；标示；意味着；指代","definition_en":"to be a sign of something, or to stand for a particular meaning","core_image":"路牌上画着一辆被斜线划掉的车——它不描写车，只把“此处禁行”标出来","scene":"The dotted line on the map denotes the border between the two countries.","sceneCN":"这里 denote 是「标示、标出」（第 2 个义项）；地图上的虚线并不描写边界，只是把边界的位置标出来。句意：地图上的虚线标示两国边界。","pos":[{"tag":"vt.","zh":"表示；标示；意味着；指代"},{"tag":"vi.","zh":"（符号、词语）表示……的意思"}],"collocations":[{"phrase":"denote a change","zh":"表示一种变化"},{"phrase":"denote the boundary","zh":"标示边界"},{"phrase":"be denoted by","zh":"用……来表示"},{"phrase":"denote a relationship","zh":"表示一种关系"},{"phrase":"denote the presence of","zh":"表明……的存在"}],"forms":[{"label":"三单","form":"denotes"},{"label":"过去式","form":"denoted"},{"label":"过去分词","form":"denoted"},{"label":"现在分词","form":"denoting"}],"derivatives":[{"word":"denotation","pos":"n.","zh":"字面意义；外延；标示"},{"word":"denotative","pos":"adj.","zh":"指示的；字面意义的"},{"word":"denotatively","pos":"adv.","zh":"从字面意义上；指示地"},{"word":"denotable","pos":"adj.","zh":"可表示的；可标指的"},{"word":"denotement","pos":"n.","zh":"标记；标示（罕用）"}],"senses":[{"no":"01","title":"Mark off: single a thing out by a mark","titleCN":"划界标出：用标记把某物单独圈出来","definition":"to mark something off from others, or identify it by a distinguishing mark","definitionCN":"把某物从其他事物中划出来，或用有区别的标记把它认出来","example":"On the plan, each plot is denoted by a small numbered square.","exampleCN":"在平面图上，每一块地都用带编号的小方框标出。","why":"Latin denotare joins de- 'completely' to notare 'to mark'. The first English sense in the 1590s was 'mark off from others; identify by a mark' — the mark does not describe the thing, it singles it out.","whyCN":"拉丁语 denotare 由 de-“完全”加 notare“做标记”构成。16 世纪 90 年代英语最早的意思是“把某物从别的东西里划出来、用标记认出它”——标记不描写事物，只把它单独点出来。"},{"no":"02","title":"Be the sign of: stand in place of something","titleCN":"标示：作为某物的记号站在那里","definition":"to be a sign or symptom of something; to indicate it","definitionCN":"作为某事物的记号或征兆；表明、指示该事物","example":"The raised flag denotes that the track is closed.","exampleCN":"升起的旗子表示这条跑道已关闭。","why":"Once a mark can single a thing out, the mark can also stand for it. The 1590s record already includes 'be the sign or symptom of', so the physical mark became a sign read by an observer.","whyCN":"一旦一个标记能把事物单独点出来，它也能代替那个事物站在那里。16 世纪 90 年代的记录已含“是……的记号或征兆”，于是手上的标记变成了让观察者去读的符号。"},{"no":"03","title":"Of a word: carry a literal meaning","titleCN":"字面所指：一个词承载的本义","definition":"of a word, to have a particular literal meaning or refer to a particular thing","definitionCN":"指词语具有某种字面意义，或指称某一特定事物","example":"In British English, 'flat' denotes an apartment, not a tyre.","exampleCN":"在英式英语里，flat 指的是公寓，而不是轮胎。","why":"Language took the sign relation and made it verbal: a word is the mark, its literal meaning is what the mark stands for. This is the 'denotation' later contrasted with the feelings a word carries.","whyCN":"语言把“记号—所指”这层关系搬到了词语上：词是标记，字面意义是标记所代表的东西。这就是后来与“言外之感”相对立的“外延、字面意义”。"},{"no":"04","title":"Of a symbol: represent a fixed value","titleCN":"符号代表：固定地代表某个对象","definition":"of a symbol, to represent or stand for a particular object or quantity","definitionCN":"指符号代表、指代某一特定对象或数量","example":"In the equation, the letter x denotes an unknown number.","exampleCN":"在这个方程里，字母 x 表示一个未知数。","why":"Mathematics kept the strictest part of the word: a symbol is appointed to stand for exactly one value. The mark is arbitrary, but the standing-for is fixed by rule.","whyCN":"数学保留了这个词最严格的一面：一个符号被指定代表恰好一个值。记号本身是任意的，但“代表什么”由规则固定下来。"},{"no":"05","title":"Point to indirectly: suggest without saying","titleCN":"暗示：不直说而指向某意","definition":"to suggest or imply something indirectly, rather than state it openly","definitionCN":"间接地暗示或意味着某事，而不是公开说出","example":"A rising tone may denote doubt rather than a real question.","exampleCN":"升调可能表示怀疑，而不是真正的提问。","why":"A sign need not be explicit. Since a mark can be read for what it hints at, denote widened from 'stand for' to 'point toward' — the listener infers what the sign implies.","whyCN":"记号不必明说。既然一个标记可以被读出它暗示的东西，denote 就从“代表”扩大到“指向”——听者去推断记号所隐含的意思。"},{"no":"06","title":"Denotation in semantics: the hard edge of meaning","titleCN":"语义学的外延：意义中坚硬的那条边","definition":"in semantics, the direct or literal meaning of an expression, as opposed to its connotation","definitionCN":"语义学中指表达式的直接或字面意义，与内涵、联想义相对","example":"The denotation of 'snake' is a reptile; its connotation may be danger.","exampleCN":"snake 的外延是一种爬行动物；它的内涵可能是危险。","why":"Twentieth-century linguistics split the old verb into two nouns: denotation is what the sign covers, connotation is what it trails behind. The term keeps the word's original 'marking out' image.","whyCN":"20 世纪语言学把这个旧动词拆成两个名词：外延是符号所覆盖的范围，内涵是它身后拖着的联想。术语仍保留这个词最初“划出范围”的意象。"},{"no":"07","title":"Of a name: designate a person or office","titleCN":"指称：名称指定某个人或职位","definition":"of a name or title, to designate a particular person, group, or office","definitionCN":"指名称或头衔指定某个人、群体或职位","example":"'Chair' denotes the person who runs the meeting, not the furniture.","exampleCN":"chair 指的是主持会议的人，而不是那件家具。","why":"A title is a mark pinned on a person. The 'mark off' sense survives here: the name does not describe the holder, it identifies which person is meant.","whyCN":"头衔是别在人身上的标记。“划出来”的义项在这里仍然活着：名称不描写持有者，只指明说的是哪一个人。"},{"no":"08","title":"In medicine: be a symptom of","titleCN":"医学上：作为某种病症的指征","definition":"of a symptom or test result, to indicate the presence of a particular disease or condition","definitionCN":"指症状或检查结果表明存在某种疾病或状况","example":"A persistent cough may denote a lung infection.","exampleCN":"持续咳嗽可能表明肺部感染。","why":"Medicine uses the body as a surface of signs. A symptom marks a hidden condition the way a flag marks a closed track; the visible sign denotes what cannot be seen.","whyCN":"医学把身体当作一片符号的表面。症状标示看不见的病情，就像旗子标示关闭的跑道；可见的征兆代表着看不见的东西。"},{"no":"09","title":"In grammar: a form marks a function","titleCN":"语法上：形式标记某一功能","definition":"of a grammatical form, to signal a particular function such as tense, number, or case","definitionCN":"指语法形式标示时态、数、格等特定功能","example":"In English, the -s ending denotes plural number on nouns.","exampleCN":"在英语里，-s 词尾表示名词的复数。","why":"Grammarians treat inflection as a mark on a stem. The suffix is the visible mark; plural is the function it denotes, so the 1590s 'mark' sense is applied to the smallest pieces of language.","whyCN":"语法学家把屈折变化看作词干上的标记。后缀是看得见的记号，复数是它所表示的功能——16 世纪 90 年代那个“标记”义就这样用到了语言最小的部件上。"}],"etymology":{"intro":{"en":"Denote comes from Latin denotare, 'mark out, designate', built from de- 'completely' and notare 'to mark'. It reached English through French dénoter in the 1590s, and later became a technical term in logic and semantics.","cn":"denote 来自拉丁语 denotare“标出、指定”，由 de-“完全”与 notare“做标记”构成。它经法语 dénoter 于 16 世纪 90 年代进入英语，后来成为逻辑学和语义学的术语。"},"items":[{"era":"LATIN (before 1C BC)","en":"Denotare meant 'to mark out, point out, designate'. It is a transparent compound of de- 'completely' and notare 'to mark', from nota 'a mark, sign, note'.","cn":"denotare 意为“标出、指出、指定”，是 de-“完全”与 notare“做标记”的透明复合词，而 notare 来自 nota“标记、符号、记号”。"},{"era":"FRENCH (14c.)","en":"French dénoter carried the Latin sense 'to denote, mark out' and supplied the form English borrowed.","cn":"法语 dénoter 承袭拉丁语“标示、标出”的意思，并提供了英语借入的词形。"},{"era":"1590s ENGLISH","en":"The first English records give 'mark off from others; identify by a mark; be the sign or symptom of'. The mark and the thing it stands for arrive together.","cn":"英语最早记录为“把某物从其他事物中划出；用标记辨认；是……的记号或征兆”。标记与它所代表的事物是一起出现的。"},{"era":"17c. ENGLISH","en":"The verb settled into the general sense 'be a sign of, indicate'. Objects, words, and symptoms could all denote what they pointed to.","cn":"这个动词稳定在泛指的“是……的记号、表明”上。物件、词语、症状都可以 denote 它们所指向的东西。"},{"era":"MODERN ENGLISH","en":"Logic and linguistics turned denote into a technical word: denotation is the literal range of a term, while connotation is the feeling it drags along. The spelling and the mark image have not changed.","cn":"逻辑学和语言学把 denote 变成术语：denotation 是词语的字面范围，connotation 是它拖着的感受。拼写与“标记”的意象都没有变。"}]},"similar":{"note":{"en":"The first group is chosen for spelling and sound, the second for meaning, so that form and sense stay separate.","cn":"第一组按拼写和读音挑选，第二组按词义挑选，这样词形和词义不会混在一起。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"demote","ipa":"/dɪˈməʊt/","tag":"de- + move","definition":"to move someone to a lower rank or position. It shares the de- opening and the stress pattern of denote.","definitionCN":"使降级、降职。与 denote 同样以 de- 开头、重音位置相同。"},{"word":"devote","ipa":"/dɪˈvəʊt/","tag":"de- + vow","definition":"to give one's time or energy wholly to something. It differs from denote by a single consonant.","definitionCN":"把时间或精力完全献给某事。与 denote 只差一个辅音。"},{"word":"denounce","ipa":"/dɪˈnaʊns/","tag":"de- + nounce","definition":"to publicly declare someone or something wrong or evil. It begins with the same deno- string but ends in a different root.","definitionCN":"公开谴责、告发。开头同样是 deno-，但词根不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mean","ipa":"/miːn/","tag":"literal sense","definition":"to have a particular sense or refer to a particular thing. It is the plain everyday match for denote in its word sense.","definitionCN":"意思是；指的是。对应 denote 表“词语字面意义”的义项，是最日常的说法。"},{"word":"signify","ipa":"/ˈsɪɡnɪfaɪ/","tag":"be a sign of","definition":"to be a sign of something, or to make a meaning known. It is close to denote but often implies communication.","definitionCN":"表示；意味着；象征。与 denote 接近，但更强调传达出意思。"},{"word":"indicate","ipa":"/ˈɪndɪkeɪt/","tag":"point to","definition":"to show or point to something, often indirectly. It matches the 'be a sign of' sense without the technical weight.","definitionCN":"表明；指示。对应“是……的记号”义，但没有术语色彩。"},{"word":"represent","ipa":"/ˌreprɪˈzent/","tag":"stand for","definition":"to stand for something or act on its behalf. It matches denote in the symbol-and-name senses.","definitionCN":"代表；象征。对应 denote 的符号义和名称指称义。"},{"word":"stand for","ipa":"/stænd fɔː(r)/","tag":"phrasal match","definition":"to be an abbreviation or symbol of something. It is the spoken paraphrase of what a mark denotes.","definitionCN":"代表；是……的缩写或符号。是“一个标记 denote 什么”的口语说法。"}]}]},"mnemonics":{"normalIntro":{"en":"These links are real: the Latin notare family behind note and notify, the con- prefix inside connote, and the everyday habit of reading marks as signs.","cn":"这些联想都是真实的：note、notify 背后拉丁语 notare 词族，connote 里的 con- 前缀，以及人把标记读成符号的日常习惯。"},"normal":[{"en":"de- means 'completely' and notare means 'to mark': to denote is to mark a thing fully, so that the mark can stand for it.","cn":"de- 是“完全”，notare 是“做标记”：denote 就是把标记完整地打在事物上，好让这个标记能代替它。"},{"en":"note, notable, notify and denote all sit on Latin nota 'mark'. A note is a mark you make so the thing can be found again.","cn":"note、notable、notify、denote 都站在拉丁语 nota“标记”上。note 是你做的标记，为的是以后还能找到那件事。"},{"en":"connote = con- 'with' + notare 'mark': connotation is the extra mark a word carries along with its plain denotation.","cn":"connote = con-“一起”+ notare“标记”：connotation 就是一个词在字面外延之外顺带带着的额外标记。"},{"en":"In a dictionary, the denotation is the first line; the connotation is what the usage note whispers after it.","cn":"词典里，denotation 是第一行释义；connotation 是后面用法说明悄悄补充的那层意味。"},{"en":"Mathematicians say x denotes a number: the letter is a mark appointed to stand in the number's place.","cn":"数学家说 x denotes 一个数：字母是被指派站在那个数位置上的标记。"}],"abstract":[{"en":"A sign is a finger pointing at the moon: denote gives the pointing, not the moonlight.","cn":"符号是指向月亮的手指：denote 给出的是那根手指，而不是月光。"},{"en":"Denotation is the hard edge of a word's meaning; connotation is the soft shadow it casts.","cn":"外延是词义坚硬的那条边，内涵是它投下的柔软影子。"},{"en":"To denote is to draw a line around a thing and say: this mark, and no other, stands here.","cn":"denote 就是绕着事物画一条线，然后说：站在这里的，是这个标记，不是别的。"}]},"examples":[{"en":"In this chart, the red bars denote last year's sales.","cn":"在这张图里，红色柱条表示去年的销售额。"},{"en":"For many people, a wedding ring denotes commitment rather than wealth.","cn":"对许多人来说，婚戒表示的是承诺，而不是财富。"},{"en":"The symbol @ denotes 'at' in an email address.","cn":"符号 @ 在电子邮件地址中表示“at”。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“点 note”——de（完全）+ note（标记），把标记完全点到事物上，就是标示、表示","word":"denote"},"root":"源自拉丁语 denotare“标出、指定”，由 de-“完全”+ notare“做标记”构成，notare 又来自 nota“标记”；经法语 dénoter 于 16 世纪 90 年代进入英语。","sensesIntro":{"en":"Nine senses of denote, from a mark that singles a thing out to the semantic term for literal meaning. Each step keeps the same move: a visible mark is placed where something else should be read.","cn":"denote 的九个义项，从把事物单独划出的标记，一直到语义学里指“字面意义”的术语。每一步都保持同一个动作：把一个看得见的标记放在本该读出别的东西的位置上。"},"semanticMap":{"core":{"en":"CORE IMAGE: a mark laid on a thing so that the mark can stand for it.","cn":"核心意象：把一个标记打在事物上，好让这个标记代替它。"},"chain":["MAKE A MARK","SINGLE OUT","STAND FOR","CARRY A MEANING","POINT INDIRECTLY","FIX THE RANGE"],"branches":[{"senses":"S01 · S02","en":"THE MARK AND THE SIGN: first the mark identifies a thing, then the same mark is read as its sign.","cn":"标记与符号：先是用标记认出事物，接着同一个标记被读成事物的符号。"},{"senses":"S03 · S07","en":"WORDS AND NAMES: a word marks a literal meaning, and a title marks which person is meant.","cn":"词与名称：词标出字面意义，头衔标出说的是哪个人。"},{"senses":"S04 · S09","en":"FORMAL MARKS: a mathematical symbol stands for a fixed value, and a grammatical ending marks a function.","cn":"形式标记：数学符号代表固定数值，语法词尾标示功能。"},{"senses":"S05 · S08","en":"READING BEYOND THE MARK: a tone hints at doubt, and a symptom points to a hidden disease.","cn":"读出标记之外：语调暗示怀疑，症状指向看不见的疾病。"},{"senses":"S06","en":"THE TECHNICAL EDGE: denotation names the literal range of a term, set against its connotation.","cn":"术语的边界：外延命名词语的字面范围，与内涵相对。"}]},"affixes":{"intro":{"en":"Denote is a Latin loan built on the stem not- 'mark': note, notable, notify and annotate share it, while de-, con- and ad- change the direction of the marking.","cn":"denote 是建立在词干 not-“标记”上的拉丁借词：note、notable、notify、annotate 共用这个词干，而 de-、con-、ad- 改变标记的方向。"},"latinIntro":{"en":"Latin nota 'mark, sign' produces notare 'to mark', then denotare 'mark out', annotare 'write down beside', and connote 'mark along with'. The family is about marks, not about knowledge.","cn":"拉丁语 nota“标记、符号”生出 notare“做标记”，再生成 denotare“标出”、annotare“在旁边写下”、connotare“连带着标记”。这个词族讲的是标记，不是知识。"},"items":[{"word":"denote","structure":"de- (completely) + notare (to mark)","meaning":"to mark out; be a sign of","meaningCN":"标示；表示（de- 完全 + notare 标记）","example":"The crest denotes the city's founding family.","exampleCN":"这个纹章标示这座城市的创建家族。"},{"word":"denotation","structure":"denot- + -ation (noun of action)","meaning":"the literal meaning or range of a term","meaningCN":"字面意义；外延（-ation 构成名词）","example":"Definitions focus on denotation, not on tone.","exampleCN":"释义关注的是字面意义，而不是语气。"},{"word":"denotative","structure":"denot- + -ative (adjective)","meaning":"having the function of denoting","meaningCN":"指示的；字面意义的（-ative 构成形容词）","example":"Scientific writing tends to be denotative.","exampleCN":"科学写作倾向于使用字面意义。"},{"word":"note","structure":"Latin nota (a mark, sign)","meaning":"a short written record; to notice","meaningCN":"笔记；注意到（直接来自 nota 标记）","example":"She noted the exact time of the call.","exampleCN":"她记下了那通电话的确切时间。"},{"word":"notable","structure":"not- (mark) + -able (worthy of)","meaning":"worthy of being noticed","meaningCN":"值得注意的；显著的（-able 值得）","example":"The town is notable for its stone bridge.","exampleCN":"这座小镇因石桥而闻名。"},{"word":"notify","structure":"not- (mark) + -ify (to make)","meaning":"to make something known formally","meaningCN":"通知（-ify 使……；使人知道）","example":"Please notify us of any change of address.","exampleCN":"地址如有变动，请通知我们。"},{"word":"annotate","structure":"an- (ad-, to) + notare (to mark)","meaning":"to add notes beside a text","meaningCN":"给……作注释（ad- 朝向 + notare 标记）","example":"Students annotate the poem in the margins.","exampleCN":"学生们在页边给这首诗作注释。"},{"word":"annotation","structure":"annotat- + -ion (noun of action)","meaning":"a note added to a text","meaningCN":"注释；评注（-ion 构成名词）","example":"The annotation explains an old idiom.","exampleCN":"这条注释解释了一个古老的习语。"},{"word":"connote","structure":"con- (with) + notare (to mark)","meaning":"to carry an extra suggested meaning","meaningCN":"意味着；含言外之意（con- 一起 + notare 标记）","example":"The word 'home' connotes warmth and safety.","exampleCN":"home 这个词含有温暖和安全的意味。"}],"latinEntries":[{"word":"nota","structure":"nota (noun)","meaning":"a mark, sign, note, letter","meaningCN":"标记；符号；记号；字母"},{"word":"notare","structure":"nota + -are (verb)","meaning":"to mark, note, make a note of","meaningCN":"做标记；记录；注意"},{"word":"denotare","structure":"de- + notare","meaning":"to mark out, point out, designate","meaningCN":"标出；指出；指定"}]}},{"word":"deny","ipa_uk":"/dɪˈnaɪ/","ipa_us":"/dɪˈnaɪ/","definition_zh":"否认；拒不承认；拒绝给予；拒绝准入；断绝关系","definition_en":"to say that something is not true, to refuse to give or allow something, or to disown a connection","core_image":"一个人把手掌按在桌上，把刚说出口的话推回去：不是我，没有这回事","scene":"法庭上，证人站在证人席，被问到是否见过照片上的人。 The witness had to deny that he had ever seen the man before.","sceneCN":"这里 deny 是「否认、拒不承认」（第 1 个义项：宣称某事不实）。句意：证人不得不否认自己以前见过那个人。","pos":[{"tag":"vt.","zh":"否认；拒不承认；拒绝给予；拒绝……进入"},{"tag":"vi.","zh":"否认；拒绝"}],"collocations":[{"phrase":"deny a claim","zh":"否认一项说法"},{"phrase":"deny responsibility","zh":"否认责任"},{"phrase":"deny somebody access","zh":"拒绝某人进入"},{"phrase":"deny the existence of","zh":"否认……的存在"},{"phrase":"there is no denying that","zh":"不可否认……"}],"forms":[{"label":"三单","form":"denies"},{"label":"过去式","form":"denied"},{"label":"过去分词","form":"denied"},{"label":"现在分词","form":"denying"}],"derivatives":[{"word":"denial","pos":"n.","zh":"否认；拒绝；克制"},{"word":"denier","pos":"n.","zh":"否认者；拒绝者"},{"word":"deniable","pos":"adj.","zh":"可否认的"},{"word":"deniability","pos":"n.","zh":"可否认性；可推卸性"},{"word":"undeniable","pos":"adj.","zh":"不可否认的；确凿的"}],"senses":[{"no":"01","title":"Say it is not true: push a statement back","titleCN":"否认陈述：把一句话推回去","definition":"to declare that a statement, claim, or report is not true","definitionCN":"宣称某一说法、主张或报道不真实","example":"She denied that she had ever met him.","exampleCN":"她否认自己曾见过他。","why":"The first English sense, early 14c., is 'declare to be untrue or untenable'. The verb begins as a speech act: a statement is put forward, and the denier pushes it back with a 'no'.","whyCN":"英语最早（14 世纪初）的义项是“宣称不真实、站不住脚”。这个动词一开始就是一个言语行为：别人把一句话递过来，否认者用一声“不”把它推回去。"},{"no":"02","title":"Refuse to admit: keep a fact outside","titleCN":"拒不承认：把事实关在门外","definition":"to refuse to admit or accept a fact, especially one about oneself","definitionCN":"拒绝承认或接受某一事实，尤指关于自身的事实","example":"He denies that he is afraid of failure.","exampleCN":"他拒不承认自己害怕失败。","why":"From 'declare untrue' it is a short step to 'refuse to admit'. The statement is no longer someone else's; it is a fact at the door, and the denier will not let it in.","whyCN":"从“宣称不实”到“拒不承认”只差一步。这时那句话不再是别人递来的，而是站在门口的一件事实，否认者不肯让它进来。"},{"no":"03","title":"Deny an allegation: answer a charge with 'no'","titleCN":"否认指控：用“不”回应一项罪名","definition":"to state formally that an accusation or allegation is false","definitionCN":"正式声明某项指控或罪名不实","example":"The company denied all allegations of unsafe working conditions.","exampleCN":"公司否认了所有关于工作环境不安全的指控。","why":"Legal and public life made the speech act formal. An allegation is a charge laid at your feet; to deny it is to refuse the charge in front of witnesses, not merely to disagree.","whyCN":"法律与公共生活让这个言语行为变得正式。指控是被放到你脚下的罪名；否认它，就是在证人面前拒收这项罪名，而不只是意见不同。"},{"no":"04","title":"Refuse to give: withhold what is asked","titleCN":"拒绝给予：扣住别人要的东西","definition":"to refuse to give something that someone has asked for or is entitled to","definitionCN":"拒绝给予某人索要或应得的东西","example":"The bank denied his request for a loan.","exampleCN":"银行拒绝了他的贷款申请。","why":"Late 14c. added 'refuse, refuse to grant or give'. The same 'no' now faces a request rather than a statement: what is withheld is the thing, not the truth.","whyCN":"14 世纪后期增添了“拒绝、拒绝授予或给予”。同一个“不”这时面对的是请求而不是陈述：被扣住的是东西，不是真相。"},{"no":"05","title":"Refuse access: shut the door on someone","titleCN":"拒绝准入：把人挡在门外","definition":"to refuse to allow someone to enter a place or use something","definitionCN":"拒绝允许某人进入某地或使用某物","example":"Journalists were denied access to the courtroom.","exampleCN":"记者被拒绝进入法庭。","why":"The 'refuse access to' sense is recorded from the 1660s. Here the thing withheld is entry itself, so the abstract 'no' becomes a physical door closing.","whyCN":"“拒绝进入”这一义项记录于 17 世纪 60 年代。这里被扣住的是“进入”本身，于是抽象的“不”变成一扇当着脸关上的门。"},{"no":"06","title":"Disown: deny a connection to your own","titleCN":"断绝关系：否认与自己人的关联","definition":"to refuse to acknowledge a person or thing as connected to oneself","definitionCN":"拒绝承认某人或某物与自己有关联","example":"Peter denied knowing Jesus three times that night.","exampleCN":"那天夜里，彼得三次否认自己认识耶稣。","why":"Late 14c. also records 'refuse to acknowledge, disavow, disown'. The word turns from a claim to a bond: denying a person means cutting the line that tied you to them.","whyCN":"14 世纪后期还记录了“拒绝承认、抵赖、断绝关系”。这个词从“一句话”转向“一条纽带”：否认一个人，就是切断把你和他连起来的那根线。"},{"no":"07","title":"Self-denial: say no to your own appetite","titleCN":"克制：对自己的欲望说“不”","definition":"the practice of refusing oneself pleasure or comfort, often for a moral or religious purpose","definitionCN":"拒绝给自己享乐或舒适的做法，常出于道德或宗教目的","example":"Monks practise self-denial during the fasting season.","exampleCN":"修士们在斋戒期实行自我克制。","why":"The 'no' can point inward. Since the verb means 'refuse to grant', turning it on oneself produces self-denial: the giver and the refuser are the same person.","whyCN":"这个“不”可以转向内部。既然动词意为“拒绝给予”，把它对准自己就生出 self-denial：给予者和拒绝者是同一个人。"},{"no":"08","title":"Deny oneself: give up a pleasure deliberately","titleCN":"舍弃享受：主动放弃某种快乐","definition":"to refrain from allowing oneself something enjoyable or beneficial","definitionCN":"克制自己不去享用某种愉快或有益的东西","example":"She denied herself sleep to finish the report.","exampleCN":"她为了写完报告而不让自己睡觉。","why":"This is the reflexive form of the 'withhold' sense. What is withheld is a good thing, and the person withholding it is the one who wants it.","whyCN":"这是“扣住不给”义项的反身形式。被扣住的是一件好东西，而扣住它的人正是想要它的那个人。"},{"no":"09","title":"In logic: deny a proposition","titleCN":"逻辑上：否定一个命题","definition":"in logic, to assert the contradictory of a proposition","definitionCN":"在逻辑中指断言与某命题相矛盾的判断","example":"To deny 'all swans are white', one only needs one black swan.","exampleCN":"要否定“所有天鹅都是白的”，只需要一只黑天鹅。","why":"Logic took the everyday 'say no' and made it exact: denial is the contradictory of a proposition, not a refusal to speak. The word's core act survives as a formal operation.","whyCN":"逻辑学把日常的“说不”变得精确：否定是一个命题的矛盾判断，而不是拒绝开口。这个词的核心动作在这里保存为一种形式运算。"},{"no":"10","title":"In denial: the mind refuses the fact","titleCN":"心理否认：心智拒绝接受事实","definition":"in psychology, the unconscious refusal to accept a painful truth","definitionCN":"心理学中指无意识地拒绝接受令人痛苦的事实","example":"He is still in denial about the severity of his illness.","exampleCN":"他仍不愿正视自己病情的严重程度。","why":"Freudian psychology named denial as a defence mechanism in 1914. The everyday 'refuse to admit' is pushed below awareness: the refusal still happens, but the person no longer knows they are doing it.","whyCN":"弗洛伊德心理学在 1914 年把 denial 命名为一种防御机制。日常的“拒不承认”被推到意识之下：拒绝仍在发生，但当事人已经不知道自己正在拒绝。"}],"etymology":{"intro":{"en":"Deny comes from Old French denoiir, from Latin denegare 'to deny, refuse', itself de- 'away' plus negare 'to say no'. The negative base goes back to Old Latin nec 'not' and the Italic root *nek-, from PIE *ne- 'not'.","cn":"deny 来自古法语 denoiir，再上溯拉丁语 denegare“否认、拒绝”，由 de-“离开”与 negare“说不”构成。否定词基可追到古拉丁语 nec“不”和意大利语族词根 *nek-，再上溯原始印欧语 *ne-“不”。"},"items":[{"era":"PIE (no written record)","en":"The chain ends in PIE *ne- 'not', a reconstructed form with no written record. Its exact shape is therefore uncertain; the asterisk marks a reconstruction, not a text.","cn":"这条链的尽头是原始印欧语 *ne-“不”，这是一个没有书面记录的构拟形式，确切形态来源不确定。星号表示构拟，而不是文本。"},{"era":"OLD LATIN → LATIN","en":"Old Latin nec 'not' fed Latin negare 'to refuse, say no'. Denegare added de- 'away' to make 'deny, reject, refuse'.","cn":"古拉丁语 nec“不”生出拉丁语 negare“拒绝、说不”。denegare 再加 de-“离开”，构成“否认、拒绝、回绝”。"},{"era":"OLD FRENCH (12c.)","en":"Old French denoiir meant 'deny, repudiate, withhold' and carried both the spoken denial and the withholding of a thing.","cn":"古法语 denoiir 意为“否认、抵赖、扣留不给”，同时带着口头否认和扣住东西两层意思。"},{"era":"EARLY 14c ENGLISH","en":"The first English record is 'declare to be untrue or untenable'. Later in the same century the verb also meant 'refuse to grant or give' and 'refuse to acknowledge, disown'.","cn":"英语最早记录为“宣称不真实、站不住脚”。同一世纪后期，这个动词又指“拒绝授予或给予”以及“拒绝承认、断绝关系”。"},{"era":"1660s ENGLISH","en":"The sense 'refuse access to' appears in the 1660s. Modern English keeps all of these, plus the Freudian noun denial for the mind's refusal of a painful fact.","cn":"“拒绝进入”这一义项出现在 17 世纪 60 年代。现代英语保留了以上全部义项，并增添了弗洛伊德式的名词 denial，指心智对痛苦事实的拒绝。"}]},"similar":{"note":{"en":"The first group is chosen for spelling and sound, the second for meaning, so that form and sense stay separate.","cn":"第一组按拼写和读音挑选，第二组按词义挑选，这样词形和词义不会混在一起。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"defy","ipa":"/dɪˈfaɪ/","tag":"one letter away","definition":"to openly resist or refuse to obey. It differs from deny by the f/v contrast and means resistance, not negation.","definitionCN":"公然反抗、拒不服从。与 deny 只差 f/v，但意思是反抗，不是否认。"},{"word":"denim","ipa":"/ˈdenɪm/","tag":"same opening","definition":"a strong cotton fabric used for jeans. It begins like deny but has a short e and a different ending.","definitionCN":"牛仔布。开头与 deny 相同，但 e 读短音，结尾也不同。"},{"word":"dense","ipa":"/dens/","tag":"near spelling","definition":"tightly packed or thick. It shares den- but ends in -se and is pronounced with /s/.","definitionCN":"密集的；浓密的。同样有 den-，但以 -se 结尾，读 /s/。"}]},{"heading":"NEAR MEANING","entries":[{"word":"refuse","ipa":"/rɪˈfjuːz/","tag":"withhold consent","definition":"to say or show that one will not do or accept something. It matches deny in the 'refuse to give' sense.","definitionCN":"拒绝。对应 deny 表“拒绝给予”的义项。"},{"word":"reject","ipa":"/rɪˈdʒekt/","tag":"turn down","definition":"to refuse to accept, consider, or use something. It is firmer than deny and often applies to offers or ideas.","definitionCN":"拒绝接受；驳回。比 deny 更坚决，常用于提议或想法。"},{"word":"contradict","ipa":"/ˌkɒntrəˈdɪkt/","tag":"say the opposite","definition":"to state the opposite of what someone has said. It matches deny in the 'declare untrue' sense.","definitionCN":"反驳；与……矛盾。对应 deny 表“宣称不实”的义项。"},{"word":"disown","ipa":"/dɪsˈəʊn/","tag":"cut the bond","definition":"to refuse to acknowledge a person or thing as one's own. It matches the 'deny a connection' sense.","definitionCN":"声明与……断绝关系。对应 deny 表“否认关联”的义项。"},{"word":"withhold","ipa":"/wɪðˈhəʊld/","tag":"keep back","definition":"to hold something back instead of giving it. It focuses on the thing kept, where deny focuses on the refusal.","definitionCN":"扣留；不给。强调被扣住的东西，而 deny 强调拒绝这个动作。"}]}]},"mnemonics":{"normalIntro":{"en":"These links are real: the Latin negare family behind negative and abnegate, the reflective self-denial, and the Freudian term denial.","cn":"这些联想都是真实的：negative、abnegate 背后的拉丁语 negare 词族、反身形式 self-denial，以及弗洛伊德术语 denial。"},"normal":[{"en":"deny = de- 'away' + negare 'say no': the word literally pushes the thing away with a no.","cn":"deny = de-“离开”+ negare“说不”：字面就是用一个“不”把东西推开。"},{"en":"negative is the same negare family: a negative answer is a 'no' written down as a word.","cn":"negative 属于同一个 negare 词族：否定的回答就是把一声“不”写成了一个词。"},{"en":"abnegate = ab- 'away' + negare: to abnegate a pleasure is to say no to it and put it away from you.","cn":"abnegate = ab-“离开”+ negare：abnegate 一种享乐，就是对它说不，并把它从自己身边推开。"},{"en":"self-denial turns the same 'no' inward: you are both the one asking and the one refusing.","cn":"self-denial 把同一个“不”转向内部：你既是要东西的人，也是拒绝的人。"},{"en":"in denial is the modern psychological name for the old 'refuse to admit' sense: the refusal now hides itself.","cn":"in denial 是古老的“拒不承认”义项在现代心理学里的名字：拒绝如今把自己藏了起来。"}],"abstract":[{"en":"Deny is a hand pushing back: first a sentence, then a request, then a person at the door.","cn":"deny 是一只推回去的手：先推一句话，再推一个请求，最后推站在门口的人。"},{"en":"The same 'no' can face outward and inward; that is why refusing a loan and refusing oneself sleep share one word.","cn":"同一个“不”可以朝外，也可以朝内；正因如此，拒绝贷款和不准自己睡觉会用同一个词。"},{"en":"Denial is not the absence of a fact but a door held shut against it.","cn":"否认不是事实不存在，而是一扇对着事实关紧的门。"}]},"examples":[{"en":"The government denied that the documents were genuine.","cn":"政府否认这些文件是真的。"},{"en":"He was denied entry because his visa had expired.","cn":"他因签证过期被拒绝入境。"},{"en":"There is no denying that the project has taken too long.","cn":"不可否认，这个项目拖得太久了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“抵赖”——de（离开）+ ny（说不），把事实推开、说“不”，就是否认、拒绝","word":"deny"},"root":"源自拉丁语 denegare“否认、拒绝”，由 de-“离开”+ negare“说不”构成；negare 上溯古拉丁语 nec“不”与原始印欧语 *ne-“不”（构拟，无书面记录）。经古法语 denoiir 于 14 世纪初进入英语。","sensesIntro":{"en":"Ten senses of deny, all built on one gesture: a 'no' that pushes something away. The thing pushed away can be a statement, a fact, a request, a visitor, a bond, a pleasure, or a proposition.","cn":"deny 的十个义项都建立在同一个动作上：一声把东西推开的“不”。被推开的东西可以是陈述、事实、请求、访客、亲缘、享乐，或一个命题。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand pushing something back with a firm 'no'.","cn":"核心意象：一只手用坚决的“不”把东西推回去。"},"chain":["HEAR A CLAIM","SAY NO","REFUSE TO ADMIT","WITHHOLD THE THING","SHUT THE DOOR","CUT THE BOND"],"branches":[{"senses":"S01 · S03","en":"THE SPOKEN NO: a statement is declared untrue, and a formal charge is answered with a denial.","cn":"说出口的“不”：宣称陈述不实，对正式指控给出否认。"},{"senses":"S02 · S10","en":"THE INWARD NO: a fact is refused at the door, and psychology names the refusal denial.","cn":"朝内的“不”：事实被挡在门外，心理学把这种拒绝命名为 denial。"},{"senses":"S04 · S05","en":"THE WITHHELD THING: a request is turned down, and entry itself is refused.","cn":"被扣住的东西：请求被回绝，连“进入”本身也被拒绝。"},{"senses":"S06 · S07 · S08","en":"THE BOND AND THE SELF: a person is disowned, and the same no is turned on one's own appetite.","cn":"纽带与自我：否认与某人的关系，同一个“不”也转向自己的欲望。"},{"senses":"S09","en":"THE LOGICAL NO: denial becomes the exact contradictory of a proposition.","cn":"逻辑上的“不”：否定成为命题的精确矛盾判断。"}]},"affixes":{"intro":{"en":"Deny is a Latin loan built on the negative stem neg-: denial, deniable and undeniable grow from it, while negate, negative, abnegate and renege share the same 'say no' base.","cn":"deny 是建立在否定词干 neg- 上的拉丁借词：denial、deniable、undeniable 由它长出，而 negate、negative、abnegate、renege 共用同一个“说不”的词基。"},"latinIntro":{"en":"Latin negare 'to refuse, say no' comes from Old Latin nec 'not', from Italic *nek-, from PIE *ne-. Denegare adds de- 'away'; abnegare adds ab- 'away'; negativus turns the verb into an adjective.","cn":"拉丁语 negare“拒绝、说不”来自古拉丁语 nec“不”，再上溯意大利语族 *nek-、原始印欧语 *ne-。denegare 加 de-“离开”，abnegare 加 ab-“离开”，negativus 则把动词变成形容词。"},"items":[{"word":"deny","structure":"de- (away) + negare (to say no)","meaning":"to say something is not true; to refuse","meaningCN":"否认；拒绝（de- 离开 + negare 说不）","example":"She denied the rumour outright.","exampleCN":"她断然否认了那个传言。"},{"word":"denial","structure":"deny + -al (noun)","meaning":"the act of denying; a refusal","meaningCN":"否认；拒绝（-al 构成名词）","example":"His denial convinced no one.","exampleCN":"他的否认没能说服任何人。"},{"word":"denier","structure":"deny + -er (agent noun)","meaning":"one who denies","meaningCN":"否认者（-er 表人）","example":"She is a denier of the official account.","exampleCN":"她否认官方说法。"},{"word":"deniable","structure":"deny + -able (can be)","meaning":"able to be denied","meaningCN":"可否认的（-able 能……的）","example":"The memo was written to be deniable.","exampleCN":"那份备忘录写得可以随时否认。"},{"word":"undeniable","structure":"un- (not) + deny + -able","meaning":"impossible to deny","meaningCN":"不可否认的（un- 不 + -able 可……的）","example":"Her talent is undeniable.","exampleCN":"她的才华不可否认。"},{"word":"negate","structure":"neg- (say no) + -ate (verb)","meaning":"to make ineffective or untrue","meaningCN":"否定；使无效（neg- 说不 + -ate 动词）","example":"One error can negate years of work.","exampleCN":"一个错误就能使多年的工作付诸东流。"},{"word":"negative","structure":"negat- + -ive (adjective)","meaning":"expressing a denial; not positive","meaningCN":"否定的；消极的（-ive 构成形容词）","example":"He gave a negative answer.","exampleCN":"他给出了否定的回答。"},{"word":"abnegate","structure":"ab- (away) + negare (to say no)","meaning":"to renounce or give up a right or pleasure","meaningCN":"放弃；克制（ab- 离开 + negare 说不）","example":"He abnegated his claim to the throne.","exampleCN":"他放弃了对王位的要求。"},{"word":"renege","structure":"re- (back) + negare (to say no)","meaning":"to go back on a promise","meaningCN":"背信；食言（re- 回 + negare 说不）","example":"They reneged on the deal at the last minute.","exampleCN":"他们在最后一刻背弃了协议。"}],"latinEntries":[{"word":"negare","structure":"neg- + -are (verb)","meaning":"to refuse, say no","meaningCN":"拒绝；说不"},{"word":"denegare","structure":"de- + negare","meaning":"to deny, reject, refuse","meaningCN":"否认；拒绝；回绝"},{"word":"negativus","structure":"negat- + -ivus (adjective)","meaning":"that which denies","meaningCN":"否定性的"}]}},{"word":"derive","ipa_uk":"/dɪˈraɪv/","ipa_us":"/dɪˈraɪv/","definition_zh":"获得；起源于；由……派生；推导；提取","definition_en":"to obtain something from a source, to come from an origin, or to work something out by reasoning","core_image":"一股泉水从岩缝里冒出来，顺坡流成小溪——起点只给水，流向由地势决定","scene":"Many English words derive from Latin.","sceneCN":"这里 derive 是「起源于、由……派生」（第 2 个义项：从某个源头流出来）。句意：许多英语单词源自拉丁语。画面里那股从岩缝流出的水，就是“来源”；流出来的水，就是派生词。","pos":[{"tag":"vt.","zh":"获得；推导；提取；追溯……的来源"},{"tag":"vi.","zh":"起源于；由……派生"}],"collocations":[{"phrase":"derive from","zh":"源自；由……派生"},{"phrase":"be derived from","zh":"取自；由……衍生而来"},{"phrase":"derive pleasure from","zh":"从……中获得乐趣"},{"phrase":"derive benefit from","zh":"从……中获益"},{"phrase":"derive a formula","zh":"推导出一个公式"}],"forms":[{"label":"三单","form":"derives"},{"label":"过去式","form":"derived"},{"label":"过去分词","form":"derived"},{"label":"现在分词","form":"deriving"}],"derivatives":[{"word":"derivation","pos":"n.","zh":"起源；派生；推导"},{"word":"derivative","pos":"n./adj.","zh":"衍生物；派生的；缺乏原创性的"},{"word":"derivational","pos":"adj.","zh":"派生法的；构词派的"},{"word":"derivable","pos":"adj.","zh":"可推导的；可派生的"},{"word":"derivatively","pos":"adv.","zh":"派生地；间接地"}],"senses":[{"no":"01","title":"Draw off a stream: lead water from its source","titleCN":"引水：把水从源头引走","definition":"literally, to lead or draw off a stream of water from its source","definitionCN":"字面义：把一股水从它的源头引开、引走","example":"The ancient engineers derived water from the river into a network of canals.","exampleCN":"古代工程师把河水引出来，导入一个运河网络。","why":"Latin derivare was built from the phrase de rivo, 'from the stream'. The original picture is hydraulic: a channel is cut so that water leaves its source and runs elsewhere.","whyCN":"拉丁语 derivare 由短语 de rivo“从溪流中”构成。最初的画面是水利工程：挖一条渠，让水离开源头，流到别处去。"},{"no":"02","title":"Come from an origin: flow down from a source","titleCN":"起源于：从某个源头流下来","definition":"to come or originate from a particular source","definitionCN":"来自或起源于某一特定源头","example":"The custom derives from an ancient harvest festival.","exampleCN":"这一习俗源自一个古老的丰收节。","why":"Late 14c. English recorded 'descend from'. The water image is kept but the stream becomes lineage or history: a thing is traced back and found to flow out of an earlier source.","whyCN":"14 世纪后期的英语记录了“descend from（由……传下）”。水的意象保留下来，只是溪流变成了血统或历史：把事物往回追，发现它从更早的源头流出来。"},{"no":"03","title":"Obtain from a source: get something out of something","titleCN":"获得：从某物中取得某物","definition":"to obtain or gain something from a particular source","definitionCN":"从某一特定来源获得或取得某物","example":"The company derives most of its income from overseas sales.","exampleCN":"这家公司的大部分收入来自海外销售。","why":"From the 1560s derive meant 'get, gain, obtain' as from a source. If something flows out of a source, the receiver can catch it: origin becomes supply.","whyCN":"从 16 世纪 60 年代起，derive 有“从来源处取得、获得”的意思。既然有东西从源头流出来，接收者就能接住它：起源变成了供给。"},{"no":"04","title":"Derive pleasure: draw a feeling out of an activity","titleCN":"获得乐趣：从一件事里汲取感受","definition":"to get a feeling such as pleasure, satisfaction, or confidence from something","definitionCN":"从某事物中获得快乐、满足或信心等感受","example":"She derives great satisfaction from teaching young children.","exampleCN":"她从教小孩子中获得很大的满足感。","why":"The 'obtain' sense extends to immaterial things. Pleasure is treated as a stream that an activity gives off, and the person draws it off for themselves.","whyCN":"“获得”义扩展到看不见的东西。快乐被当作一项活动流出来的水，人把它引到自己这里。"},{"no":"05","title":"Trace the derivation: follow the line back","titleCN":"追溯来源：沿这条线往回走","definition":"to trace or show the origin of something, especially a word","definitionCN":"追溯或说明某事物的来源，尤指词语的来源","example":"Etymologists derive the name from an old Germanic root.","exampleCN":"词源学家把这个名称追溯到一个古老的日耳曼语词根。","why":"Around 1600 the verb took the sense 'trace or show derivation'. The direction reverses: instead of flowing forward from the source, the researcher walks upstream along the channel.","whyCN":"约 1600 年，这个动词取得“追溯或说明来源”的意思。方向反了过来：不再是水从源头往前流，而是研究者沿渠往上走。"},{"no":"06","title":"In linguistics: a word grows out of another","titleCN":"语言学：一个词从另一个词长出来","definition":"of a word, to arise from another word or root by a process of word formation","definitionCN":"指词语通过构词过程从另一词或词根产生","example":"'Happiness' derives from the adjective 'happy'.","exampleCN":"happiness 由形容词 happy 派生而来。","why":"The 1550s applied the verb to words. A suffix is a small channel: the base word is the source, and the new word is water led off from it under a new shape.","whyCN":"16 世纪 50 年代把这个动词用到了词语上。后缀就是一条小渠道：基础词是源头，新词是被引出来、换了个形状的水。"},{"no":"07","title":"Derive by reasoning: reach a result step by step","titleCN":"推导：一步一步走到结论","definition":"to obtain a result, conclusion, or formula by a process of reasoning or calculation","definitionCN":"通过推理或计算过程得出结果、结论或公式","example":"From these two premises we can derive a contradiction.","exampleCN":"从这两个前提出发，我们可以推导出一个矛盾。","why":"From c. 1500 derive meant 'obtain by a process of reasoning'. The source is now a premise, and the conclusion is what is drawn off from it by rule — a channel of logic rather than water.","whyCN":"约 1500 年起，derive 意为“通过推理过程获得”。源头这时成了前提，结论是按规则从前提中引出来的——这是一条逻辑的渠道，不是水渠。"},{"no":"08","title":"In chemistry: extract a substance from a source","titleCN":"化学上：从原料中提取物质","definition":"to obtain a substance from a material by a chemical or physical process","definitionCN":"通过化学或物理过程从某种材料中取得物质","example":"The drug is derived from a plant grown in the Andes.","exampleCN":"这种药物提取自一种生长在安第斯山脉的植物。","why":"Chemistry makes the 'draw off' image literal again: a substance is separated out of the material that holds it, as water is led out of a spring.","whyCN":"化学让“引出”的意象重新变得具体：把一种物质从承载它的材料里分离出来，就像把水从泉眼里引出来。"},{"no":"09","title":"Derive from an ancestor: come down a family line","titleCN":"承袭：沿家族血脉传下来","definition":"to descend or be descended from an ancestor or earlier group","definitionCN":"从某位祖先或更早的群体传下来、为其后裔","example":"Many of the town's families derive from settlers who arrived in the 1700s.","exampleCN":"镇上许多家族都是 18 世纪初来定居者的后裔。","why":"The oldest English sense is 'descend from'. Blood is imagined as a stream running through generations: each person is water drawn from an earlier spring.","whyCN":"英语最古老的义项就是“由……传下”。血脉被想象成一条穿过世代的水流：每个人都是从更早的泉眼里引出来的水。"}],"etymology":{"intro":{"en":"Derive comes from Latin derivare 'to lead or draw off a stream from its source', from de rivo 'from the stream'. It entered English through Old French deriver in the late 14c., first as 'descend from', then spread to reasoning, words, and chemistry.","cn":"derive 来自拉丁语 derivare“把水从源头引出”，字面是 de rivo“从溪流中”。它经古法语 deriver 于 14 世纪后期进入英语，最早意为“由……传下”，后来扩展到推理、词语和化学。"},"items":[{"era":"PIE (no written record)","en":"The stream word goes back to a reconstructed PIE root *rei- 'to run, flow'. This form has no written record, so its exact shape is uncertain and must not be treated as a known word.","cn":"“溪流”这个词上溯到一个构拟的原始印欧语词根 *rei-“跑、流”。这一形式没有书面记录，确切形态来源不确定，不能当作已知的词来用。"},{"era":"LATIN (before 1C BC)","en":"Latin rivus meant 'a stream, brook'. The phrase de rivo 'from the stream' produced derivare 'to lead or draw off a stream', and by extension 'to turn aside'.","cn":"拉丁语 rivus 意为“溪流、小河”。短语 de rivo“从溪流中”生出 derivare“把水引出、引走”，再引申为“使转向”。"},{"era":"OLD FRENCH (12-13c.)","en":"Old French deriver meant 'to flow, pour out; derive, originate', keeping both the water image and the idea of coming from a source.","cn":"古法语 deriver 意为“流出、倾出；派生、起源”，同时保留了水的意象和“来自某源头”的意思。"},{"era":"LATE 14c ENGLISH","en":"The first English sense is 'descend from', used of people and things that come down from an earlier origin. The water image becomes a line of descent.","cn":"英语最早的义项是“由……传下”，用于从更早源头传下来的人或物。水的意象变成了血统或传承的线。"},{"era":"c. 1500-1660s ENGLISH","en":"Around 1500 the verb added 'obtain by reasoning'; the 1550s applied it to word formation; c. 1600 came 'trace or show derivation'; the 1560s added 'get, gain, obtain'; the 1660s added 'arise, spring from'.","cn":"约 1500 年增添“通过推理获得”；16 世纪 50 年代用于构词；约 1600 年出现“追溯或说明来源”；16 世纪 60 年代增添“取得、获得”；17 世纪 60 年代增添“由……产生”。"}]},"similar":{"note":{"en":"The first group is chosen for spelling and sound, the second for meaning, so that form and sense stay separate.","cn":"第一组按拼写和读音挑选，第二组按词义挑选，这样词形和词义不会混在一起。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"deprive","ipa":"/dɪˈpraɪv/","tag":"de- + private","definition":"to take something away from someone. It shares de- and the stress pattern but means removal, not origin.","definitionCN":"剥夺。同样以 de- 开头、重音相同，但意思是拿走，不是起源。"},{"word":"drive","ipa":"/draɪv/","tag":"near sound","definition":"to operate a vehicle or push something forward. It sounds close to derive but has a long i in the first syllable.","definitionCN":"驾驶；驱动。读音与 derive 接近，但第一音节是长元音 /aɪ/。"},{"word":"deride","ipa":"/dɪˈraɪd/","tag":"de- + ridere","definition":"to laugh at someone scornfully. It looks like derive with a different final consonant and means mockery.","definitionCN":"嘲笑；愚弄。形似 derive，只是结尾辅音不同，意思是嘲弄。"}]},{"heading":"NEAR MEANING","entries":[{"word":"obtain","ipa":"/əbˈteɪn/","tag":"get","definition":"to get something, especially by effort. It matches derive in the 'gain from a source' sense.","definitionCN":"获得。对应 derive 表“从来源取得”的义项。"},{"word":"originate","ipa":"/ɒrɪdʒɪˈneɪt/","tag":"begin","definition":"to begin or come from a particular place or cause. It matches the 'come from an origin' sense.","definitionCN":"起源；发源。对应 derive 表“起源于”的义项。"},{"word":"stem from","ipa":"/stem frɒm/","tag":"phrasal origin","definition":"to be caused by or come from something. It is the everyday spoken match for derive from.","definitionCN":"源于；由……造成。是 derive from 的日常口语对应说法。"},{"word":"deduce","ipa":"/dɪˈdjuːs/","tag":"reason out","definition":"to reach a conclusion by reasoning from known facts. It matches the logical 'derive' sense.","definitionCN":"推论；演绎。对应 derive 表“推导”的义项。"},{"word":"extract","ipa":"/ɪkˈstrækt/","tag":"draw out","definition":"to remove or obtain a substance from something. It matches the chemical sense of derive.","definitionCN":"提取；抽出。对应 derive 表“提取”的义项。"}]}]},"mnemonics":{"normalIntro":{"en":"These links are real: the Latin rivus 'stream' behind river and rivulet, the de rivo phrase inside derivare, and the reasoning sense recorded around 1500.","cn":"这些联想都是真实的：river、rivulet 背后拉丁语 rivus“溪流”，derivare 里的 de rivo 短语，以及约 1500 年记录的推理义。"},"normal":[{"en":"derive = de- 'from' + rivus 'stream': to derive is to lead a stream out of its source.","cn":"derive = de-“从”+ rivus“溪流”：derive 就是把一股水从源头引出来。"},{"en":"river and rivulet share the same rivus: a river is simply the stream that got big.","cn":"river 和 rivulet 共用同一个 rivus：river 不过是长大的那条溪。"},{"en":"A derivative is water led off from an older word: 'happiness' is a channel running out of 'happy'.","cn":"derivative 是从更老的词里引出来的水：happiness 就是从 happy 流出的一条渠。"},{"en":"In maths, derive a formula: the premises are the spring, and the conclusion is the water you lead off.","cn":"数学里 derive 一个公式：前提是泉眼，结论是你引出来的水。"},{"en":"In chemistry, a derivative is a substance drawn out of the material that held it, exactly like water drawn from a spring.","cn":"化学里的 derivative 是从承载它的材料里引出的物质，和从泉眼引水一模一样。"}],"abstract":[{"en":"Origin is upstream; derivation is the channel; the derived thing is the water that arrives.","cn":"源头在上游，派生是那条渠，派生出来的东西是流到的水。"},{"en":"To derive is to answer 'where does this come from?' by walking up the channel instead of down it.","cn":"derive 就是回答“这东西从哪来”：沿渠往上走，而不是顺流而下。"},{"en":"The same word covers water, blood, words, and logic because all four are imagined as flowing from a source.","cn":"同一个词能覆盖水、血脉、词语和逻辑，因为这四样都被想象成从某个源头流出来的。"}]},"examples":[{"en":"The word 'salary' derives from the Latin for salt.","cn":"salary 这个词源自拉丁语中表示“盐”的词。"},{"en":"Children derive a sense of security from a stable routine.","cn":"孩子从稳定的日常安排中获得安全感。"},{"en":"We can derive the second equation from the first.","cn":"我们可以从第一个方程推导出第二个方程。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“地来水”——de（从）+ river（河），水从地里那条河引出来，就是获得、起源、派生","word":"derive"},"root":"源自拉丁语 derivare“把水从源头引出”，由 de rivo“从溪流中”构成，rivus“溪流”上溯原始印欧语 *rei-“跑、流”（构拟，无书面记录）；经古法语 deriver 于 14 世纪后期进入英语。","sensesIntro":{"en":"Nine senses of derive, all built on one picture: water led out of a source. The channel can be a river, a family line, a word stem, a premise, or a chemical process.","cn":"derive 的九个义项都建立在一个画面上：把水从源头引出来。这条渠可以是河、血统、词干、前提，或一道化学过程。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stream led out of its spring and made to run elsewhere.","cn":"核心意象：把一股水从泉眼里引出，让它流到别处。"},"chain":["FIND THE SPRING","CUT THE CHANNEL","LET IT FLOW","CATCH THE WATER","TRACE IT BACK","NAME THE SOURCE"],"branches":[{"senses":"S01 · S02 · S09","en":"FROM A SOURCE: water is led off, a thing descends from an origin, and a person comes down a family line.","cn":"从源头而来：水被引出，事物由源头传下，人沿家族血脉承袭。"},{"senses":"S03 · S04","en":"WHAT IS RECEIVED: income is gained from sales, and satisfaction is drawn out of an activity.","cn":"所获之物：从销售中获得收入，从一项活动中汲取满足。"},{"senses":"S05 · S06","en":"THE LINE BACK: etymology walks upstream, and a suffix leads a new word out of an old one.","cn":"往回的那条线：词源学逆流而上，后缀把新词从旧词引出。"},{"senses":"S07","en":"THE CHANNEL OF REASON: a conclusion is drawn off from premises by rule.","cn":"推理的渠道：结论按规则从前提出被引出。"},{"senses":"S08","en":"THE CHEMICAL CHANNEL: a substance is separated out of the material that holds it.","cn":"化学的渠道：把物质从承载它的材料中分离出来。"}]},"affixes":{"intro":{"en":"Derive is a Latin loan built on rivus 'stream': derivation, derivative and derivable grow from the verb, while river, rivulet and rival share the same water image.","cn":"derive 是建立在 rivus“溪流”上的拉丁借词：derivation、derivative、derivable 由这个动词长出，而 river、rivulet、rival 共用同一个水的意象。"},"latinIntro":{"en":"Latin rivus 'stream' gives derivare 'lead off a stream' and rivulus 'a small stream'. Rivalis originally meant one who uses the same stream, which is why rivalry is about sharing a channel.","cn":"拉丁语 rivus“溪流”生出 derivare“引走水流”和 rivulus“小溪”。rivalis 原指“共用同一条溪的人”，所以 rivalry 的本义与共用一条渠道有关。"},"items":[{"word":"derive","structure":"de- (from) + rivus (stream)","meaning":"to lead off; to come from a source","meaningCN":"获得；起源；派生（de- 从 + rivus 溪流）","example":"The name derives from an old dialect word.","exampleCN":"这个名字源自一个古老的方言词。"},{"word":"derivation","structure":"deriv- + -ation (noun of action)","meaning":"the act of deriving; origin","meaningCN":"派生；起源；推导（-ation 构成名词）","example":"The derivation of the term is disputed.","exampleCN":"这个术语的来源尚有争议。"},{"word":"derivative","structure":"deriv- + -ative (adjective/noun)","meaning":"derived from something else","meaningCN":"派生的；衍生物（-ative 构成形容词/名词）","example":"The film is derivative of earlier horror movies.","exampleCN":"这部影片模仿了早先的恐怖片。"},{"word":"derivational","structure":"derivation + -al (adjective)","meaning":"relating to word derivation","meaningCN":"构词派生的（-al 构成形容词）","example":"The suffix is derivational, not inflectional.","exampleCN":"这个后缀是派生后缀，不是屈折后缀。"},{"word":"derivable","structure":"derive + -able (can be)","meaning":"able to be derived","meaningCN":"可推导的；可派生的（-able 能……的）","example":"The result is derivable from the data.","exampleCN":"这个结果可以从数据中推导出来。"},{"word":"river","structure":"Latin riparius / rivus (stream)","meaning":"a large natural stream of water","meaningCN":"河流（与 rivus 溪流同源）","example":"The river runs through the old town.","exampleCN":"这条河穿过老城。"},{"word":"rivulet","structure":"rivulus (small stream) + -et (diminutive)","meaning":"a very small stream","meaningCN":"小溪（-et 表小）","example":"A rivulet trickled down the rock.","exampleCN":"一条小溪顺着岩石流下。"},{"word":"rival","structure":"rivalis (one sharing a stream)","meaning":"a competitor for the same thing","meaningCN":"竞争者；对手（原指共用一条溪的人）","example":"The two firms are rivals for the same market.","exampleCN":"这两家公司是同一市场的竞争对手。"},{"word":"rivalry","structure":"rival + -ry (state, noun)","meaning":"the state of being rivals","meaningCN":"竞争；对抗（-ry 表状态）","example":"Their rivalry goes back to school days.","exampleCN":"他们的竞争从学生时代就开始了。"}],"latinEntries":[{"word":"rivus","structure":"rivus (noun)","meaning":"a stream, brook","meaningCN":"溪流；小河"},{"word":"derivare","structure":"de rivo / de- + rivus","meaning":"to lead or draw off a stream","meaningCN":"把水从溪流中引出"},{"word":"rivulus","structure":"rivus + -ulus (diminutive)","meaning":"a small stream","meaningCN":"小溪"}]}},{"word":"describe","ipa_uk":"/dɪˈskraɪb/","ipa_us":"/dɪˈskraɪb/","definition_zh":"描述；叙述；描绘；形容；画出（轨迹）","definition_en":"to say or write what someone or something is like, or to trace out a shape or path","core_image":"一支笔沿着物体边缘走一圈，把形状留在纸上——不是拍照，是用线勾出特征","scene":"The police asked her to describe the man she had seen.","sceneCN":"这里 describe 是「描述、形容」（第 1 个义项：用语言说出某人某物的样子）。句意：警方让她描述她看到的那个男人。画面里那支沿边缘走的笔，就是把特征一条条说出来的动作。","pos":[{"tag":"vt.","zh":"描述；叙述；描绘；形容；画出（图形、轨迹）"}],"collocations":[{"phrase":"describe in detail","zh":"详细描述"},{"phrase":"describe somebody as","zh":"把某人说成……"},{"phrase":"describe the process","zh":"描述过程"},{"phrase":"be described as","zh":"被形容为"},{"phrase":"accurately describe","zh":"准确地描述"}],"forms":[{"label":"三单","form":"describes"},{"label":"过去式","form":"described"},{"label":"过去分词","form":"described"},{"label":"现在分词","form":"describing"}],"derivatives":[{"word":"description","pos":"n.","zh":"描述；说明；种类"},{"word":"descriptive","pos":"adj.","zh":"描述性的；描写的"},{"word":"descriptively","pos":"adv.","zh":"描述地；描写地"},{"word":"describable","pos":"adj.","zh":"可描述的"},{"word":"indescribable","pos":"adj.","zh":"难以描述的"}],"senses":[{"no":"01","title":"Say what it is like: put its features into words","titleCN":"描述：把它的样子说成话","definition":"to say or write what someone or something is like by giving its features","definitionCN":"通过说出特征，用口头或书面方式说明某人或某物的样子","example":"Can you describe the jacket he was wearing?","exampleCN":"你能描述一下他穿的那件夹克吗？","why":"From c. 1300 describe meant 'represent orally or by writing'. The Latin base describere is 'write down, sketch'; language takes the place of the pen and the listener is given the outline.","whyCN":"从约 1300 年起，describe 意为“用口头或书面方式表现”。拉丁语基础 describere 是“写下、勾画”；这时语言代替了笔，听者得到的是被勾出的轮廓。"},{"no":"02","title":"Tell the story of an event: give an account","titleCN":"叙述事件：把事情经过讲出来","definition":"to give an account of an event, including what happened and in what order","definitionCN":"叙述一件事的经过，包括发生了什么以及先后顺序","example":"The report describes how the fire started.","exampleCN":"这份报告叙述了火灾是如何开始的。","why":"The pen can trace time as well as shape. Once describe covers 'represent orally or by writing', an event can be laid out line by line — first this, then that.","whyCN":"笔不只能勾出形状，也能勾出时间。一旦 describe 覆盖“用口头或书面表现”，一件事就可以被一条线一条线地铺开——先这样，再那样。"},{"no":"03","title":"Paint with detail: make the reader see it","titleCN":"细描：让读者看见那个画面","definition":"to give a detailed and vivid account that lets someone imagine a scene","definitionCN":"给出详细而生动的叙述，使人能在脑中想象出场景","example":"The novel describes the harbour at dawn in precise detail.","exampleCN":"这部小说细致地描写了黎明时的港口。","why":"Description sharpens when the writer selects sensory detail. The same 'outline' becomes a dense drawing: the words do not merely label, they make the reader's eye fill in the scene.","whyCN":"当作者挑出感官细节时，描述就变锋利了。同一个“轮廓”变成了密集的图画：词语不再只是贴标签，而是让读者的眼睛自己把场景补全。"},{"no":"04","title":"Depict in art: draw the figure on a surface","titleCN":"描绘：在平面上画出形象","definition":"to represent a person, scene, or object in a drawing, painting, or other artwork","definitionCN":"在素描、绘画或其他艺术作品中表现人物、场景或物体","example":"The mural describes a busy market day in the old city.","exampleCN":"这幅壁画描绘了老城繁忙的集日。","why":"The oldest sense of Latin describere is 'write down, copy; sketch, represent'. Art kept the literal hand: the pen or brush marks a surface until the figure appears.","whyCN":"拉丁语 describere 最古老的意思是“写下、摹写；素描、表现”。艺术保留了这个字面上的手：笔在平面上留下痕迹，直到形象出现。"},{"no":"05","title":"Draw the outline: mark the boundary of a shape","titleCN":"勾轮廓：把形状的边界画出来","definition":"to delineate or mark the form or outline of something","definitionCN":"勾出或标出某物的形状、轮廓","example":"With a compass, describe a circle of radius five centimetres.","exampleCN":"用圆规画出一个半径为五厘米的圆。","why":"Around 1400 describe meant 'delineate or mark the form or figure of, outline'. This is the word at its most physical: a line goes around the edge and closes the shape.","whyCN":"约 1400 年，describe 意为“勾出或标出形状、轮廓”。这是这个词最物理的一面：一条线沿边缘走一圈，把形状围起来。"},{"no":"06","title":"Of a moving body: trace a path","titleCN":"轨迹：运动物体划出的路线","definition":"of a moving object, to move along and thereby trace out a particular path or figure","definitionCN":"指运动物体沿某路线移动，从而划出特定的轨迹或图形","example":"The satellite describes an orbit around the earth every ninety minutes.","exampleCN":"这颗卫星每九十分钟绕地球运行一圈。","why":"Late 14c. records 'form or trace by motion'. Here the moving thing is the pen: its path leaves a line in space, so describe means the route itself, not the words about it.","whyCN":"14 世纪后期记录了“通过运动形成或划出”。这里运动的东西就是笔：它的路线在空间里留下一条线，于是 describe 指的是路线本身，而不是关于路线的话。"},{"no":"07","title":"Describe someone as: pin a label on them","titleCN":"把某人说成：给他贴上一个标签","definition":"to characterize or label a person or thing in a particular way","definitionCN":"以某种方式给某人或某物定性、贴标签","example":"Critics described the film as 'beautiful but empty'.","exampleCN":"评论家把这部电影说成“美则美矣，空洞无物”。","why":"A description can become a verdict. The outline you draw around someone turns into the category you put them in, so 'describe as' carries a judgement as well as a picture.","whyCN":"描述可以变成判词。你绕着某人画出的轮廓，变成你把他归入的那一类，所以 describe as 既给画面，也带判断。"},{"no":"08","title":"Old sense: interpret or explain","titleCN":"旧义：解释、说明","definition":"in early use, to interpret or explain the meaning of something","definitionCN":"早期用法中指解释或说明某事物的含义","example":"The medieval text describes the dream as a warning from God.","exampleCN":"这份中世纪文本把这个梦解释为来自上帝的警告。","why":"The first English record, mid-13c., is 'interpret, explain', a sense now obsolete. To describe was to read a meaning off a text, closer to 'construe' than to 'report'.","whyCN":"英语最早的记录（13 世纪中期）是“解释、说明”，这一义项今已废弃。那时的 describe 是从文本上读出一个意思，更接近“解读”，而不是“报告”。"},{"no":"09","title":"Beyond words: what cannot be described","titleCN":"言语之外：无法被描述的东西","definition":"used in the negative to say that something is too extreme or strange for words","definitionCN":"用于否定结构，表示某事物极端或奇特得无法用语言表达","example":"The view from the summit is hard to describe.","exampleCN":"山顶的景色难以描述。","why":"The limit of the word defines it. Because describe means tracing a full outline, whatever exceeds the outline becomes 'indescribable' — the shape is there, but no line can close around it.","whyCN":"词的边界反过来定义了它。因为 describe 意为勾出完整轮廓，凡是超出轮廓的东西就成了 indescribable——形状在那里，却没有一条线能把它围合。"}],"etymology":{"intro":{"en":"Describe comes from Latin describere 'to write down, copy; sketch, represent', from de- 'down' and scribere 'to write'. It reached English through Old French descrivre in the mid-13c., first meaning 'interpret, explain', then 'represent in words', and later 'trace a shape'.","cn":"describe 来自拉丁语 describere“写下、摹写；素描、表现”，由 de-“向下”与 scribere“写”构成。它经古法语 descrivre 于 13 世纪中期进入英语，最早意为“解释、说明”，继而“用语言表现”，后来又引申出“勾出形状”。"},"items":[{"era":"PIE (no written record)","en":"Scribere is traced to a reconstructed PIE root *skribh- 'to cut', the idea being that early writing was cut or scratched into a surface. The root has no written record, so its exact form is uncertain.","cn":"scribere 上溯到一个构拟的原始印欧语词根 *skribh-“切、划”。其想法是最早的书写是刻划在表面上。这个词根没有书面记录，确切形态来源不确定。"},{"era":"LATIN (before 1C BC)","en":"Describere meant 'to write down, copy; sketch, represent'. De- 'down' plus scribere 'write' gives the picture of a line drawn down and around a form.","cn":"describere 意为“写下、摹写；素描、表现”。de-“向下”加 scribere“写”，给出的是沿一个形状向下、再绕一圈画线的画面。"},{"era":"OLD FRENCH (13c.)","en":"Old French descrivre / descrire meant 'describe, represent' and supplied the form that English borrowed.","cn":"古法语 descrivre / descrire 意为“描述、表现”，提供了英语借入的词形。"},{"era":"MID-13c ENGLISH","en":"The first English record, descriven, means 'interpret, explain', a sense now obsolete. By c. 1300 it also means 'represent orally or by writing'.","cn":"英语最早记录 descriven 意为“解释、说明”，此义今已废弃。到约 1300 年，它又指“用口头或书面方式表现”。"},{"era":"LATE 14c-1450 ENGLISH","en":"Late 14c. adds 'form or trace by motion'; c. 1400 adds 'delineate or mark the form or figure of, outline'. The Latin b was restored in spelling c. 1450.","cn":"14 世纪后期增添“通过运动形成或划出”；约 1400 年增添“勾出或标出形状、轮廓”。约 1450 年拼写中恢复了拉丁语的 b。"}]},"similar":{"note":{"en":"The first group is chosen for spelling and sound, the second for meaning, so that form and sense stay separate.","cn":"第一组按拼写和读音挑选，第二组按词义挑选，这样词形和词义不会混在一起。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"descry","ipa":"/dɪˈskraɪ/","tag":"near spelling","definition":"to catch sight of something far away. It looks like describe but ends in -y and means seeing, not saying.","definitionCN":"望见；看出。形似 describe，但以 -y 结尾，意思是看见，不是说。"},{"word":"discrete","ipa":"/dɪˈskriːt/","tag":"near sound","definition":"separate and distinct. It is often confused with discreet and sounds close to the middle of describe.","definitionCN":"分离的；离散的。常与 discreet 混淆，读音接近 describe 的中段。"},{"word":"prescribe","ipa":"/prɪˈskraɪb/","tag":"same -scribe family","definition":"to order or recommend a treatment or rule. It shares -scribe but has pre- 'before' instead of de-.","definitionCN":"开处方；规定。同属 -scribe 词族，但前缀是 pre-“在前”，不是 de-。"}]},{"heading":"NEAR MEANING","entries":[{"word":"depict","ipa":"/dɪˈpɪkt/","tag":"show in image","definition":"to show something in a picture or in words. It is closer to painting than describe is.","definitionCN":"描绘；描写。比 describe 更偏向“画出图像”。"},{"word":"portray","ipa":"/pɔːˈtreɪ/","tag":"represent a person","definition":"to represent someone or something in a particular way, especially in art or writing. It often implies a stance.","definitionCN":"刻画；表现。常暗示一种立场或角度。"},{"word":"narrate","ipa":"/nəˈreɪt/","tag":"tell in order","definition":"to tell a story or give an account of events in order. It matches describe in the 'give an account' sense.","definitionCN":"叙述；讲述。对应 describe 表“叙述经过”的义项。"},{"word":"recount","ipa":"/rɪˈkaʊnt/","tag":"tell what happened","definition":"to tell someone about an event, especially one you experienced. It stresses the telling of a sequence.","definitionCN":"讲述；叙述。强调按顺序讲出亲身经历。"},{"word":"illustrate","ipa":"/ɪˈlʌstreɪt/","tag":"make clear by example","definition":"to explain or make something clear with examples or pictures. It adds a purpose that describe need not have.","definitionCN":"说明；举例说明。它多了一层“为了让对方明白”的目的，而 describe 不一定有。"}]}]},"mnemonics":{"normalIntro":{"en":"These links are real: the Latin scribere 'write' family behind scribe and manuscript, the de- 'down' in describere, and the 1400 sense 'mark the outline'.","cn":"这些联想都是真实的：scribe、manuscript 背后拉丁语 scribere“写”词族，describere 里的 de-“向下”，以及约 1400 年“勾出轮廓”的义项。"},"normal":[{"en":"describe = de- 'down' + scribere 'write': to describe is to write the thing down line by line.","cn":"describe = de-“向下”+ scribere“写”：describe 就是把那东西一行一行写下来。"},{"en":"scribe, script and manuscript all share scribere 'write'. A description is a script of what the eye saw.","cn":"scribe、script、manuscript 都共用 scribere“写”。description 就是眼睛所见的“脚本”。"},{"en":"prescribe = pre- 'before' + scribere: the doctor writes the rule before you follow it; describe writes down what is already there.","cn":"prescribe = pre-“在前”+ scribere：医生先把规则写下，你再照做；describe 写下的则是已经在那里的东西。"},{"en":"In geometry, to describe a circle is to let the compass trace the outline — the oldest 'draw a line around' sense.","cn":"几何里 describe a circle 是让圆规把轮廓划出来——这正是最古老的“绕圈画线”义。"},{"en":"Indescribable does not mean 'no words exist'; it means no line can close around the thing.","cn":"indescribable 不是“没有词”，而是没有一条线能把那东西围合起来。"}],"abstract":[{"en":"Describe is a pen walking around an object and leaving its outline in the listener's mind.","cn":"describe 是一支笔绕着物体走一圈，把轮廓留在听者心里。"},{"en":"Words can sketch a shape, tell a sequence, or draw a path in space; all three are the same line in different materials.","cn":"词语可以勾出形状、讲出顺序，或在空间里画出路线；三者是同一条线落在不同材料上。"},{"en":"A description ends where the outline can no longer close; that is where 'indescribable' begins.","cn":"描述在轮廓无法闭合的地方结束；那里正是“难以描述”开始的地方。"}]},"examples":[{"en":"She described the kitchen in enough detail for us to picture it.","cn":"她把厨房描述得足够详细，让我们能在脑中想象出来。"},{"en":"The witness described the car as dark blue and very old.","cn":"证人把那辆车说成深蓝色、非常旧。"},{"en":"The planet describes a nearly circular orbit around its star.","cn":"这颗行星围绕它的恒星画出近乎圆形的轨道。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“地写scribe”——de（向下）+ scribe（写），把眼前的东西一笔一笔写下来，就是描述","word":"describe"},"root":"源自拉丁语 describere“写下、摹写；素描”，由 de-“向下”+ scribere“写”构成，scribere 上溯原始印欧语 *skribh-“切、划”（构拟，无书面记录）；经古法语 descrivre 于 13 世纪中期进入英语。","sensesIntro":{"en":"Nine senses of describe, from words that give an account to a compass that draws a circle. Every sense keeps one act: a line is made to follow a form, whether the line is made of speech, ink, or motion.","cn":"describe 的九个义项，从用话讲出经过，到用圆规画一个圆。每个义项都保留同一个动作：让一条线沿某个形状走，无论这条线是言语、墨水还是运动。"},"semanticMap":{"core":{"en":"CORE IMAGE: a line drawn along the edge of a thing until its shape appears.","cn":"核心意象：一条线沿着事物的边缘走，直到它的形状显现。"},"chain":["SEE THE FORM","FOLLOW THE EDGE","LEAVE A LINE","NAME THE FEATURES","TELL THE ORDER","CLOSE THE SHAPE"],"branches":[{"senses":"S01 · S03","en":"WORDS AS A PEN: features are put into speech, and detail makes the reader see the scene.","cn":"以词为笔：把特征说成话，细节让读者看见场景。"},{"senses":"S02 · S07","en":"THE ACCOUNT AND THE LABEL: an event is told in order, and a person is characterized by a label.","cn":"叙述与标签：事件按顺序讲出，人被一个标签定性。"},{"senses":"S04 · S05","en":"THE DRAWN FORM: art depicts a figure, and geometry marks an outline.","cn":"画出的形：艺术描绘形象，几何勾出轮廓。"},{"senses":"S06","en":"THE PATH IN SPACE: a moving body traces the line by moving along it.","cn":"空间中的路线：运动物体一边走，一边把线划出来。"},{"senses":"S08 · S09","en":"THE OLD AND THE LIMIT: 'interpret' is the obsolete first sense, and 'indescribable' marks where the outline fails.","cn":"旧义与边界：“解释”是最早的废弃义，“难以描述”标出轮廓失效之处。"}]},"affixes":{"intro":{"en":"Describe is a Latin loan built on the stem scrib- 'write': description, descriptive and describable grow from it, while scribe, script, manuscript, prescribe and subscribe share the same writing base.","cn":"describe 是建立在词干 scrib-“写”上的拉丁借词：description、descriptive、describable 由它长出，而 scribe、script、manuscript、prescribe、subscribe 共用同一个“写”的词基。"},"latinIntro":{"en":"Latin scribere 'to write' is the base of describere 'write down', praescribere 'write before', subscribare 'write beneath', and scriptum 'something written'. The family is about making marks on a surface.","cn":"拉丁语 scribere“写”是 describere“写下”、praescribere“写在前”、subscribare“写在下面”和 scriptum“写下的东西”的基础。这个词族讲的是在表面上留下痕迹。"},"items":[{"word":"describe","structure":"de- (down) + scribere (to write)","meaning":"to write down; to represent in words","meaningCN":"描述；叙述（de- 向下 + scribere 写）","example":"He described the room in careful detail.","exampleCN":"他仔细描述了这个房间。"},{"word":"description","structure":"descript- + -ion (noun of action)","meaning":"the act of describing; an account","meaningCN":"描述；说明（-ion 构成名词）","example":"The police issued a detailed description of the suspect.","exampleCN":"警方公布了对嫌疑人的详细描述。"},{"word":"descriptive","structure":"descript- + -ive (adjective)","meaning":"giving a picture in words","meaningCN":"描述性的（-ive 构成形容词）","example":"The essay is descriptive rather than argumentative.","exampleCN":"这篇文章是描述性的，而非论证性的。"},{"word":"describable","structure":"describe + -able (can be)","meaning":"able to be described","meaningCN":"可描述的（-able 能……的）","example":"The sensation is barely describable.","exampleCN":"那种感觉几乎无法描述。"},{"word":"indescribable","structure":"in- (not) + describable","meaning":"too extreme to be described","meaningCN":"难以描述的（in- 不 + describable 可描述的）","example":"There was an indescribable relief in the room.","exampleCN":"房间里有一种难以言表的宽慰。"},{"word":"scribe","structure":"Latin scriba (writer)","meaning":"a person who writes or copies documents","meaningCN":"抄写员；书记（直接来自 scriba 写者）","example":"A scribe copied the manuscript by hand.","exampleCN":"一位抄写员用手抄写了这份手稿。"},{"word":"script","structure":"Latin scriptum (something written)","meaning":"written text; a written plan","meaningCN":"文本；脚本（来自 scriptum 写下的东西）","example":"The actor learned the script by heart.","exampleCN":"演员把剧本背了下来。"},{"word":"manuscript","structure":"manu- (hand) + script (written)","meaning":"a document written by hand","meaningCN":"手稿（manu 手 + script 写成的）","example":"The library holds a medieval manuscript.","exampleCN":"这家图书馆藏有一份中世纪手稿。"},{"word":"prescribe","structure":"pre- (before) + scribere (to write)","meaning":"to set down a rule or treatment in advance","meaningCN":"规定；开处方（pre- 在前 + scribere 写）","example":"The doctor prescribed a course of antibiotics.","exampleCN":"医生开了一个疗程的抗生素。"}],"latinEntries":[{"word":"scribere","structure":"scribere (verb)","meaning":"to write","meaningCN":"写"},{"word":"describere","structure":"de- + scribere","meaning":"to write down, copy, sketch","meaningCN":"写下；摹写；勾画"},{"word":"scriptum","structure":"script- + -um (thing)","meaning":"something written","meaningCN":"写下的东西；文本"}]}},{"word":"design","ipa_uk":"/dɪˈzaɪn/","ipa_us":"/dɪˈzaɪn/","definition_zh":"设计；构思；图案；布局；意图；谋划","definition_en":"to plan and shape something for a purpose, or the plan, pattern, or intention that results","core_image":"先用手指在空中勾出一个方框，再落笔画下第一根线——先在心里标记，再把它做出来","scene":"She designs the layout of the magazine.","sceneCN":"这里 design 是「设计、构思版面」（第 3 个义项：为某个用途规划并勾出样子）。句意：她设计这本杂志的版面。画面中先用手指勾框、再落笔，就是把脑中的安排变成可见结构。","pos":[{"tag":"vt.","zh":"设计；构思；绘制；谋划"},{"tag":"vi.","zh":"从事设计；做设计工作"},{"tag":"n.","zh":"设计；图案；布局；意图；计划"}],"collocations":[{"phrase":"be designed to do","zh":"旨在做……；为……而设计"},{"phrase":"by design","zh":"故意地；有意为之"},{"phrase":"design a system","zh":"设计一个系统"},{"phrase":"industrial design","zh":"工业设计"},{"phrase":"a floral design","zh":"花卉图案"}],"forms":[{"label":"三单","form":"designs"},{"label":"过去式","form":"designed"},{"label":"过去分词","form":"designed"},{"label":"现在分词","form":"designing"}],"derivatives":[{"word":"designer","pos":"n.","zh":"设计师"},{"word":"designing","pos":"adj./n.","zh":"工于心计的；设计（工作）"},{"word":"designedly","pos":"adv.","zh":"故意地；有目的地"},{"word":"redesign","pos":"v./n.","zh":"重新设计"},{"word":"designee","pos":"n.","zh":"被指定者；受委托人"}],"senses":[{"no":"01","title":"Shape in the mind: form an idea of what to make","titleCN":"心中成形：先想清楚要做什么样","definition":"to form a plan or idea in the mind for something that is to be made or done","definitionCN":"在头脑中为将要制作或完成的事物形成计划或想法","example":"The course is designed for students with no previous experience.","exampleCN":"这门课程是为没有相关经验的学生设计的。","why":"The verb's first English record, late 14c., is 'to make, shape'. The shaping begins in the mind: before the hand moves, an idea is marked out as the thing to be made.","whyCN":"这个动词最早的英语记录（14 世纪后期）是“制作、塑形”。塑形从心里开始：手还没动，一个想法就先被标成“要做成的东西”。"},{"no":"02","title":"Plan a scheme: lay out steps to an end","titleCN":"计划：把通往目标的步骤排出来","definition":"to plan or outline a scheme, especially one with several stages","definitionCN":"规划或勾勒一项方案，尤指包含若干阶段的方案","example":"They designed a three-stage process for testing the vaccine.","exampleCN":"他们设计了一个三阶段的疫苗测试流程。","why":"From the 1540s design meant 'to plan or outline, form a scheme'. A shape in space becomes a shape in time: the outline is now a sequence of steps.","whyCN":"从 16 世纪 40 年代起，design 意为“规划、勾勒、制定方案”。空间里的形状变成了时间里的形状：轮廓现在是一串步骤。"},{"no":"03","title":"Draw the plan: put the outline on paper","titleCN":"画出图纸：把轮廓落到纸上","definition":"to draw the outline or figure of something, especially a proposed work","definitionCN":"画出某物的轮廓或图形，尤指拟建的作品","example":"The architect designed a low building with a wide glass front.","exampleCN":"建筑师设计了一座正面是宽大玻璃的低矮建筑。","why":"The transitive 'draw the outline or figure of' appears in the 1630s. The mental mark becomes a visible line, and the plan can be handed to someone else.","whyCN":"“画出轮廓或图形”这一及物义出现在 17 世纪 30 年代。心里的标记变成看得见的线，计划因此可以交给别人去执行。"},{"no":"04","title":"A pattern: the decorative arrangement itself","titleCN":"图案：装饰性的安排本身","definition":"a decorative pattern or arrangement of lines, shapes, or colours","definitionCN":"由线条、形状或颜色构成的装饰性图案或安排","example":"The carpet has a simple geometric design.","exampleCN":"这块地毯有一个简单的几何图案。","why":"The noun is recorded from the 1580s as 'a scheme or plan in the mind'; by the 1640s it also meant the artistic details that make up a work. The plan becomes the visible pattern.","whyCN":"名词在 16 世纪 80 年代记录为“心中的方案或计划”；到 17 世纪 40 年代，它也指构成作品的艺术细节。计划变成了看得见的图案。"},{"no":"05","title":"Layout: how the parts are arranged","titleCN":"布局：各部分如何安放","definition":"the arrangement or organization of parts in a building, page, product, or system","definitionCN":"建筑、页面、产品或系统中各部分的安排与组织方式","example":"The design of the page makes the text easy to scan.","exampleCN":"这个页面的布局让文字很容易扫读。","why":"Design as a noun widened from a picture to a structure. Once you see a plan as lines on paper, you can also see it as the way parts sit together in a finished thing.","whyCN":"作为名词，design 从一幅图扩展到一种结构。一旦你把计划看成纸上的线，你也能把它看成成品中各部分相处的方式。"},{"no":"06","title":"Intention: what the maker meant to do","titleCN":"意图：做的人本来想干什么","definition":"the purpose or intention behind an action or arrangement","definitionCN":"某一行动或安排背后的目的、意图","example":"The delay was not accidental; it was by design.","exampleCN":"这次拖延并非偶然，而是故意的。","why":"From the 1580s the noun meant 'a scheme or plan in the mind', and from 1704 especially 'an intention to act in a particular way'. The outline is now an intention, not a drawing.","whyCN":"从 16 世纪 80 年代起，名词意为“心中的方案或计划”，从 1704 年起尤指“按某种方式行事的意图”。轮廓这时是意图，不是图画。"},{"no":"07","title":"Design in secret: a plot with a purpose","titleCN":"谋划：藏着目的的盘算","definition":"a secret and often harmful plan; to plot something with a particular aim","definitionCN":"秘密的、常带恶意的计划；带特定目的地谋划","example":"He suspected that the two men were designing a way to cheat him.","exampleCN":"他怀疑那两个人正在谋划一个骗他的办法。","why":"Italian disegnare in the 16c. developed 'to contrive, plot, intend'. A plan made in the mind can be hidden there too, so design acquires a dark, secret sense.","whyCN":"意大利语 disegnare 在 16 世纪发展出“策划、图谋、打算”的意思。在心里做出的计划也可以藏在心里，于是 design 多了一层阴暗、秘密的意味。"},{"no":"08","title":"Applied art: design as a profession","titleCN":"应用艺术：作为专业的设计","definition":"the practical application of artistic principles to objects, graphics, or systems","definitionCN":"把艺术原则实际应用到物品、图形或系统上","example":"She studied graphic design before moving into publishing.","exampleCN":"她先学平面设计，后来进入出版业。","why":"The 1660s sense 'plan and execute, fashion with artistic skill' turned into a profession. Design now names the work of joining usefulness to form.","whyCN":"17 世纪 60 年代“规划并执行、以艺术技巧制作”的义项变成了一门职业。design 现在命名的是把“有用”与“形式”接起来的工作。"},{"no":"09","title":"Designed for: built to serve a purpose","titleCN":"专为……而设：为某个用途造出来","definition":"made or intended for a particular purpose or user","definitionCN":"为特定目的或使用者制作或设定的","example":"The app is designed to work offline.","exampleCN":"这个应用是为离线使用而设计的。","why":"A plan always has an end in view. When the end is stated in the sentence — designed to work, designed for children — the noun's 'intention' sense becomes an adjective-like participle.","whyCN":"计划总有它盯住的目的。当目的在句子里说出来——designed to work、designed for children——名词的“意图”义就变成了类似形容词的分词。"},{"no":"10","title":"Old sense: designate or appoint","titleCN":"古义：指定、任命","definition":"in 17c. English, to designate, appoint, or set apart for a role","definitionCN":"在 17 世纪英语中指指定、任命或为某角色预留","example":"The office was designed for the keeper of the royal records.","exampleCN":"这个职位是为皇家档案保管人指定的。","why":"Latin designare meant 'mark out, choose, designate, appoint', and 17c. English still used design for that. The modern 'designate' keeps the old sense alive with a different spelling.","whyCN":"拉丁语 designare 意为“标出、挑选、指定、任命”，17 世纪英语仍用 design 表达这个意思。现代的 designate 用另一种拼写让这个旧义继续活着。"}],"etymology":{"intro":{"en":"Design comes ultimately from Latin designare 'mark out, point out; devise; choose, designate, appoint', from de- 'out' and signare 'to mark', from signum 'a sign'. Italian disegnare in the 16c. split it into 'plot, intend' and 'draw'; French passed both senses to English, which uses design for all of them.","cn":"design 最终来自拉丁语 designare“标出、指出；设计；挑选、指定、任命”，由 de-“出”与 signare“做标记”构成，signare 又来自 signum“记号”。16 世纪意大利语 disegnare 把它分成“图谋、打算”和“绘制”两支；法语把这两支都传给英语，英语用 design 承担全部义项。"},"items":[{"era":"LATIN (before 1C BC)","en":"Designare meant 'mark out, point out; devise; choose, designate, appoint'. It joins de- 'out' to signare 'to mark', so the core act is making a sign that sets something apart.","cn":"designare 意为“标出、指出；设计；挑选、指定、任命”。它把 de-“出”与 signare“做标记”接在一起，核心动作是做一个记号，把某物单独标出来。"},{"era":"ITALIAN (16c.)","en":"Italian disegnare developed two branches: 'to contrive, plot, intend' and 'to draw, paint, embroider'. The same mark could be made in the mind or on a surface.","cn":"意大利语 disegnare 发展出两支：一是“策划、图谋、打算”，二是“绘制、绘画、刺绣”。同一个记号既可以做在心里，也可以做在表面上。"},{"era":"FRENCH (16c.)","en":"French took both Italian senses in different forms, dessein 'purpose, plan' and dessin 'drawing', and passed them on to English.","cn":"法语用不同形式接收了意大利语的两支：dessein“目的、计划”和 dessin“图画”，再把它们传给英语。"},{"era":"LATE 14c-1540s ENGLISH","en":"The verb first appears late 14c. as 'to make, shape'. From the 1540s it means 'to plan or outline, form a scheme'; the 1630s add 'draw the outline of a proposed work'.","cn":"动词最早在 14 世纪后期出现，意为“制作、塑形”。从 16 世纪 40 年代起意为“规划、勾勒、制定方案”；17 世纪 30 年代增添“画出拟建作品的轮廓”。"},{"era":"1580s-1700s ENGLISH","en":"The noun appears in the 1580s as 'a scheme or plan in the mind'. Art adds 'a drawing, an outline' in the 1630s and decorative detail in the 1640s; 1704 records the 'intention, often harmful' sense.","cn":"名词在 16 世纪 80 年代出现，意为“心中的方案或计划”。艺术义在 17 世纪 30 年代增添“图画、轮廓”，17 世纪 40 年代增添装饰细节；1704 年记录“意图、常指恶意”的义项。"},{"era":"MODERN ENGLISH","en":"The 1660s sense 'plan and execute with artistic skill' grew into the modern profession of design. Industrial and graphic design keep both halves: the plan and the made form.","cn":"17 世纪 60 年代“规划并执行、以艺术技巧制作”的义项长成了现代的设计职业。工业设计与平面设计同时保留两半：计划与做成的形式。"}]},"similar":{"note":{"en":"The first group is chosen for spelling and sound, the second for meaning, so that form and sense stay separate.","cn":"第一组按拼写和读音挑选，第二组按词义挑选，这样词形和词义不会混在一起。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"designate","ipa":"/ˈdezɪɡneɪt/","tag":"same Latin base","definition":"to officially choose or name someone for a role. It is the old 'appoint' sense of design kept as a separate word.","definitionCN":"指定；任命。它是 design 古老“任命”义独立出来的一个词。"},{"word":"resign","ipa":"/rɪˈzaɪn/","tag":"re- + sign","definition":"to give up a job or position formally. It shares -sign but has re- 'back' and a different meaning.","definitionCN":"辞职。同样以 -sign 结尾，但前缀是 re-“回”，意思不同。"},{"word":"assign","ipa":"/əˈsaɪn/","tag":"as- + sign","definition":"to give a task or share to someone. It is close in sound to design and also comes from signare.","definitionCN":"分配；指派。读音接近 design，同样来自 signare。"}]},{"heading":"NEAR MEANING","entries":[{"word":"plan","ipa":"/plæn/","tag":"steps to an end","definition":"an organized set of steps for achieving something. It matches design in the 'scheme' sense but says nothing about form.","definitionCN":"计划；方案。对应 design 表“方案”的义项，但不涉及形状。"},{"word":"scheme","ipa":"/skiːm/","tag":"formal or secret plan","definition":"a large or secret plan. It matches design in both the planning and the plotting senses.","definitionCN":"方案；阴谋。同时对应 design 的“规划”义和“图谋”义。"},{"word":"blueprint","ipa":"/ˈbluːprɪnt/","tag":"technical drawing","definition":"a detailed technical drawing or a plan for the future. It matches design in the drawn-plan sense.","definitionCN":"蓝图；详细规划。对应 design 表“图纸、规划”的义项。"},{"word":"pattern","ipa":"/ˈpætən/","tag":"repeated arrangement","definition":"a repeated decorative arrangement of shapes or lines. It matches design as a visible motif.","definitionCN":"图案；花样。对应 design 表“可见图案”的义项。"},{"word":"intention","ipa":"/ɪnˈtenʃn/","tag":"what one means to do","definition":"the aim or purpose behind an action. It matches design in the 'by design' sense.","definitionCN":"意图；目的。对应 design 在 by design 中表“故意”的义项。"}]}]},"mnemonics":{"normalIntro":{"en":"These links are real: the Latin signum 'sign' family behind signal and signature, the de- 'out' in designare, and the double branch 'plan' versus 'draw' that Italian handed to English.","cn":"这些联想都是真实的：signal、signature 背后拉丁语 signum“记号”词族，designare 里的 de-“出”，以及意大利语传给英语的“计划”与“绘制”两支。"},"normal":[{"en":"design = de- 'out' + signum 'sign': to design is to mark a sign out, so others can see what you mean to make.","cn":"design = de-“出”+ signum“记号”：design 就是把一个记号标出来，让别人看见你打算做什么。"},{"en":"sign, signal, signature and design all share signum 'mark'. A design is the mark that tells you what the thing will be.","cn":"sign、signal、signature、design 都共用 signum“记号”。design 就是告诉你“这东西将会是什么样”的那个记号。"},{"en":"designate is design's old 'appoint' sense: to designate is to mark a person out for a role.","cn":"designate 就是 design 古老的“任命”义：指定一个人，就是把他标出来担任某个角色。"},{"en":"by design means the mark was made on purpose; the opposite phrase is by accident.","cn":"by design 指那个记号是被有意打上的；它的反义说法是 by accident。"},{"en":"A floral design on a plate is the plan made visible: the same mark, now repeated as decoration.","cn":"盘子上的花卉 design 是计划变得可见：同一个记号，如今被重复成装饰。"}],"abstract":[{"en":"Design is a mark made in the mind first, then in the material: the sign is the bridge between intention and object.","cn":"design 是先在心里、再在材料上打下的记号：这个记号是意图与物品之间的桥。"},{"en":"The word holds two directions at once: looking forward it is a plan, looking down it is a drawing.","cn":"这个词同时握住两个方向：朝前看是计划，朝下看是图画。"},{"en":"To design is to answer two questions with one mark: what will this be, and what is it for?","cn":"design 是用一个记号回答两个问题：这东西会是什么样？它又是为了什么？"}]},"examples":[{"en":"The bridge was designed by a local engineer.","cn":"这座桥是由一位本地工程师设计的。"},{"en":"The wallpaper has a repeating leaf design.","cn":"墙纸上有重复的叶子图案。"},{"en":"The error was not luck; it was by design.","cn":"这个错误不是运气使然，而是故意的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“地sign”——de（出）+ sign（记号），把心里的记号标出来，就是设计、图案、意图","word":"design"},"root":"源自拉丁语 designare“标出、指定、设计”，由 de-“出”+ signare“做标记”构成，signare 来自 signum“记号”；经意大利语与法语两支义项于 14 世纪后期进入英语。","sensesIntro":{"en":"Ten senses of design, all built on one act: making a sign that sets a shape apart. The sign can live in the mind, on paper, in a pattern, in an arrangement, or in an intention.","cn":"design 的十个义项都建立在同一个动作上：打一个记号，把某个形状单独标出来。这个记号可以活在心里、纸上、图案里、布局里，或一个意图里。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sign marked out in the mind before it is marked on the material.","cn":"核心意象：先在心中标出一个记号，再把它打到材料上。"},"chain":["MARK IT OUT","FORM THE IDEA","DRAW THE PLAN","ARRANGE THE PARTS","MAKE IT WORK","READ THE INTENT"],"branches":[{"senses":"S01 · S02","en":"THE MIND MARKS FIRST: an idea is shaped, then turned into a scheme with steps.","cn":"心里先做记号：先塑成一个想法，再把它变成有步骤的方案。"},{"senses":"S03 · S05","en":"THE VISIBLE PLAN: the outline is drawn on paper, and the parts are arranged in a layout.","cn":"看得见的计划：轮廓画到纸上，各部分在布局里被安放。"},{"senses":"S04 · S08","en":"FORM AS ART: a decorative pattern, and the profession that joins use to shape.","cn":"形式作为艺术：装饰图案，以及把用途与形状接起来的职业。"},{"senses":"S06 · S07 · S09","en":"THE PURPOSE INSIDE: intention, a secret plot, and something built for a stated end.","cn":"内里的目的：意图、秘密谋划，以及为明确目的造出的东西。"},{"senses":"S10","en":"THE OLD APPOINTMENT: design once meant to designate, and designate still carries that mark.","cn":"古老的任命义：design 曾表示“指定”，designate 仍带着这个记号。"}]},"affixes":{"intro":{"en":"Design is a Latin loan built on signum 'sign': designation, designer and redesign grow from it, while sign, signal, signature and signify share the same marking base.","cn":"design 是建立在 signum“记号”上的拉丁借词：designation、designer、redesign 由它长出，而 sign、signal、signature、signify 共用同一个“做标记”的词基。"},"latinIntro":{"en":"Latin signum 'mark, sign' gives signare 'to mark', then designare 'mark out' and designatio 'a marking out'. The family is about setting a mark on a thing so that it can be identified or chosen.","cn":"拉丁语 signum“记号、符号”生出 signare“做标记”，再生成 designare“标出”和 designatio“标出、指定”。这个词族讲的是在事物上留下记号，好把它认出或挑选出来。"},"items":[{"word":"design","structure":"de- (out) + signare (to mark)","meaning":"to mark out a plan or form","meaningCN":"设计；构思（de- 出 + signare 标记）","example":"They designed a chair that folds flat.","exampleCN":"他们设计了一把可以折平的椅子。"},{"word":"designate","structure":"de- + signare + -ate (verb)","meaning":"to mark out and name for a role","meaningCN":"指定；任命（-ate 构成动词）","example":"The area was designated a nature reserve.","exampleCN":"这个区域被指定为自然保护区。"},{"word":"designation","structure":"designat- + -ion (noun of action)","meaning":"the act of naming or appointing","meaningCN":"指定；名称（-ion 构成名词）","example":"The official designation of the post is 'registrar'.","exampleCN":"这个职位的正式名称是 registrar。"},{"word":"designer","structure":"design + -er (agent noun)","meaning":"one who designs","meaningCN":"设计师（-er 表人）","example":"The designer chose a muted colour palette.","exampleCN":"设计师选了一组柔和的配色。"},{"word":"redesign","structure":"re- (again) + design","meaning":"to design something again","meaningCN":"重新设计（re- 再 + design）","example":"The team redesigned the menu for clarity.","exampleCN":"团队为了提高清晰度重新设计了菜单。"},{"word":"sign","structure":"Latin signum (mark, sign)","meaning":"a mark or gesture that means something","meaningCN":"记号；标志（直接来自 signum）","example":"A red sign marked the exit.","exampleCN":"一块红色标志标出了出口。"},{"word":"signal","structure":"signum + -al (adjective/noun)","meaning":"a sign that conveys information","meaningCN":"信号（-al 构成形容词/名词）","example":"The radio signal was weak in the valley.","exampleCN":"山谷里无线电信号很弱。"},{"word":"signature","structure":"signat- + -ure (noun)","meaning":"a person's written name as a mark","meaningCN":"签名（-ure 构成名词）","example":"The contract needs your signature.","exampleCN":"这份合同需要你的签名。"},{"word":"signify","structure":"sign- (mark) + -ify (to make)","meaning":"to be a sign of; to mean","meaningCN":"表示；意味着（-ify 使……）","example":"A nod can signify agreement.","exampleCN":"点头可以表示同意。"}],"latinEntries":[{"word":"signum","structure":"signum (noun)","meaning":"a mark, sign, token","meaningCN":"记号；符号；标志"},{"word":"signare","structure":"signum + -are (verb)","meaning":"to mark, seal, sign","meaningCN":"做标记；盖章；签名"},{"word":"designare","structure":"de- + signare","meaning":"to mark out, designate, appoint","meaningCN":"标出；指定；任命"}]}},{"word":"despite","ipa_uk":"/dɪˈspaɪt/","ipa_us":"/dɪˈspaɪt/","definition_zh":"尽管；虽然；不顾；蔑视（古义）；侮辱（古义）","definition_en":"used to say that something happens even though another thing could prevent it; without being stopped by","core_image":"一个人顶着一堵写满阻力的墙继续往前走——墙还在，脚步没有停","scene":"A hiker keeps climbing although the storm warning is still up: Despite the wind, she reached the ridge before noon.","sceneCN":"这里 despite 是「尽管、不顾」（第 01 个义项：介词，表示某事不构成阻碍）；句意：尽管风很大，她还是在中午前登上了山脊。画面里可辨识的物件：山脊、被风吹斜的登山杖、尚未撤下的风暴警报旗。","pos":[{"tag":"prep.","zh":"尽管；虽然；不顾"},{"tag":"n.","zh":"（古）蔑视；侮辱；怨恨"},{"tag":"vt.","zh":"（罕）蔑视；轻视"}],"collocations":[{"phrase":"despite the fact that","zh":"尽管……（后接完整从句）"},{"phrase":"despite all","zh":"尽管有这一切"},{"phrase":"despite oneself","zh":"不由自主地；违背自己意愿地"},{"phrase":"despite appearances","zh":"尽管表面看来如此"},{"phrase":"in despite of","zh":"（古）不顾；无视（= in spite of）"}],"forms":[{"label":"介词形态","form":"despite（无屈折变化）"},{"label":"名词复数（古义）","form":"despites"},{"label":"动词过去式（罕用）","form":"despited"}],"derivatives":[{"word":"spite","pos":"n.","zh":"恶意；怨恨（despite 的缩略形式）"},{"word":"spiteful","pos":"adj.","zh":"恶意的；爱记仇的"},{"word":"despiteful","pos":"adj.","zh":"（古）满怀蔑视的；恶毒的"},{"word":"despicable","pos":"adj.","zh":"可鄙的；卑劣的（同出拉丁语 despicere）"},{"word":"in spite of","pos":"phrase","zh":"尽管；不顾（与 despite 同源同义）"}],"senses":[{"no":"01","title":"In spite of: the obstacle that does not stop the act","titleCN":"尽管：挡不住动作的那道障碍","definition":"used before a noun to say that something is true or happens even though another thing might prevent it","definitionCN":"用在名词前，表示某事虽然可能受阻却仍然成立或发生","example":"Despite the heavy rain, the match continued until dark.","exampleCN":"尽管大雨倾盆，比赛仍一直进行到天黑。","why":"The prepositional sense (early 15c.) is short for in despite of, literally 'in contempt of'. The obstacle is not removed; it is held in contempt, and contempt is what removes its power to stop you.","whyCN":"介词义（15 世纪早期）是 in despite of 的省略，字面为“以蔑视对待”。障碍并没有被搬走，而是被轻视；正是这份轻视让障碍失去了拦住你的力量。"},{"no":"02","title":"Despite the fact that: the noun slot opens into a clause","titleCN":"尽管事实是：名词位置被从句撑开","definition":"a concessive connector that introduces a full clause, usually in the frame 'despite the fact that'","definitionCN":"引导完整从句的让步连接语，通常以 despite the fact that 的框架出现","example":"Despite the fact that he had studied for months, he failed the exam.","exampleCN":"尽管他已苦学数月，考试还是没通过。","why":"The preposition normally takes a noun or an -ing form and cannot take a clause: *despite he studied is impossible. Speakers bridge that gap with the fact that, turning a fact into the noun the preposition needs.","whyCN":"这个介词通常只接名词或 -ing 形式，不能直接接从句，*despite he studied 不成立。说话人用 the fact that 把一件事包装成名词，正是为了填上介词要的那个位置。"},{"no":"03","title":"In despite of: defiance spoken out loud","titleCN":"In despite of：把蔑视说出口的公然违抗","definition":"in open defiance or contempt of; a literary and archaic phrase","definitionCN":"公然违抗、蔑视……；现为书面古语","example":"In despite of the ban, they published the book anyway.","exampleCN":"他们无视禁令，仍然出版了这本书。","why":"The phrase is a loan-translation of Anglo-French en despit de, 'in contempt of' (c. 1300). At that time despite was still the noun 'scorn', so the phrase said plainly: I hold this in scorn and act anyway.","whyCN":"这个短语是盎格鲁-法语 en despit de（约 1300 年）的仿译，意思是“以蔑视为之”。当时 despite 还是名词“蔑视”，所以短语说得很直白：我瞧不起它，但我照样做。"},{"no":"04","title":"Scorn: the look directed downward","titleCN":"蔑视：从上往下投去的目光","definition":"contempt or scorn for someone or something regarded as worthless (archaic noun)","definitionCN":"对被视为无价值的人或事的轻蔑、鄙视（古名词义）","example":"He spoke of their warning with open despite.","exampleCN":"他谈起他们的警告时毫不掩饰地轻蔑。","why":"Latin despectus is the past participle of despicere, 'to look down on', from de 'down' + specere 'to look'. Scorn is literally a downward glance: the scorner stands above what he judges.","whyCN":"拉丁语 despectus 是 despicere 的过去分词，意为“向下看”，由 de“向下”+ specere“看”构成。蔑视字面上就是往下瞥一眼：轻视者把自己站到了他所评判之物的上方。"},{"no":"05","title":"A contemptuous challenge: the insult offered to a face","titleCN":"挑衅性侮辱：当面递出的羞辱","definition":"an act intended to insult or humiliate someone; a defiant challenge (c. 1300)","definitionCN":"存心侮辱或羞辱他人的举动；挑衅性的挑战（约 1300 年）","example":"The knight answered the despite with a drawn sword.","exampleCN":"骑士拔剑回应了这份当面羞辱。","why":"The earliest English noun (c. 1300) meant 'contemptuous challenge, defiance; an act designed to insult'. A feeling kept private stays scorn; shown to someone's face it becomes a challenge, and the word names the act.","whyCN":"英语最早的名词义（约 1300 年）是“蔑视性的挑战、挑衅；存心羞辱他人的行为”。藏在心里的情绪只是蔑视；当面做出来就成了挑战，词也就用来指这个举动。"},{"no":"06","title":"Malice: the scorn that keeps score","titleCN":"怨恨：记在账上的蔑视","definition":"ill will or malice toward another person (archaic noun)","definitionCN":"对他人的恶意、怨恨（古名词义）","example":"She refused out of pure despite, not because she disagreed.","exampleCN":"她拒绝纯粹是出于怨恨，并不是因为她不同意。","why":"Middle English despit also carried 'malice'. Around 1300 the shortened form spite split off to hold the everyday emotion, while despite kept the formal and prepositional work; the old malice sense survives in in despite of.","whyCN":"中古英语 despit 也含“恶意”。约 1300 年，缩略形式 spite 分出去承担日常的“怨恨”情绪，despite 则转向正式用法和介词用法；古老的“恶意”义仍残留在 in despite of 里。"},{"no":"07","title":"Despite oneself: the will that overrides itself","titleCN":"不由自主：意志违反自身","definition":"used to say that someone does something although they did not intend or want to","definitionCN":"表示某人做了某事，尽管并非本意或并不愿意","example":"She smiled despite herself, though she was still angry.","exampleCN":"她不由自主地笑了，尽管还在生气。","why":"The same 'in contempt of' structure is turned inward: the self becomes the obstacle held in contempt. The body acts, the will objects, and the act goes on despite the will.","whyCN":"同一个“以蔑视对待”的结构被转向内部：自己成了那个被轻视的障碍。身体在动，意志在反对，动作却仍然 despite 意志地进行下去。"},{"no":"08","title":"Despite appearances: when the visible ground is overruled","titleCN":"尽管表面如此：可见证据被推翻","definition":"used before evidence words such as appearances or everything, to say the hidden truth is different","definitionCN":"用在 appearances、everything 等表示证据的词前，表示隐藏的真相并不相同","example":"Despite appearances, the old bridge is perfectly safe.","exampleCN":"尽管看上去破旧，这座老桥其实完全安全。","why":"Appearances are the most obvious ground for a judgment, and the preposition was built to override grounds. To go despite appearances is to let a hidden fact outrank the visible one, exactly as the obstacle is outranked in sense 01.","whyCN":"表象是判断最现成的依据，而这个词的介词义本来就是用来压过某种依据的。despite appearances 就是让隐藏的事实压过看得见的事实，与第 01 义里障碍被压过的机制完全一致。"},{"no":"09","title":"To scorn: the rare verb behind the preposition","titleCN":"蔑视：介词背后那个罕用动词","definition":"to treat with contempt; to scorn (rare, mostly archaic)","definitionCN":"以轻蔑的态度对待；鄙视（罕用，多为古语）","example":"The old critics despited the young painter's work.","exampleCN":"那些老批评家蔑视这位年轻画家的作品。","why":"The verb was formed from the noun while the noun still meant 'scorn'. As the prepositional 'notwithstanding' took over the word in the 15c., the verb faded, leaving a trace only in older writing.","whyCN":"这个动词是在名词仍表“蔑视”时由名词转成的。15 世纪介词义“尽管”接管了这个词之后，动词逐渐退场，只在较早的文本里留下痕迹。"}],"etymology":{"intro":{"en":"Despite comes from Latin despicere 'to look down on', through Old French despit. Its modern prepositional sense grew out of the phrase in despite of, where the obstacle is held in contempt rather than removed.","cn":"despite 来自拉丁语 despicere“向下看、蔑视”，经古法语 despit 进入英语。现代介词义从短语 in despite of 长出来：障碍不是被搬走，而是被蔑视。"},"items":[{"era":"LATIN (1C BC)","en":"Despicere meant 'to look down on, scorn', from de 'down' + specere 'to look at'; its past participle despectus is the source of the noun. The deeper PIE root *spek- 'to observe' is a reconstruction with no written record, so it is labelled reconstructed, not attested.","cn":"despicere 意为“向下看、蔑视”，由 de“向下”+ specere“看”构成；其过去分词 despectus 是名词义的来源。更深的原始印欧语词根 *spek-“观察”是重构形式，没有书面记录，因此只能标为“重构”，不能当作确证。"},{"era":"OLD FRENCH (12c.)","en":"Old French despit (Modern French dépit) meant 'contempt, spite; insult, humiliation'. It carried both the feeling and the act into English.","cn":"古法语 despit（现代法语 dépit）意为“蔑视、怨恨；侮辱、羞辱”，把情绪和举动两层意思一起带进了英语。"},{"era":"c. 1300 ENGLISH","en":"The first English records give 'contemptuous challenge, defiance; an act designed to insult or humiliate someone'; by mid-14c. also plain 'scorn, contempt'. The short form spite splits off around the same time.","cn":"英语最早的记录是“蔑视性的挑战、挑衅；存心侮辱或羞辱他人的行为”；到 14 世纪中期也直接指“蔑视、轻蔑”。缩略形式 spite 大约同时分出。"},{"era":"EARLY 15c ENGLISH","en":"'Notwithstanding' appears early 15c. as a shortening of in despite of (c. 1300), itself a loan-translation of Anglo-French en despit de 'in contempt of'. A 16c. spelling reform nearly fixed the form as despight.","cn":"“尽管”义在 15 世纪早期出现，是 in despite of（约 1300 年）的省略，而该短语又是盎格鲁-法语 en despit de“以蔑视为之”的仿译。16 世纪的拼写改革一度几乎把它定形为 despight。"},{"era":"MODERN ENGLISH","en":"The preposition now does most of the work; the noun survives in fixed phrases such as in despite of, and the verb is rare. Spite became the everyday word for the emotion, which is why despite no longer means 'malice' to most speakers.","cn":"现代英语里介词义承担了主要工作；名词义只活在 in despite of 这类固定短语里，动词义罕用。spite 成了表达这种情绪的日常词，所以多数人已不觉得 despite 还有“恶意”的意思。"}]},"similar":{"note":{"en":"The first group is chosen for spelling and sound, the second for meaning, so that form and sense stay separate.","cn":"第一组按拼写和读音挑选，第二组按词义挑选，这样词形和词义不会混在一起。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"spite","ipa":"/spaɪt/","tag":"shortened twin","definition":"petty ill will; a desire to hurt or annoy. It is despite minus the first syllable, and has kept the emotional sense.","definitionCN":"恶意；怨恨。它是 despite 去掉第一个音节后的形式，保留了情绪义。"},{"word":"despise","ipa":"/dɪˈspaɪz/","tag":"same Latin root, verb","definition":"to feel contempt for. It shares despicere with despite but is a verb and ends in /z/, not /t/.","definitionCN":"鄙视；看不起。与 despite 同出 despicere，但它是动词，结尾读 /z/ 而不是 /t/。"},{"word":"respite","ipa":"/ˈrespɪt/","tag":"near spelling","definition":"a short period of rest or relief. It looks like despite but is stressed on the first syllable and is a noun.","definitionCN":"暂缓；喘息。拼写像 despite，但重音在第一音节，且是名词。"},{"word":"despight","ipa":"/dɪˈspaɪt/","tag":"16c variant","definition":"an archaic spelling of despite, produced by a 16th-century spelling reform. Same pronunciation, different letters.","definitionCN":"despite 的古拼写，由 16 世纪拼写改革造成。读音相同，字母不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"notwithstanding","ipa":"/ˌnɒtwɪθˈstændɪŋ/","tag":"formal","definition":"in spite of; despite. It is the most formal of the concessive words and can follow the noun it governs.","definitionCN":"尽管；虽然。是这类让步词里最正式的，还可以放在它所支配的名词之后。"},{"word":"although","ipa":"/ɔːlˈðəʊ/","tag":"clause only","definition":"despite the fact that. Unlike despite, it must be followed by a full clause, not a noun.","definitionCN":"尽管；虽然。与 despite 不同，它后面必须接完整从句，不能只接名词。"},{"word":"in spite of","ipa":"/ɪn ˈspaɪt əv/","tag":"same meaning, two words","definition":"despite. It is the fuller phrase from which despite was clipped, and it takes a noun or -ing form.","definitionCN":"尽管。它是 despite 由之省略而来的完整短语，后接名词或 -ing 形式。"},{"word":"regardless of","ipa":"/rɪˈɡɑːdləs əv/","tag":"paying no attention","definition":"without being affected by; paying no attention to. It stresses indifference rather than defiance.","definitionCN":"不管；不顾。强调不在意，而不是蔑视式的违抗。"},{"word":"even though","ipa":"/ˈiːvn ðəʊ/","tag":"strong concession","definition":"despite the fact that; used when the contrast is surprising or strong. It also needs a clause.","definitionCN":"即使；尽管。用于对比出人意料或强烈时，同样要接从句。"}]}]},"mnemonics":{"normalIntro":{"en":"These links are real: Latin despicere 'look down', the phrase in despite of, and the 14c. split that gave English spite.","cn":"这些联想都是真实的：拉丁语 despicere“向下看”、短语 in despite of，以及 14 世纪分出 spite 的那次裂变。"},"normal":[{"en":"de- 'down' + spic- 'look': to scorn is to look down on something. The downward glance is the picture inside the word.","cn":"de-“向下”+ spic-“看”：蔑视就是从上往下看某物。这一瞥向下，就是词里藏着的画面。"},{"en":"Despite and spite are one word twice: spite is the clipped form, so 'in spite of' and 'despite' mean the same thing today.","cn":"despite 和 spite 是同一个词的两截：spite 是省略形式，所以今天的 in spite of 和 despite 意思相同。"},{"en":"The preposition takes a noun or -ing, never a clause: despite the rain / despite raining, but not *despite it rained.","cn":"这个介词接名词或 -ing，不接从句：despite the rain / despite raining，但不能说 *despite it rained。"},{"en":"Where you could say 'even though', you can usually say 'despite the fact that'; the fact that is the bridge from clause to noun.","cn":"能说 even though 的地方，通常也能说 despite the fact that；the fact that 就是从从句通向名词的那座桥。"},{"en":"despite oneself is the preposition turned inward: the self is the obstacle, and the action still goes through.","cn":"despite oneself 是把这个介词转向内部：自己成了障碍，动作却照样通过。"}],"abstract":[{"en":"The word begins as a look downward and ends as a step forward: contempt aimed at an obstacle becomes motion that ignores it.","cn":"这个词从向下的目光开始，以向前的脚步结束：投向障碍的蔑视，变成了无视它的前行。"},{"en":"Nothing is removed. The wall stays; only its authority is withdrawn. That is why despite never means 'because of' or 'without'.","cn":"什么都没有被搬走。墙还在，被撤掉的只是它的权威。所以 despite 从来不表示“因为”，也不表示“没有”。"},{"en":"So scorn, insult, malice, defiance, and notwithstanding are one gesture seen from five distances: from the eye, to the face, to the will, to the sentence.","cn":"所以蔑视、侮辱、恶意、违抗、尽管，是同一个姿态在五种距离上的样子：从眼睛，到面孔，到意志，再到句子。"}]},"examples":[{"en":"Despite the delay, most passengers stayed calm and waited for news.","cn":"尽管航班延误，多数乘客仍保持冷静，等待消息。"},{"en":"Despite all her efforts, the garden refused to bloom that year.","cn":"尽管她费尽心力，那座花园那年还是没有开花。"},{"en":"He laughed despite himself, though he had promised to stay serious.","cn":"他不由自主地笑了，尽管先前答应过要保持严肃。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“抵死拜他”：抵死也不拜他——就是 despite 的“不顾、尽管”","word":"despite"},"root":"源自拉丁语 despicere“向下看、蔑视”（de 向下 + specere 看），经古法语 despit 于约 1300 年进入英语；介词义“尽管”来自短语 in despite of。","sensesIntro":{"en":"Nine senses of despite, from a downward glance to the preposition that lets an act continue. The scorn never disappears; it moves into the grammar, where what is held in contempt loses the power to stop you.","cn":"despite 的九个义项，从向下的目光一直到让动作继续的介词。蔑视始终没有消失，它钻进了语法：被瞧不起的东西，就失去了拦住你的力量。"},"semanticMap":{"core":{"en":"CORE IMAGE: a glance downward at an obstacle, then a step that passes it.","cn":"核心意象：先向下瞥一眼障碍，再迈一步越过去。"},"chain":["LOOK DOWN","HOLD IN SCORN","INSULT TO THE FACE","DEFY IN DESPITE OF","OVERRIDE THE GROUND","CONCEDE AND CONTINUE"],"branches":[{"senses":"S04 · S05","en":"THE DOWNWARD LOOK: scorn as a private feeling, and the insulting act that shows it to a face.","cn":"向下的目光：作为私下情绪的蔑视，与当面展示它的侮辱举动。"},{"senses":"S06","en":"THE KEEPING OF SCORE: malice, the scorn that outlives the moment and turns into a grudge.","cn":"记账：恶意，是活过当下、变成怨恨的那种蔑视。"},{"senses":"S03","en":"THE PHRASE OF DEFIANCE: in despite of, a loan-translation that says 'in contempt of' and acts anyway.","cn":"违抗的短语：in despite of，一句仿译，意思是“以蔑视为之”，却照样去做。"},{"senses":"S01 · S02","en":"THE CONCESSIVE TOOL: the preposition takes a noun, and the fact that lets it take a clause.","cn":"让步工具：介词接名词，而 the fact that 让它能接从句。"},{"senses":"S07 · S08 · S09","en":"THE SELF AND THE EVIDENCE: a will overridden, appearances overruled, and the rare verb that still scorns.","cn":"自我与证据：被压过的意志、被推翻的表象，以及仍在蔑视的罕用动词。"}]},"affixes":{"intro":{"en":"Despite belongs to the Latin spec- family 'to look': de- + spic-, with relatives in spite, despise, despicable, aspect, inspect and retrospect.","cn":"despite 属于拉丁语 spec-“看”这个词族：de- + spic-，亲属包括 spite、despise、despicable、aspect、inspect、retrospect。"},"latinIntro":{"en":"Latin specere 'to look at' (past participle spectus) builds despicere 'look down on', and the same root spreads through aspect, inspect, respect, suspect and perspective.","cn":"拉丁语 specere“看”（过去分词 spectus）构成 despicere“向下看”，同一词根还散布在 aspect、inspect、respect、suspect、perspective 里。"},"items":[{"word":"despite","structure":"de- (down) + spic- (look) + -e","meaning":"a looking down on; hence notwithstanding","meaningCN":"向下看、蔑视；由此引申为“尽管”","example":"Despite the noise, she finished the letter.","exampleCN":"尽管很吵，她还是写完了那封信。"},{"word":"despiteful","structure":"despite + -ful (full of)","meaning":"full of scorn; malicious (archaic)","meaningCN":"满怀蔑视的；恶毒的（古语）","example":"The despiteful remark ended the conversation.","exampleCN":"那句充满蔑视的话结束了谈话。"},{"word":"spite","structure":"aphetic short form of despite","meaning":"petty ill will","meaningCN":"恶意；怨恨（despite 的省略形式）","example":"He left the light on out of spite.","exampleCN":"他出于赌气把灯留着没关。"},{"word":"spiteful","structure":"spite + -ful","meaning":"showing petty ill will","meaningCN":"恶意的；爱记仇的","example":"She made a spiteful remark about his accent.","exampleCN":"她恶意地拿他的口音说了一句。"},{"word":"despise","structure":"de- (down) + spic- (look), via Old French despire","meaning":"to look down on; to feel contempt for","meaningCN":"鄙视；看不起（向下看）","example":"He despised the way they treated the interns.","exampleCN":"他鄙视他们对待实习生的方式。"},{"word":"despicable","structure":"de- + spic- + -able (worthy of)","meaning":"worthy of being looked down on","meaningCN":"可鄙的；卑劣的（值得被看低的）","example":"It was a despicable act of betrayal.","exampleCN":"那是一次卑劣的背叛行为。"},{"word":"respite","structure":"re- (back) + spect- (look) + -e","meaning":"a looking back; hence a pause, relief","meaningCN":"回头看；由此引申为暂缓、喘息","example":"The rain gave the firefighters a brief respite.","exampleCN":"那场雨让消防员得到短暂的喘息。"},{"word":"aspect","structure":"ad- (to) + spect- (look)","meaning":"the look a thing presents; one side of it","meaningCN":"外观；方面（事物呈现给你的那一面）","example":"We considered every aspect of the plan.","exampleCN":"我们考虑了这个计划的每个方面。"},{"word":"inspect","structure":"in- (into) + spect- (look)","meaning":"to look into closely; to examine","meaningCN":"检查；视察（往里看）","example":"Officials inspected the factory last week.","exampleCN":"官员上周视察了这家工厂。"},{"word":"retrospect","structure":"retro- (backward) + spect- (look)","meaning":"a looking back at past events","meaningCN":"回顾；回想（向后看）","example":"In retrospect, the warning signs were obvious.","exampleCN":"回头看来，那些警示信号很明显。"}],"latinEntries":[{"word":"despicere","structure":"de- + specere (verb)","meaning":"to look down on, scorn","meaningCN":"向下看；蔑视"},{"word":"despectus","structure":"past participle of despicere","meaning":"looked down on; contempt","meaningCN":"被看低的；蔑视"},{"word":"specere","structure":"spec- (look) + -ere (infinitive)","meaning":"to look at, observe","meaningCN":"看；观察"}]}},{"word":"detect","ipa_uk":"/dɪˈtekt/","ipa_us":"/dɪˈtekt/","definition_zh":"察觉；发现；探测；检测；侦破","definition_en":"to notice or discover something that is hidden, faint, or not immediately obvious","core_image":"在黑暗里摸到一根细得几乎感觉不到的线——它一直在，只是被盖住了","scene":"A technician sweeps the airport hall with a handheld scanner: The scanner can detect a trace of explosive inside a closed bag.","sceneCN":"这里 detect 是「探测、检测」（第 04 个义项：用仪器感知看不见的东西）；句意：这台扫描仪能检测出封闭行李中微量的爆炸物。画面里可辨识的物件：手持扫描仪、传送带、拉上的行李箱。","pos":[{"tag":"vt.","zh":"察觉；发现；探测；检测"},{"tag":"vi.","zh":"（罕）起侦探作用；可被检测"}],"collocations":[{"phrase":"detect a change","zh":"察觉变化"},{"phrase":"detect traces of","zh":"检测出……的痕迹"},{"phrase":"detect a lie","zh":"识破谎言"},{"phrase":"detect a signal","zh":"探测到信号"},{"phrase":"detect an error","zh":"发现错误"}],"forms":[{"label":"三单","form":"detects"},{"label":"过去式","form":"detected"},{"label":"过去分词","form":"detected"},{"label":"现在分词","form":"detecting"}],"derivatives":[{"word":"detection","pos":"n.","zh":"察觉；侦查；检测"},{"word":"detective","pos":"n./adj.","zh":"侦探；侦探的"},{"word":"detector","pos":"n.","zh":"探测器；检测器；检波器"},{"word":"detectable","pos":"adj.","zh":"可察觉的；可检测的"},{"word":"undetected","pos":"adj.","zh":"未被发觉的"}],"senses":[{"no":"01","title":"Uncover: the earliest sense, taking the cover off","titleCN":"揭开：最早的含义，把盖子拿掉","definition":"to uncover, lay bare, expose or reveal something (early 15c., now obsolete)","definitionCN":"揭开、使暴露、揭发某事（15 世纪早期，现已废弃）","example":"In early records, to detect a plot meant to uncover it and lay it bare.","exampleCN":"在早期文献里，detect 一桩阴谋的意思是把它揭开、暴露出来。","why":"The word entered English in the early 15c. from Latin detectus, past participle of detegere 'uncover', built on de- 'un-' + tegere 'to cover'. The literal act of lifting a cover is the ancestor of every later sense.","whyCN":"这个词在 15 世纪早期从拉丁语 detectus 进入英语，那是 detegere“揭开”的过去分词，由 de-“去掉”+ tegere“覆盖”构成。把盖子掀开这个字面动作，就是后来所有义项的祖先。"},{"no":"02","title":"Notice what is faint: the senses take the cover off","titleCN":"察觉微弱之物：感官把盖子掀开","definition":"to perceive something slight or easily missed, such as a change in tone or smell","definitionCN":"察觉到细微、容易被忽略的东西，如语气或气味的变化","example":"She detected a note of worry in his voice.","exampleCN":"她察觉到他的声音里有一丝担忧。","why":"A faint signal is covered by noise, the way an object is covered by cloth. Perceiving it is lifting that cover with the senses, so the physical metaphor passes from the hand to the ear and eye.","whyCN":"微弱的信号被噪声盖住，就像物件被布盖住。感知到它，就是用感官把那层布掀开；于是“揭开”这个物理隐喻从手转到了耳朵和眼睛。"},{"no":"03","title":"Find out: a hidden fact brought to light","titleCN":"查明：把隐藏的事实带到光下","definition":"to discover or ascertain a fact that was not previously known","definitionCN":"发现或查明此前不为人知的事实","example":"The study detected a link between sleep and memory.","exampleCN":"这项研究发现了睡眠与记忆之间的联系。","why":"The 1580s sense was 'find out the secret action or character of'; by 1756 it had widened to 'discover, find out, ascertain'. Once the cover can be lifted from a secret, it can be lifted from any unknown fact.","whyCN":"16 世纪 80 年代的义项是“查明秘密的行动或品性”；到 1756 年扩大为“发现、查明”。既然盖子能从秘密上掀开，它也就能从任何未知事实上掀开。"},{"no":"04","title":"Instrumental sensing: a machine becomes the eye","titleCN":"仪器探测：机器成了眼睛","definition":"to measure or register something by means of an instrument, especially what humans cannot sense directly","definitionCN":"用仪器测量或记录某物，尤指人无法直接感知的东西","example":"The telescope detected a faint radio pulse from a distant galaxy.","exampleCN":"望远镜探测到来自一个遥远星系的微弱射电脉冲。","why":"Instruments extend the senses. What the eye cannot uncover, a sensor uncovers; the same 'remove the cover' logic simply gets a new organ made of metal and glass.","whyCN":"仪器是感官的延伸。眼睛揭不开的，传感器能揭开；同一套“去掉遮盖”的逻辑，只是换上了一副金属和玻璃做的新器官。"},{"no":"05","title":"Medical detection: finding what the body hides","titleCN":"医学检测：找出身体藏起来的东西","definition":"to identify a disease, virus, or condition before it becomes obvious","definitionCN":"在疾病、病毒或状况明显之前将其识别出来","example":"The blood test can detect the virus weeks before symptoms appear.","exampleCN":"这项血检能在症状出现前数周检测出病毒。","why":"Medicine applies 'uncover' to the body, which hides its own processes. Screening is literally early uncovering: the disease is already there, still under a cover of no symptoms.","whyCN":"医学把“揭开”用在身体上，而身体最会藏起自己的过程。筛查字面上就是提前揭开：疾病早就在那里，只是还盖着一层“没有症状”的布。"},{"no":"06","title":"See through a deception: finding the secret action","titleCN":"识破：抓住秘密的举动","definition":"to discover someone's hidden intention, lie, or secret behaviour","definitionCN":"发现某人隐藏的意图、谎言或秘密行为","example":"The officer detected the lie at once from the way he paused.","exampleCN":"警官从他停顿的方式立刻识破了谎言。","why":"From the 1580s detect narrowed to 'find out the secret action or character of'. A lie is the purest case of a covered thing: someone is actively holding the cloth down.","whyCN":"从 16 世纪 80 年代起，detect 缩小为“查明秘密的行动或品性”。谎言是被盖住之物的最纯粹情形：有人正主动按住那块布。"},{"no":"07","title":"Trace detection: finding the residue too small to see","titleCN":"痕量检测：找出小到看不见的残留","definition":"to find a very small amount of a substance, especially in forensics or chemistry","definitionCN":"发现极少量的物质，尤用于法医或化学领域","example":"Forensic teams detected gunpowder residue on the sleeve.","exampleCN":"法医小组在袖口上检测出了火药残留。","why":"Chemistry pushes 'uncover' to the smallest scale. A trace is a cover so thin that no eye can lift it, so the word moves to the laboratory bench and the spectrum.","whyCN":"化学把“揭开”推到最小的尺度。痕迹是一层薄到眼睛掀不开的覆盖物，于是这个词走进了实验室的台面和光谱仪。"},{"no":"08","title":"Pattern detection: finding a shape inside noise","titleCN":"模式识别：在噪声里找出一条形状","definition":"to identify a regular pattern or trend in a large amount of data","definitionCN":"在大量数据中识别出规律或趋势","example":"The algorithm detects patterns that no analyst would notice by hand.","exampleCN":"这个算法能识别出手工分析绝不会注意到的模式。","why":"Statistics treats noise as a cover laid over a pattern. Detection is the removal of that cover by comparison, which is why the word fits algorithms that have no eyes at all.","whyCN":"统计学把噪声看作盖在规律上的一层布。检测就是通过比较把这层布去掉，所以这个词也适用于根本没有眼睛的算法。"},{"no":"09","title":"Radio detection: extracting the message from the wave","titleCN":"检波：从电波里取出信息","definition":"in radio, to extract a signal from a modulated carrier wave","definitionCN":"无线电中，从已调制的载波中提取信号","example":"The receiver detects the weak signal and then amplifies it.","exampleCN":"接收机检测出微弱信号，然后再把它放大。","why":"Early radio called the stage that pulled the audio out of the carrier wave detection, and the part that did it the detector. The message is covered by the wave; detecting is uncovering it.","whyCN":"早期无线电把从载波里取出音频的那一步叫作 detection，把完成它的部件叫 detector。信息被电波盖着，检测就是把它揭出来。"},{"no":"10","title":"Fault detection: finding the crack before it opens","titleCN":"故障检测：在裂缝张开之前找到它","definition":"to find a defect or impending failure in a machine or structure","definitionCN":"发现机器或结构中的缺陷或即将发生的故障","example":"Sensors detect a crack long before the wing fails.","exampleCN":"传感器远在机翼失效之前就检测到了裂缝。","why":"Engineering borrows the word for the hidden defect, because maintenance is the practice of uncovering before disaster. The cover here is metal, and the cost of leaving it on is a failure.","whyCN":"工程学借这个词指隐藏的缺陷，因为维护本来就是“在灾难之前揭开”。这里的盖子是一层金属，不揭开的代价就是失效。"}],"etymology":{"intro":{"en":"Detect comes from Latin detegere 'to uncover', de- 'un-' plus tegere 'to cover'. English took it in the early 15c. as 'uncover, expose', narrowed it to secret actions in the 1580s, and widened it to any discovery by 1756.","cn":"detect 来自拉丁语 detegere“揭开”，即 de-“去掉”+ tegere“覆盖”。英语在 15 世纪早期借入时意为“揭开、暴露”，16 世纪 80 年代缩小到“查明秘密举动”，到 1756 年又扩大为任何“发现、查明”。"},"items":[{"era":"PIE (reconstructed)","en":"The root *(s)teg- 'to cover' is reconstructed from cognates such as Greek stegein 'to cover' and English thatch. There is no written PIE record, so this level is a reconstruction, not an attested form.","cn":"词根 *(s)teg-“覆盖”是由希腊语 stegein“覆盖”、英语 thatch“茅草顶”等同源词重构出来的。原始印欧语没有书面记录，所以这一层只是重构形式，不是有据可查的形态。"},{"era":"LATIN (1C BC)","en":"Tegere meant 'to cover, hide'; detegere added de- 'off, un-' to make 'uncover, expose', figuratively 'discover, reveal'. Its past participle detectus is the form English borrowed.","cn":"tegere 意为“覆盖、遮住”；detegere 加上 de-“去掉、相反”构成“揭开、使暴露”，引申为“发现、揭露”。英语借的正是它的过去分词 detectus。"},{"era":"EARLY 15c ENGLISH","en":"The first English sense was 'uncover, lay bare, expose, disclose, reveal', now obsolete. The word still carried the physical image of lifting a covering.","cn":"英语最早的义项是“揭开、使裸露、暴露、披露、揭露”，现已废弃。那时这个词还带着掀开覆盖物的具体画面。"},{"era":"1580s ENGLISH","en":"The sense 'to find out the secret action or character of' is recorded from the 1580s. Detection becomes police work and human judgement rather than cloth and hands.","cn":"“查明秘密的行动或品性”这一义项记录于 16 世纪 80 年代。detect 由此从布匹与双手，转成了警察工作与人的判断。"},{"era":"1756 ENGLISH","en":"The broad sense 'discover, find out, ascertain' dates from 1756, opening the way to scientific and technical uses: radiation, disease, traces, patterns.","cn":"宽泛的“发现、查明”义始于 1756 年，为科技用法打开了路：辐射、疾病、痕量、模式都能 detect。"},{"era":"MODERN ENGLISH","en":"Detector, detective and detection follow the same stem. Radar stands for radio detection and ranging, and modern usage extends detect to sensors, algorithms and fault monitoring.","cn":"detector、detective、detection 都沿同一词干。radar 就是 radio detection and ranging 的缩写；现代用法把 detect 扩展到传感器、算法和故障监测。"}]},"similar":{"note":{"en":"The first group is chosen for spelling and sound, the second for meaning, so that form and sense stay separate.","cn":"第一组按拼写和读音挑选，第二组按词义挑选，这样词形和词义不会混在一起。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"detest","ipa":"/dɪˈtest/","tag":"one letter away","definition":"to hate intensely. It shares de- but comes from testis 'witness', not tegere 'cover'.","definitionCN":"憎恶；极度讨厌。同样带 de-，但来自 testis“见证人”，不是 tegere“覆盖”。"},{"word":"deduct","ipa":"/dɪˈdʌkt/","tag":"near sound","definition":"to subtract an amount. It comes from ducere 'to lead', and differs from detect in the middle consonant.","definitionCN":"扣除；减去。来自 ducere“引导”，与 detect 的差别在中间那个辅音。"},{"word":"depict","ipa":"/dɪˈpɪkt/","tag":"near spelling","definition":"to represent in a picture or in words. It comes from pingere 'to paint', not from tegere.","definitionCN":"描绘；描写。来自 pingere“画”，与 tegere 无关。"},{"word":"direct","ipa":"/dɪˈrekt/","tag":"near sound","definition":"straight; to guide. It begins with the same de- sound but has an /r/ where detect has a /t/.","definitionCN":"直接的；指导。开头有同样的 de- 音，但 detect 的 /t/ 在这里换成了 /r/。"}]},{"heading":"NEAR MEANING","entries":[{"word":"discover","ipa":"/dɪˈskʌvə(r)/","tag":"find what was hidden","definition":"to find something that was already there but unknown. It matches detect in the 'find out a fact' sense.","definitionCN":"发现原本存在但不为人知的东西。对应 detect 表“查明事实”的义项。"},{"word":"notice","ipa":"/ˈnəʊtɪs/","tag":"see without effort","definition":"to become aware of something through attention. It is weaker than detect and implies no covering to remove.","definitionCN":"注意到；留意到。比 detect 弱，不含“去掉遮盖”的意味。"},{"word":"perceive","ipa":"/pəˈsiːv/","tag":"sensory or mental","definition":"to become aware of through the senses or the mind. It matches the 'notice what is faint' sense.","definitionCN":"感知；察觉。对应 detect 表“察觉微弱之物”的义项。"},{"word":"spot","ipa":"/spɒt/","tag":"sudden and visual","definition":"to see or recognize suddenly, often by eye. It is quicker and more visual than detect.","definitionCN":"一眼发现；认出。比 detect 更快，也更依赖视觉。"},{"word":"identify","ipa":"/aɪˈdentɪfaɪ/","tag":"name what is found","definition":"to recognize and name something. It goes one step further than detect: finding plus classification.","definitionCN":"识别；确认。比 detect 多一步：不仅发现，还归类命名。"}]}]},"mnemonics":{"normalIntro":{"en":"These links are real: de- + teg- 'cover', the detector inside a radio, and detective as a shortening of detective police (1828).","cn":"这些联想都是真实的：de- + teg-“覆盖”、收音机里的 detector，以及 1828 年由 detective police 缩略而成的 detective。"},"normal":[{"en":"de- 'off' + tect 'cover': to detect is to take the cover off. Every sense keeps that one gesture.","cn":"de-“去掉”+ tect“盖子”：detect 就是把盖子拿掉。所有义项都保留着这一个动作。"},{"en":"Protect is the same tegere with pro- 'in front': to protect is to cover in front, to detect is to take the cover off. Opposite prefixes, one root.","cn":"protect 是同一个 tegere 加 pro-“在前面”：保护是在前面盖上，检测是把盖子揭开。前缀相反，词根相同。"},{"en":"Detective (1828) is short for detective police: the person whose job is detecting. The noun came from the adjective.","cn":"detective（1828）是 detective police 的缩略，指以 detecting 为业的人。名词是从形容词变来的。"},{"en":"Radar = radio detection and ranging, so the word is literally built into the name of the machine.","cn":"radar = radio detection and ranging，这个词就字面地造在这台机器的名字里。"},{"en":"Detect and detest sit one letter apart: detect removes a cover, detest calls a witness (testis) against someone.","cn":"detect 和 detest 只差一个字母：detect 揭盖子，detest 则是叫见证人（testis）来指证。"}],"abstract":[{"en":"Cover and uncover are one act seen from two sides: a secret is only a secret while the cloth stays on.","cn":"盖与揭是同一个动作的两面：秘密之所以是秘密，只因为那块布还没被掀开。"},{"en":"The word travels from hands to senses to instruments to statistics: each step finds a thinner cover and a finer eye.","cn":"这个词从手走到感官，再走到仪器和统计：每一步都在找更薄的遮盖和更精细的眼睛。"},{"en":"So a whisper, a virus, a lie, a radio wave and a crack are one thing: something under a cover, waiting to be uncovered.","cn":"所以一声低语、一种病毒、一句谎话、一道电波、一条裂缝都是同一件事：被盖住的东西，等着被揭开。"}]},"examples":[{"en":"The human ear cannot detect sounds above about twenty kilohertz.","cn":"人耳无法察觉频率约两万赫兹以上的声音。"},{"en":"The software detects unusual activity on the network within seconds.","cn":"该软件能在几秒内检测出网络上的异常活动。"},{"en":"Doctors detected the tumour early, when it was still easy to treat.","cn":"医生及早发现了肿瘤，那时还容易治疗。"}],"dict_mnemonic":{"note":"词根拆解 · 有词源依据","text":"de（去掉）+ tect（盖子）：把盖子揭掉，就 detect 了——察觉、探测","word":"detect"},"root":"源自拉丁语 detegere“揭开”（de 去掉 + tegere 覆盖），过去分词 detectus；15 世纪早期进入英语，原义“使暴露”，后引申为“察觉、查明、探测”。","sensesIntro":{"en":"Ten senses of detect, all built on one gesture: lifting a cover. From a cloth over an object, the word moves to a faint sound, a secret, a virus, a radio wave, a pattern in data and a crack in metal.","cn":"detect 的十个义项都建立在同一个动作上：掀开遮盖。从盖在物件上的布开始，这个词走向微弱的声音、秘密、病毒、电波、数据中的规律和金属里的裂缝。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand lifting a cover off something that was there all along.","cn":"核心意象：一只手掀开盖子，露出一直在那儿的东西。"},"chain":["LIFT THE COVER","SEE WHAT WAS HIDDEN","NAME THE SECRET","EXTEND THE SENSE","MEASURE THE TRACE","FIND THE PATTERN"],"branches":[{"senses":"S01","en":"THE LITERAL HAND: the early sense 'uncover, expose', where the cover is real cloth and the act is physical.","cn":"字面上的手：早期义“揭开、暴露”，盖子是真的布，动作是身体的。"},{"senses":"S02 · S03","en":"THE SENSES AND THE MIND: a faint sound is noticed, then a hidden fact is established.","cn":"感官与心智：先察觉微弱的声音，再查明隐藏的事实。"},{"senses":"S04 · S05 · S09","en":"THE INSTRUMENT: machines, medical tests and radios uncover what no eye or ear can reach.","cn":"仪器：机器、医学检验和无线电揭开眼睛和耳朵够不到的东西。"},{"senses":"S06 · S07","en":"THE SECRET AND THE TRACE: a lie held down by a person, and a residue too thin for any eye.","cn":"秘密与痕迹：被人按住的一桩谎言，以及薄到任何眼睛都看不清的残留。"},{"senses":"S08 · S10","en":"THE PATTERN AND THE FAULT: statistics uncovers shapes in noise, engineering uncovers cracks before failure.","cn":"规律与故障：统计在噪声里揭出形状，工程在失效前揭出裂缝。"}]},"affixes":{"intro":{"en":"Detect is built from Latin de- 'off, un-' and the root teg- 'cover', with relatives in protect, tegument and integument, plus the derived family detection, detective, detector.","cn":"detect 由拉丁语 de-“去掉、相反”与词根 teg-“覆盖”构成，亲属有 protect、tegument、integument，以及派生家族 detection、detective、detector。"},"latinIntro":{"en":"Latin tegere 'to cover' gives detegere 'uncover' and protegere 'cover in front, protect'; the root *(s)teg- is reconstructed, so no attested PIE form should be quoted.","cn":"拉丁语 tegere“覆盖”构成 detegere“揭开”和 protegere“在前面盖上、保护”；词根 *(s)teg- 是重构形式，不应引用成有据可查的原始印欧语形态。"},"items":[{"word":"detect","structure":"de- (off, un-) + tect- (cover)","meaning":"to uncover; hence to notice or discover","meaningCN":"揭开；由此引申为察觉、发现","example":"The sensor detects smoke within seconds.","exampleCN":"传感器在几秒内检测到烟雾。"},{"word":"detection","structure":"detect + -ion (noun of action)","meaning":"the act of uncovering or discovering","meaningCN":"察觉；侦查；检测（动作名词）","example":"Early detection greatly improves survival rates.","exampleCN":"早期发现大大提高生存率。"},{"word":"detective","structure":"detect + -ive (adjective, then noun)","meaning":"skilled in detecting; a person who investigates","meaningCN":"擅长侦查的；侦探","example":"A detective interviewed the neighbours.","exampleCN":"一名侦探走访了邻居。"},{"word":"detector","structure":"detect + -or (agent noun)","meaning":"a device or person that detects","meaningCN":"探测器；检测器；检波器","example":"The smoke detector woke the whole family.","exampleCN":"烟雾报警器叫醒了全家。"},{"word":"detectable","structure":"detect + -able (can be)","meaning":"able to be noticed or measured","meaningCN":"可察觉的；可检测的","example":"The drug is detectable for several days.","exampleCN":"这种药在体内数天内都可检出。"},{"word":"undetected","structure":"un- (not) + detect + -ed","meaning":"not noticed or discovered","meaningCN":"未被发觉的","example":"The leak went undetected for months.","exampleCN":"这个泄漏数月未被发现。"},{"word":"protect","structure":"pro- (in front) + tect- (cover)","meaning":"to cover in front; to keep safe","meaningCN":"保护（在前面盖上）","example":"The roof protects the house from rain.","exampleCN":"屋顶为房子挡雨。"},{"word":"protection","structure":"protect + -ion","meaning":"the act of keeping something safe","meaningCN":"保护；防护","example":"The law offers protection to whistle-blowers.","exampleCN":"法律为举报人提供保护。"},{"word":"tegument","structure":"teg- (cover) + -ment (noun)","meaning":"a natural covering or integument","meaningCN":"天然覆盖物；外皮","example":"The seed's tegument shields the embryo.","exampleCN":"种子的外皮保护着胚。"},{"word":"integument","structure":"in- (in, on) + teg- (cover) + -ment","meaning":"a covering layer, such as skin","meaningCN":"覆盖层；（生物的）外皮","example":"The integument of the insect is hardened.","exampleCN":"这只昆虫的外皮已经硬化。"}],"latinEntries":[{"word":"tegere","structure":"teg- (cover) + -ere (infinitive)","meaning":"to cover, hide","meaningCN":"覆盖；遮盖"},{"word":"detegere","structure":"de- (off) + tegere","meaning":"to uncover, expose","meaningCN":"揭开；使暴露"},{"word":"detectus","structure":"past participle of detegere","meaning":"uncovered, exposed","meaningCN":"被揭开的；被暴露的"}]}},{"word":"determine","ipa_uk":"/dɪˈtɜːmɪn/","ipa_us":"/dɪˈtɜːrmɪn/","definition_zh":"决定；确定；测定；下定决心；裁定","definition_en":"to decide something, fix it exactly, or establish it by investigation","core_image":"在土地尽头钉下一根界桩——线一划定，事情就没有别的可能","scene":"A surveyor drives a stake into the ground at the corner of the lot: A quick soil test will determine whether the land can be built on.","sceneCN":"这里 determine 是「测定、查明」（第 04 个义项：通过调查得出确切结果）；句意：一次快速的土壤检测将确定这块地能否建房。画面里可辨识的物件：界桩、测绳、取土钻。","pos":[{"tag":"vt.","zh":"决定；确定；测定；裁定"},{"tag":"vi.","zh":"下决心；作出决定"}],"collocations":[{"phrase":"determine whether","zh":"确定是否……"},{"phrase":"determine the cause","zh":"查明原因"},{"phrase":"be determined to do","zh":"决心做某事"},{"phrase":"determine the outcome","zh":"决定结果"},{"phrase":"determine the price","zh":"确定价格"}],"forms":[{"label":"三单","form":"determines"},{"label":"过去式","form":"determined"},{"label":"过去分词","form":"determined"},{"label":"现在分词","form":"determining"}],"derivatives":[{"word":"determination","pos":"n.","zh":"决心；确定；裁定"},{"word":"determined","pos":"adj.","zh":"坚决的；已确定的"},{"word":"determiner","pos":"n.","zh":"决定因素；限定词"},{"word":"determinate","pos":"adj.","zh":"确定的；有明确界限的"},{"word":"determinism","pos":"n.","zh":"决定论"}],"senses":[{"no":"01","title":"Set the boundary: the original act of limiting","titleCN":"划定边界：最初的那个限定动作","definition":"to fix the limits or bounds of something; to mark where it ends","definitionCN":"确定某事物的范围或界限；标出它到哪里为止","example":"The treaty determined the border at the river.","exampleCN":"条约把边界定在了那条河上。","why":"Latin determinare is de- 'off' + terminare 'to mark the end', from terminus 'boundary stone'. To determine was first to drive the boundary stake in, an act in space before it was an act in the mind.","whyCN":"拉丁语 determinare 是 de-“离开”+ terminare“标出终点”，后者来自 terminus“界桩”。determine 最初就是把界桩钉进土里，是先发生在空间里、后才发生在心里的动作。"},{"no":"02","title":"Settle a question: bring the argument to its end","titleCN":"决定：把争论带到终点","definition":"to decide a question or dispute officially or conclusively","definitionCN":"正式或最终地决定一个问题或争端","example":"The committee will determine which proposal goes forward.","exampleCN":"委员会将决定哪一份提案进入下一轮。","why":"Once a boundary is fixed, a dispute has no room left to move. The spatial limit becomes a logical one: deciding is ending an argument by drawing its limit.","whyCN":"边界一旦钉死，争论就没有可移动的余地。空间上的界限于是变成了逻辑上的界限：决定，就是通过划定界线来结束争论。"},{"no":"03","title":"Resolve: the will sets a limit on itself","titleCN":"下定决心：意志给自己划界","definition":"to make a firm decision or intention to do something","definitionCN":"作出坚定的决定或意图去做某事","example":"She determined to finish the race despite her injury.","exampleCN":"她下定决心，尽管受伤也要跑完比赛。","why":"Late 14c. records 'come to a firm decision or definite intention'. Wavering is an open field; resolve closes it by fixing one's own course, the same boundary drawn inward.","whyCN":"14 世纪后期记录了“作出坚定决定或明确意图”的用法。犹豫是一片敞开的空地；决心通过定下自己的路线把它封住，还是同一条界线，只是画向了内部。"},{"no":"04","title":"Ascertain: find the fact and pin it down","titleCN":"测定：把事实查清并钉住","definition":"to establish or find out something by investigation, calculation, or observation","definitionCN":"通过调查、计算或观察确立或查明某事","example":"Investigators are trying to determine what caused the fire.","exampleCN":"调查人员正设法查明火灾的起因。","why":"The sense 'find (as the solution of a problem)' dates from the 1640s. An unknown is treated as an area with an edge; determining is locating that edge by evidence rather than by decree.","whyCN":"“求出（问题的解答）”这一义项始于 17 世纪 40 年代。未知被当作一块有边界的区域；测定就是靠证据而不是靠命令找到那条边。"},{"no":"05","title":"Rule: the judgment that closes a case","titleCN":"裁定：让案件闭合的判决","definition":"to decide a case or issue as a judge or authority","definitionCN":"作为法官或权威对案件或争议作出裁决","example":"The court determined that the contract was void.","exampleCN":"法院裁定该合同无效。","why":"The legal sense 'render judgment' is from the early 15c. A ruling is the official boundary line of a case: past it, the matter is closed and cannot be argued again.","whyCN":"法律义“作出判决”始于 15 世纪早期。判决就是一个案件的官方边界线：越过去，事情就闭合了，不能再争。"},{"no":"06","title":"Give a direction to: fixing which way a thing runs","titleCN":"决定走向：固定事物朝哪边运行","definition":"to give a direction or tendency to something; to shape its course","definitionCN":"给某事物以方向或趋势；塑造其走向","example":"The angle of the light determines the length of the shadow.","exampleCN":"光线的角度决定了影子的长度。","why":"Early 15c. also records 'give direction or tendency to'. A terminus does not only stop movement; it tells you which way the line runs, so determining becomes shaping a course.","whyCN":"15 世纪早期还记录了“给予方向或趋势”的用法。终点不只让运动停下，它还告诉你这条线朝哪边走，于是 determine 又成了塑造走向。"},{"no":"07","title":"Be the decisive factor: one link fixes the whole chain","titleCN":"起决定作用：一环定住整条链","definition":"to be the factor that decides the result of a process or event","definitionCN":"成为决定某一过程或事件结果的因素","example":"One vote determined the outcome of the election.","exampleCN":"一票决定了选举的结果。","why":"If a factor fixes the limit, it has decided the result. The causal and the spatial senses meet here: the thing that draws the line is the thing that settles the matter.","whyCN":"如果一个因素定住了界限，它就已经决定了结果。因果义和空间义在这里合流：划出那条线的东西，就是让事情定局的东西。"},{"no":"08","title":"Solve: locate the unknown in an equation","titleCN":"求解：在方程里定位未知量","definition":"in mathematics, to find the value of an unknown quantity","definitionCN":"数学上求出未知量的值","example":"Solve the equation to determine the value of x.","exampleCN":"解这个方程，求出 x 的值。","why":"The 1640s mathematical use treats the unknown as a point located by boundary conditions. You cannot say what x is until the constraints have fixed where it can sit.","whyCN":"17 世纪 40 年代的数学用法把未知量当作由边界条件定位的一个点。在约束条件固定住它可以待的位置之前，你说不出 x 是什么。"},{"no":"09","title":"Impel someone to act: fixing another person's course","titleCN":"使人下定决心：替别人定下路线","definition":"to cause or impel someone to do something (archaic)","definitionCN":"使或促使某人做某事（古义）","example":"The news determined him to leave at once.","exampleCN":"这个消息使他决定立刻离开。","why":"The old 'give direction to' sense was applied to people: to fix a course for someone is to push them onto it. Modern English keeps the trace in 'determine someone to do'.","whyCN":"古老的“给予方向”义被用在人身上：替某人定下路线，就是把他推上那条路。现代英语仍在 determine someone to do 里留着这道痕迹。"},{"no":"10","title":"Fix a date: marking a point in time","titleCN":"测定年代：在时间上标出一个点","definition":"to establish the date, age, or time of something","definitionCN":"确定某事物的日期、年代或时间","example":"Scientists determined the age of the fossil from the rock layer.","exampleCN":"科学家根据岩层测定了这块化石的年代。","why":"Latin terminus marked boundaries in time as well as in space. Chronology needs the same cut: an age is fixed by finding the marker that says 'before this, not after'.","whyCN":"拉丁语 terminus 既标空间边界，也标时间的界点。年代学需要同一刀：测年就是找到那个写着“在此之后，不在此前”的标记。"}],"etymology":{"intro":{"en":"Determine comes from Latin determinare 'to enclose, bound, set limits to', from de- 'off' + terminare 'mark the end', from terminus 'boundary stone'. English took it in the late 14c. with both the spatial and the deciding sense.","cn":"determine 来自拉丁语 determinare“围住、限定、设定边界”，由 de-“离开”+ terminare“标出终点”构成，后者源于 terminus“界桩”。英语在 14 世纪后期借入时就同时带着空间义和决定义。"},"items":[{"era":"PIE (reconstructed)","en":"Terminus is traced to the reconstructed root *ter- 'peg, post; boundary, marker'. Cognates include Greek terma 'boundary, end-point' and Sanskrit tarati 'crosses over'. No written PIE form exists, so this step is reconstruction only.","cn":"terminus 可追溯到重构词根 *ter-“桩、柱；边界、标记”。同源词有希腊语 terma“边界、终点”和梵语 tarati“越过”。原始印欧语没有书面形式，所以这一步只是重构。"},{"era":"LATIN (before 1C BC)","en":"Terminus meant 'an end, a limit, boundary line', and was also the name of the Roman god who guarded boundaries. Determinare added de- to terminare 'mark the end or boundary', giving 'enclose, bound, set limits to'.","cn":"terminus 意为“终点、界限、边界线”，也是罗马守护边界的界神之名。determinare 由 de- 加 terminare“标出终点或边界”构成，意为“围住、限定、设定边界”。"},{"era":"LATE 14c ENGLISH","en":"The first English records give 'to settle, decide upon; state definitely; fix the bounds of; limit in time or extent', and 'come to a firm decision or definite intention'.","cn":"英语最早的记录是“解决、决定；明确陈述；确定……的边界；在时间或范围上限定”，以及“作出坚定决定或明确意图”。"},{"era":"EARLY 15c ENGLISH","en":"'Render judgment' is recorded from the early 15c., and so is 'give direction or tendency to'. The courtroom and the physical course branch off at the same moment.","cn":"“作出判决”记录于 15 世纪早期，“给予方向或趋势”也是同一时期。法庭义与物理走向义在同一时刻分叉。"},{"era":"1640s ENGLISH","en":"'To find (as the solution of a problem)' appears in the 1640s, which opens the mathematical and scientific career of the word.","cn":"“求出（问题的解答）”出现于 17 世纪 40 年代，由此开启了这个词在数学和科学中的历程。"},{"era":"MODERN ENGLISH","en":"Modern English keeps the whole spread: fix a limit, decide, ascertain, rule, shape a course, and solve. Determination also names the quality of a will that has closed its own field.","cn":"现代英语保留了整片语义：限定、决定、查明、裁定、塑造走向、求解。determination 还指那种已经把自己那片地封住的意志品质。"}]},"similar":{"note":{"en":"The first group is chosen for spelling and sound, the second for meaning, so that form and sense stay separate.","cn":"第一组按拼写和读音挑选，第二组按词义挑选，这样词形和词义不会混在一起。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"deter","ipa":"/dɪˈtɜː(r)/","tag":"shortened look-alike","definition":"to discourage someone from acting, especially by threat. It is much shorter and has no -mine ending.","definitionCN":"威慑；使不敢。词形短得多，也没有 -mine 结尾。"},{"word":"terminate","ipa":"/ˈtɜːmɪneɪt/","tag":"same root, verb","definition":"to bring to an end. It shares terminus with determine but means ending, not fixing a limit.","definitionCN":"终止；结束。与 determine 同出 terminus，但意思是“结束”，不是“划定界限”。"},{"word":"dimension","ipa":"/daɪˈmenʃn/","tag":"near spelling","definition":"a measurement of length, width, or depth. It looks similar but comes from metiri 'to measure'.","definitionCN":"维度；尺寸。拼写相近，但来自 metiri“测量”。"},{"word":"dominant","ipa":"/ˈdɒmɪnənt/","tag":"near sound","definition":"most powerful or noticeable. It starts with domin- 'master', not termin- 'boundary'.","definitionCN":"占主导的。开头是 domin-“主人”，不是 termin-“边界”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"decide","ipa":"/dɪˈsaɪd/","tag":"cut off","definition":"to choose after consideration. It matches determine in the 'settle a question' sense and is more everyday.","definitionCN":"决定；抉择。对应 determine 表“决定问题”的义项，更日常。"},{"word":"settle","ipa":"/ˈsetl/","tag":"bring to rest","definition":"to end a dispute or arrange something finally. It stresses the argument coming to rest.","definitionCN":"解决；安顿。强调争论停下来、事情落定。"},{"word":"ascertain","ipa":"/ˌæsəˈteɪn/","tag":"find out for certain","definition":"to find out something with certainty. It matches the 'establish by investigation' sense and is formal.","definitionCN":"查明；确定。对应“通过调查确立”的义项，较正式。"},{"word":"resolve","ipa":"/rɪˈzɒlv/","tag":"firm intention","definition":"to decide firmly or solve a problem. It matches determine in the sense of a will that settles itself.","definitionCN":"决心；解决。对应 determine 表“意志自我定夺”的义项。"},{"word":"establish","ipa":"/ɪˈstæblɪʃ/","tag":"make certain","definition":"to prove or make something certain. It overlaps with determine when a fact is being fixed.","definitionCN":"确立；证实。在“把事实固定下来”这一层与 determine 重叠。"}]}]},"mnemonics":{"normalIntro":{"en":"These links are real: terminus was a boundary stone and a Roman god, and determinare is de- plus terminare 'mark the end'.","cn":"这些联想都是真实的：terminus 既是界桩，也是罗马界神；determinare 就是 de- 加 terminare“标出终点”。"},"normal":[{"en":"Terminus is a boundary stone: determine is to drive that stone into the ground. Picture the stake before you picture the decision.","cn":"terminus 是界桩：determine 就是把这根桩钉进土里。先想那根桩，再想那个决定。"},{"en":"de- + termin (end): to determine is to put an end to doubt. The same -term- sits in terminal, terminate and interminable.","cn":"de- + termin（终点）：determine 就是给疑惑画上句号。同样的 -term- 还在 terminal、terminate、interminable 里。"},{"en":"Determined (adjective) means the end is fixed in the mind: a person who has stopped considering other routes.","cn":"determined（形容词）指终点已在心里定死：一个不再考虑其他路线的人。"},{"en":"In maths, determining x is finding where it can sit; in law, determining a case is drawing the line past which no one argues.","cn":"数学里 determine x 是找出它能在哪儿落脚；法律里 determine 一个案子是划出一条越过后无人再争的线。"},{"en":"Do not confuse determine with deter: deter is de- + terrere 'frighten', so it scares you away instead of fixing a line.","cn":"别把 determine 和 deter 混了：deter 是 de- + terrere“使害怕”，它把你吓退，而不是划定一条线。"}],"abstract":[{"en":"A line drawn once turns an open field into a decided place. Every sense of determine is that line drawn in soil, in time, in a mind, in a case, or in an equation.","cn":"一条线一旦画出，开阔的田野就变成了已定的地方。determine 的每个义项，都是这条线画在土地、时间、心里、案卷上或方程里。"},{"en":"The cut moves inward: first space, then argument, then will, then fact. What begins as a fence ends as a verdict.","cn":"这一刀由外向内移：先是空间，再是争论，再是意志，再是事实。起初是一道篱笆，最后成了一句裁决。"},{"en":"So 'border', 'decide', 'measure', 'rule', and 'resolve' are one act at five depths: the same stake, driven deeper each time.","cn":"所以“划界、决定、测定、裁定、决心”是同一个动作在五个深度上的样子：同一根桩，一次比一次钉得深。"}]},"examples":[{"en":"The colour of the sky is determined by how sunlight scatters in the air.","cn":"天空的颜色由阳光在空气中的散射方式决定。"},{"en":"A single test cannot determine whether the water is safe to drink.","cn":"单次检测无法确定这水是否可安全饮用。"},{"en":"They were determined to reopen the shop before the winter.","cn":"他们下定决心要在入冬前把店重新开起来。"}],"dict_mnemonic":{"note":"词根拆解 · 有词源依据","text":"de（加强）+ termin（界限、终点）：划出界限，就 determine 了——决定、确定","word":"determine"},"root":"源自拉丁语 determinare“围住、限定”（de 离开 + terminare 标出终点，源于 terminus 界桩），14 世纪后期进入英语，由“划定界限”引申为“决定、测定、裁定”。","sensesIntro":{"en":"Ten senses of determine, all built on one act: drawing a line that ends something. The line is first spatial, then logical, then personal, then legal, then numerical, then temporal.","cn":"determine 的十个义项都建立在一个动作上：画出终结某事的线。这条线先是空间的，然后是逻辑的、个人的、法律的、数值的，最后是时间的。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stake driven in at the edge, and nothing beyond it counts.","cn":"核心意象：在边缘钉下一根桩，桩外的一切都不算数。"},"chain":["MARK THE END","FIX THE LIMIT","CLOSE THE QUESTION","SET THE WILL","FIND THE FACT","SETTLE THE RESULT"],"branches":[{"senses":"S01 · S10","en":"THE BOUNDARY IN SPACE AND TIME: the original limit, and the same cut applied to a date or an age.","cn":"空间与时间的边界：最初的限定，以及同一刀用在日期或年代上。"},{"senses":"S02 · S05","en":"THE CLOSED QUESTION: a dispute and a court case both end when the line is drawn.","cn":"被关上问题：争论与案件都在界线画出时结束。"},{"senses":"S03 · S09","en":"THE WILL: one's own wavering is bounded, and in the old sense another person's course is fixed too.","cn":"意志：自己的犹豫被圈住；在古义里，别人的路线也被定下。"},{"senses":"S04 · S08","en":"THE UNKNOWN MEASURED: evidence locates a fact, boundary conditions locate an unknown quantity.","cn":"被测量的未知：证据定位事实，边界条件定位未知量。"},{"senses":"S06 · S07","en":"THE COURSE AND THE CAUSE: a limit gives direction, and whatever fixes the limit decides the result.","cn":"走向与成因：界限给出方向，而定住界限的东西决定结果。"}]},"affixes":{"intro":{"en":"Determine is built from de- and the Latin stem termin- 'end, boundary', the same stem behind terminal, terminate, terminus and exterminate.","cn":"determine 由 de- 与拉丁词干 termin-“终点、边界”构成；terminal、terminate、terminus、exterminate 都出自同一词干。"},"latinIntro":{"en":"Latin terminus 'boundary stone' gives terminare 'mark the end' and determinare 'set limits to'; the Roman god Terminus guarded the same stone the word names.","cn":"拉丁语 terminus“界桩”构成 terminare“标出终点”和 determinare“设定边界”；罗马界神 Terminus 守护的正是这个词所指的那块石头。"},"items":[{"word":"determine","structure":"de- (off) + termin- (end, boundary) + -e","meaning":"to set the limit; hence to decide or ascertain","meaningCN":"划定界限；由此引申为决定、测定","example":"The judge will determine the sentence next week.","exampleCN":"法官下周将裁定刑期。"},{"word":"determination","structure":"determine + -ation (noun of action)","meaning":"the act of deciding; firmness of purpose","meaningCN":"决定；裁定；决心","example":"Her determination impressed everyone on the team.","exampleCN":"她的决心让队里每个人都印象深刻。"},{"word":"determined","structure":"determine + -ed (past participle as adjective)","meaning":"having a fixed purpose; settled","meaningCN":"坚决的；已确定的","example":"They were determined to finish the bridge on time.","exampleCN":"他们决心按时建成这座桥。"},{"word":"determiner","structure":"determine + -er (agent noun)","meaning":"something that decides; a word that limits a noun","meaningCN":"决定因素；限定词","example":"In 'the book', 'the' is a determiner.","exampleCN":"在 the book 中，the 是限定词。"},{"word":"determinate","structure":"determine + -ate (adjective)","meaning":"having definite limits","meaningCN":"确定的；有明确界限的","example":"The project has a determinate budget and end date.","exampleCN":"这个项目有明确的预算和截止日期。"},{"word":"determinism","structure":"determine + -ism (doctrine)","meaning":"the doctrine that events are fixed by prior causes","meaningCN":"决定论（认为事件由先前原因决定）","example":"Determinism denies that the will is entirely free.","exampleCN":"决定论否认意志完全自由。"},{"word":"indeterminate","structure":"in- (not) + determinate","meaning":"not fixed or known precisely","meaningCN":"不确定的；无法精确确定的","example":"The cause of the illness remained indeterminate.","exampleCN":"病因仍无法确定。"},{"word":"terminal","structure":"termin- (end) + -al (adjective/noun)","meaning":"at the end; a place where a line ends","meaningCN":"末端的；终点站","example":"The bus terminal was crowded at midnight.","exampleCN":"午夜时公交总站很拥挤。"},{"word":"terminate","structure":"termin- (end) + -ate (verb)","meaning":"to bring to an end","meaningCN":"终止；结束","example":"The company terminated the contract early.","exampleCN":"公司提前终止了合同。"},{"word":"exterminate","structure":"ex- (out) + termin- (boundary) + -ate","meaning":"to drive out beyond the boundary; to destroy completely","meaningCN":"逐出边界；彻底消灭","example":"The campaign aimed to exterminate the invasive insect.","exampleCN":"这项行动旨在彻底消灭这种入侵昆虫。"}],"latinEntries":[{"word":"terminus","structure":"termin- (boundary) + -us (noun)","meaning":"end, limit, boundary stone","meaningCN":"终点；界限；界桩"},{"word":"terminare","structure":"terminus + -are (verb)","meaning":"to mark the end or boundary","meaningCN":"标出终点或边界"},{"word":"determinare","structure":"de- + terminare","meaning":"to enclose, bound, set limits to","meaningCN":"围住；限定；设定边界"}]}},{"word":"develop","ipa_uk":"/dɪˈveləp/","ipa_us":"/dɪˈveləp/","definition_zh":"发展；开发；培养；生长；显影；发病","definition_en":"to grow or change into a fuller form, or to bring out what is hidden or potential","core_image":"把卷起的一幅画慢慢展开，藏在褶子里的内容一点一点露出来","scene":"A gardener crouches beside the bed she planted in spring: Over the summer, the seedlings developed into tall plants with broad leaves.","sceneCN":"这里 develop 是「生长、发育」（第 02 个义项：不及物，逐步长成完整形态）；句意：整个夏天，幼苗长成了叶片宽大的高株。画面里可辨识的物件：幼苗、宽叶、逐渐长高的支架。","pos":[{"tag":"vt.","zh":"开发；培养；使发展；显影"},{"tag":"vi.","zh":"发展；生长；逐渐显现；发病"}],"collocations":[{"phrase":"develop into","zh":"发展成；长成"},{"phrase":"develop a habit","zh":"养成习惯"},{"phrase":"developing countries","zh":"发展中国家"},{"phrase":"develop from","zh":"由……发展而来"},{"phrase":"research and development","zh":"研究与开发（研发）"}],"forms":[{"label":"三单","form":"develops"},{"label":"过去式","form":"developed"},{"label":"过去分词","form":"developed"},{"label":"现在分词","form":"developing"}],"derivatives":[{"word":"development","pos":"n.","zh":"发展；开发；进展"},{"word":"developer","pos":"n.","zh":"开发者；开发商；显影剂"},{"word":"developing","pos":"adj.","zh":"发展中的；显影的"},{"word":"developed","pos":"adj.","zh":"发达的；已开发的"},{"word":"redevelop","pos":"vt.","zh":"重新开发；改建"}],"senses":[{"no":"01","title":"Unroll: the picture taken out of its folds","titleCN":"展开：把画从褶子里取出来","definition":"to unroll or unfold something physically (1650s, now obsolete)","definitionCN":"把某物物理上展开、摊开（17 世纪 50 年代，现已废弃）","example":"In the old sense, to develop a scroll was to unroll it across the table.","exampleCN":"在古义里，develop 一卷书就是把它在桌上展开。","why":"The word entered English in the 1650s from French développer, from Old French des- 'undo' + voloper 'wrap up'. The first meaning was literal: take the wrap off and let what is inside lie flat.","whyCN":"这个词在 17 世纪 50 年代从法语 développer 进入英语，源自古法语 des-“取消”+ voloper“包裹”。最初的意思是字面的：去掉包裹，让里面的东西平摊出来。"},{"no":"02","title":"Grow into a fuller form: the seed unfolds itself","titleCN":"长成：种子把自己展开","definition":"to come gradually into existence or into a fuller, more advanced form","definitionCN":"逐渐出现，或逐渐长成更完整、更高级的形态","example":"The seedlings developed into tall plants over the summer.","exampleCN":"整个夏天，幼苗长成了高株。","why":"The intransitive sense 'come gradually into existence or operation' is recorded by 1793. What a seed holds is folded inside it; growth is that picture unfolding without anyone's hands.","whyCN":"不及物义“逐渐出现或开始运作”记录于 1793 年。种子所藏的东西是折在里面的；生长就是那幅画不需要任何人的手，自己展开。"},{"no":"03","title":"Bring out the potential in someone","titleCN":"培养：把某人身上的潜能引出来","definition":"to cultivate or bring out the ability, potential, or quality that is latent in someone or something","definitionCN":"培养或引出某人或某物身上潜在的能力、潜力或品质","example":"The programme develops young writers by giving them real audiences.","exampleCN":"这个项目通过给年轻写作者真实读者来培养他们。","why":"The transitive sense 'unfold more fully, bring out the potential in' dates from 1750. Here another person plays the hand that unfolds: the talent was folded up, and teaching opens it.","whyCN":"及物义“更充分地展开、引出潜能”始于 1750 年。这里由别人来当那只展开的手：才能本是折起的，教学把它打开。"},{"no":"04","title":"Advance through stages: one panel after another","titleCN":"逐步进展：一幅接一幅地展开","definition":"to advance from one stage to another toward a finished state","definitionCN":"从一个阶段推进到另一个阶段，走向完成状态","example":"The project developed from a sketch into a national network.","exampleCN":"这个项目从一张草图发展成了全国性网络。","why":"The sense 'advance from one stage to another toward a finished state' is from 1843. Each stage is another panel of the scroll shown; progress is the order in which the folds open.","whyCN":"“从一个阶段推进到另一阶段直至完成”这一义项始于 1843 年。每个阶段都是画卷上又展开的一幅；进展就是这些褶子打开的次序。"},{"no":"05","title":"Develop land: unfolding its latent uses","titleCN":"开发土地：把土地潜在的用途展开","definition":"to convert land or property to practical or profitable use","definitionCN":"把土地或房产转为实际或有利可图的用途","example":"The firm developed the old dock into apartments.","exampleCN":"这家公司把旧码头开发成了公寓。","why":"The real estate sense dates from 1865. Land has uses folded into it—housing, shops, roads—and building is the act of unfolding one of them into the open.","whyCN":"房地产义始于 1865 年。土地里折着多种用途——住宅、商铺、道路——而建造就是把其中一种展开到明处。"},{"no":"06","title":"Photography: bringing out the latent image","titleCN":"显影：让潜影显出来","definition":"to treat film or paper with chemicals so that a hidden image becomes visible","definitionCN":"用化学品处理胶片或相纸，使隐藏的影像变得可见","example":"Soak the film in the bath until the image develops.","exampleCN":"把胶片泡在药液里，直到影像显出来。","why":"The photographic sense is from 1845 and uses the metaphor with almost no change: the picture is already on the film but invisible, and the chemicals unfold it. This is the clearest proof that develop means 'make visible what was folded in'.","whyCN":"摄影义始于 1845 年，几乎原封不动地用了这个隐喻：影像早已在胶片上，只是看不见，药水把它展开。这是“把折起来的东西变可见”最清楚的证据。"},{"no":"07","title":"Develop a disease: symptoms unfold in the body","titleCN":"发病：症状在身体里展开","definition":"to begin to have a disease or symptom","definitionCN":"开始患某种疾病或出现某种症状","example":"He developed a fever two days after the trip.","exampleCN":"旅行两天后，他开始发烧。","why":"Medicine borrows the intransitive 'come gradually into existence'. A disease is already latent in the body and unfolds on its own schedule, which is why we say symptoms develop rather than simply appear.","whyCN":"医学借用了不及物义“逐渐出现”。疾病早潜伏在身体里，按自己的时间表展开，所以我们说症状 develop，而不只是 appear。"},{"no":"08","title":"Become known: the facts come out","titleCN":"逐渐显露：事实自己走出来","definition":"to become known or come to light, especially in the phrase 'it developed that'","definitionCN":"变得为人所知、真相显露，尤用于 it developed that 这一说法","example":"It later developed that the signature had been forged.","exampleCN":"后来查明，那个签名是伪造的。","why":"The American English sense 'become known, come to light' is from 1864. What was folded in the facts is unfolded to the public, with no agent doing the unfolding.","whyCN":"美式英语中“变得为人所知、真相显露”的义项始于 1864 年。折在事实里的东西向公众展开，而没有任何施动者在做展开的动作。"},{"no":"09","title":"Form gradually: a habit or bond that grows","titleCN":"逐渐形成：长出来的习惯与关系","definition":"to begin to have a habit, feeling, or relationship that grows over time","definitionCN":"开始形成一种随时间生长的习惯、感情或关系","example":"They developed a friendship over years of working together.","exampleCN":"多年共事让他们逐渐结下了友谊。","why":"A habit or a bond is latent in repeated contact, the way a picture is latent in film. It is not created in one act but comes out slowly, so the word fits anything that grows by unfolding.","whyCN":"习惯或情谊潜伏在反复的接触里，就像影像潜伏在胶片里。它不是一次动作造出来的，而是慢慢显出来，所以这个词适用于一切靠展开而生长的事物。"},{"no":"10","title":"Build a product or system: the spec unfolded into code","titleCN":"开发产品：把规格书展开成代码","definition":"to create and improve a product, piece of software, or system over time","definitionCN":"随着时间创建并改进某种产品、软件或系统","example":"The team developed an app that tracks air quality.","exampleCN":"这个团队开发了一款监测空气质量的应用程序。","why":"Modern technology keeps the transitive 'bring out the potential' sense: an idea written in a specification is unfolded into a working system, version after version.","whyCN":"现代技术沿用了及物义“引出潜能”：写在规格书里的想法，被一版一版地展开成一个能运行的系统。"}],"etymology":{"intro":{"en":"Develop came into English in the 1650s from French développer 'to unwrap, unfold', replacing the earlier disvelop. The deeper stem voloper 'to wrap up' is of uncertain origin, so the chain is marked source uncertain at that point.","cn":"develop 于 17 世纪 50 年代从法语 développer“打开包裹、展开”进入英语，取代更早的 disvelop。更深处的词干 voloper“包裹”来源不确定，因此词源链在这一环标为“来源不确定”。"},"items":[{"era":"OLD FRENCH (12c.)","en":"Desveloper, desvoleper meant 'unwrap, unfurl, unveil; reveal the meaning of, explain'. It was built with des- 'undo' on voloper 'wrap up', a verb whose own origin is uncertain—possibly Celtic or Germanic, with no attested source form.","cn":"古法语 desveloper、desvoleper 意为“打开包裹、展开、揭幕；揭示含义、解释”。它由 des-“取消”加 voloper“包裹”构成，而 voloper 本身的来源不确定，可能来自凯尔特语或日耳曼语，没有可查的源词形式。"},{"era":"1590s ENGLISH","en":"The earlier English form was disvelop 'unwrap, disclose' (1590s), also from French. It lost the competition to develop, which arrived in the next century.","cn":"英语更早的形式是 disvelop“打开、揭示”（16 世纪 90 年代），同样来自法语。它在与 develop 的竞争中落败，后者在下一个世纪到来。"},{"era":"1650s ENGLISH","en":"Develop enters English in the 1650s with the literal sense 'unroll, unfold', which is now obsolete. The physical image of a scroll opening is the base of everything later.","cn":"develop 于 17 世纪 50 年代进入英语，字面义为“展开、摊开”，现已废弃。画卷打开这个具体画面，是后来一切用法的底子。"},{"era":"18c–19c ENGLISH","en":"The figurative uses appear in English: 1750 transitive 'bring out the potential in'; 1793 intransitive 'come gradually into existence'; 1843 'advance from one stage to another'; 1845 photographic 'make the latent image visible'; 1865 land development.","cn":"引申用法在英语里陆续出现：1750 年及物义“引出潜能”；1793 年不及物义“逐渐出现”；1843 年“逐阶段推进”；1845 年摄影义“使潜影可见”；1865 年土地开发义。"},{"era":"1864–1960 ENGLISH","en":"The American sense 'become known, come to light' is from 1864, and the adjective developing for poorer nations advancing economically dates from 1960.","cn":"美式英语“变得为人所知、真相显露”的义项始于 1864 年；用 developing 形容经济上正在前进的较贫穷国家，则始于 1960 年。"},{"era":"MODERN ENGLISH","en":"Modern English keeps the whole ladder: a child develops, a skill is developed, a film develops, land is developed, and software is developed. Each rung is still 'what was folded in becomes visible'.","cn":"现代英语保留了整架梯子：孩子发育、技能被培养、胶片显影、土地被开发、软件被开发。每一级仍然是“折在里面的东西变得可见”。"}]},"similar":{"note":{"en":"The first group is chosen for spelling and sound, the second for meaning, so that form and sense stay separate.","cn":"第一组按拼写和读音挑选，第二组按词义挑选，这样词形和词义不会混在一起。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"envelop","ipa":"/ɪnˈveləp/","tag":"same stem, opposite act","definition":"to wrap up or surround completely. It is develop's twin: en- 'in' wraps, des- 'undo' unwraps.","definitionCN":"包住；包围。它是 develop 的孪生词：en-“进入”是包上，des-“取消”是打开。"},{"word":"devolve","ipa":"/dɪˈvɒlv/","tag":"near spelling","definition":"to pass power or duty down to another; to decline. It comes from volvere 'to roll', not voloper 'to wrap'.","definitionCN":"移交（权力）；衰退。来自 volvere“滚动”，不是 voloper“包裹”。"},{"word":"deploy","ipa":"/dɪˈplɔɪ/","tag":"near sound","definition":"to move troops or resources into position. It comes from displicare 'to unfold', a different unfold from develop.","definitionCN":"部署（部队或资源）。来自 displicare“展开”，与 develop 的“展开”并非同一词源。"},{"word":"deliver","ipa":"/dɪˈlɪvə(r)/","tag":"near rhythm","definition":"to hand over or bring to a place. It shares the de- + v- shape but comes from liberare 'to free'.","definitionCN":"递送；交付。开头同样是 de- + v-，但来自 liberare“使自由”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"grow","ipa":"/ɡrəʊ/","tag":"living things","definition":"to increase in size naturally. It matches the intransitive sense of develop and is more physical.","definitionCN":"生长；增大。对应 develop 的不及物义，更偏身体和体量。"},{"word":"evolve","ipa":"/ɪˈvɒlv/","tag":"slow change","definition":"to change gradually over a long period. It stresses slow transformation rather than bringing out what is latent.","definitionCN":"演变；进化。强调长时间缓慢变化，而不是把潜伏之物引出来。"},{"word":"expand","ipa":"/ɪkˈspænd/","tag":"get bigger","definition":"to become larger or wider. It is about size, while develop is about fullness of form.","definitionCN":"扩大；扩张。说的是尺寸变大，而 develop 说的是形态变完整。"},{"word":"mature","ipa":"/məˈtʃʊə(r)/","tag":"reach adulthood","definition":"to become fully grown or fully developed. It names the end point of developing.","definitionCN":"成熟。它命名的是 develop 这条过程的终点。"},{"word":"cultivate","ipa":"/ˈkʌltɪveɪt/","tag":"deliberate care","definition":"to help something grow by care and effort. It matches the transitive 'bring out the potential' sense.","definitionCN":"培养；培育。对应及物义“引出潜能”，强调有意的照料。"}]}]},"mnemonics":{"normalIntro":{"en":"These links are real: des- 'undo' + voloper 'wrap', the twin envelop, and the 1845 photographic sense that shows the metaphor in the open.","cn":"这些联想都是真实的：des-“取消”+ voloper“包裹”、孪生词 envelop，以及 1845 年的摄影义——它把这个隐喻摊在了明面上。"},"normal":[{"en":"de- 'undo' + velop 'wrap': to develop is to unwrap. Hold a parcel in your hand and pull the paper off.","cn":"de-“取消”+ velop“包裹”：develop 就是把包裹打开。想象手里拿着一个包裹，把纸撕下来。"},{"en":"envelop is the same stem with en- 'in': to envelop is to wrap up, to develop is to unwrap. One word, two directions.","cn":"envelop 是同一词干加 en-“进入”：包住是裹上，develop 是打开。同一个词，两个方向。"},{"en":"Photography proves the metaphor: the image is already on the film, and the chemical bath develops it. Nothing new is added; something hidden is shown.","cn":"摄影证明了这层隐喻：影像早就在胶片上，药水只是把它显出来。没有添加新东西，只是让藏着的东西被看见。"},{"en":"Developing countries (1960) are named by the same picture: capacities folded inside a society being opened out.","cn":"developing countries（1960）用的也是同一个画面：一个社会内部折着的能力正在被展开。"},{"en":"Disvelop came first (1590s) and lost to develop (1650s); the surviving word is the one that stayed closer to 'unwrap'.","cn":"disvelop 先出现（1590 年代），却败给了 develop（1650 年代）；活下来的是那个更贴近“打开包裹”的词。"}],"abstract":[{"en":"Everything that grows was first wrapped: the word says the future is folded inside the present.","cn":"一切生长之物最初都是被包着的：这个词在说，未来折在现在里面。"},{"en":"Unwrap, unfold, grow, cultivate, build, and bring out a picture are one gesture at six scales.","cn":"打开、展开、生长、培养、建造、显影，是同一个动作在六种尺度上的样子。"},{"en":"So a seed, a skill, a film, a housing estate and a fever all 'develop': each is something coming out of its folds on its own schedule.","cn":"所以种子、技能、胶片、住宅区、发烧都会 develop：每一样都是折着的东西按自己的时间表走出来。"}]},"examples":[{"en":"Children develop language skills fastest in their first years.","cn":"儿童在最初几年发展语言能力最快。"},{"en":"The small town developed into a busy port within two decades.","cn":"这座小镇在二十年内发展成了一个繁忙的港口。"},{"en":"He developed a cough that lasted for weeks after the trip.","cn":"旅行之后他咳嗽起来，持续了好几周。"}],"dict_mnemonic":{"note":"词根拆解 · 有词源依据","text":"de（去掉）+ velop（包裹）：去掉包裹，就 develop 了——展开、发展","word":"develop"},"root":"源自法语 développer“打开包裹、展开”，更早为古法语 desveloper（des 取消 + voloper 包裹，voloper 来源不确定）；1650 年代进入英语，由“展开”引申为“发展、培养、显影、发病”。","sensesIntro":{"en":"Ten senses of develop, all built on one gesture: taking a wrap off so that what was folded inside can be seen. A scroll, a seed, a talent, a film, a disease and a product all unfold the same way.","cn":"develop 的十个义项都建立在一个动作上：去掉包裹，让折在里面的东西被看见。画卷、种子、才能、胶片、疾病、产品，都以同一种方式展开。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wrapped thing opened out, and the shape inside becoming visible.","cn":"核心意象：包着的东西被打开，里面的形状露出来。"},"chain":["UNWRAP","UNFOLD","GROW","CULTIVATE","COME INTO USE","COME TO LIGHT"],"branches":[{"senses":"S01 · S06","en":"THE LITERAL UNWRAPPING: a scroll unrolled, and a latent image brought out by chemicals.","cn":"字面的打开：画卷摊开，潜影被药水显出来。"},{"senses":"S02 · S07 · S08","en":"WHAT EMERGES ON ITS OWN: a plant grows, symptoms appear, facts come to light.","cn":"自己出现的东西：植物长成、症状出现、事实显露。"},{"senses":"S03 · S09","en":"WHAT IS BROUGHT OUT BY CARE: a talent is cultivated, a friendship forms over years.","cn":"被照料出来的东西：才能被培养，友谊在多年里形成。"},{"senses":"S04 · S05","en":"THE STAGES AND THE SITE: a project advances step by step, and land is converted to use.","cn":"阶段与场地：项目逐阶段推进，土地被转为用途。"},{"senses":"S10","en":"THE MODERN PRODUCT: a specification unfolds into a working system, version after version.","cn":"现代的产品：规格书一版一版地展开成能运行的系统。"}]},"affixes":{"intro":{"en":"Develop has no Latin base: its stem comes from Old French des- 'undo' plus voloper 'wrap up', and the family is English and French—development, developer, envelop, envelope, redevelop.","cn":"develop 没有拉丁词根：它的词干来自古法语 des-“取消”加 voloper“包裹”，其词族属于英语和法语——development、developer、envelop、envelope、redevelop。"},"latinIntro":{"en":"There is no Latin source here. The ancestor is Old French desveloper, whose second element voloper 'wrap up' is of uncertain origin (possibly Celtic or Germanic), so it must not be assigned a Latin root.","cn":"这里没有拉丁语来源。其祖先是古法语 desveloper，第二个成分 voloper“包裹”来源不确定（可能来自凯尔特语或日耳曼语），因此不能给它安上一个拉丁词根。"},"items":[{"word":"develop","structure":"de- (undo) + velop (wrap)","meaning":"to unwrap; hence to unfold, grow, or bring out","meaningCN":"打开包裹；由此引申为展开、发展、培养","example":"The city plans to develop the riverfront.","exampleCN":"这座城市计划开发滨河地带。"},{"word":"development","structure":"develop + -ment (noun)","meaning":"the process of unfolding or growing","meaningCN":"发展；开发（展开的过程）","example":"Language development begins before birth.","exampleCN":"语言发展在出生前就开始了。"},{"word":"developer","structure":"develop + -er (agent noun)","meaning":"one who develops; a chemical that brings out an image","meaningCN":"开发者；开发商；显影剂","example":"The developer bought the empty lot.","exampleCN":"开发商买下了那块空地。"},{"word":"developing","structure":"develop + -ing (participle/adjective)","meaning":"in the process of growth","meaningCN":"发展中的；显影的","example":"Developing countries need cheaper vaccines.","exampleCN":"发展中国家需要更便宜的疫苗。"},{"word":"developed","structure":"develop + -ed (past participle/adjective)","meaning":"fully grown or advanced","meaningCN":"发达的；已开发的","example":"The photograph is fully developed now.","exampleCN":"这张照片现在已经完全显影了。"},{"word":"undeveloped","structure":"un- (not) + develop + -ed","meaning":"not yet grown or used","meaningCN":"未开发的；未发展的","example":"Much of the island remains undeveloped.","exampleCN":"这座岛的大部分仍未开发。"},{"word":"underdeveloped","structure":"under- (below) + develop + -ed","meaning":"grown less than is normal or needed","meaningCN":"发育不良的；发展不充分的","example":"The seedlings were underdeveloped after the cold spring.","exampleCN":"冷春之后，这些幼苗发育不良。"},{"word":"redevelop","structure":"re- (again) + develop","meaning":"to develop again or rebuild","meaningCN":"重新开发；改建","example":"The council plans to redevelop the old market.","exampleCN":"市政会计划重新开发那个旧市场。"},{"word":"envelop","structure":"en- (in) + velop (wrap)","meaning":"to wrap up, surround","meaningCN":"包住；包围（与 develop 同一词干的反向动作）","example":"Fog enveloped the valley at dawn.","exampleCN":"黎明时雾笼罩了山谷。"},{"word":"envelope","structure":"en- (in) + velop (wrap) + -e (noun)","meaning":"a paper wrapper for a letter","meaningCN":"信封（把信包起来的东西）","example":"She sealed the envelope and posted it.","exampleCN":"她封好信封寄了出去。"}],"latinEntries":[]}},{"word":"device","ipa_uk":"/dɪˈvaɪs/","ipa_us":"/dɪˈvaɪs/","definition_zh":"装置；设备；手段；策略；徽章；遗赠","definition_en":"a thing made for a particular purpose, or a plan or trick used to achieve an effect","core_image":"一只手上摊开的小机关——每个零件都被分派到一个用途","scene":"A nurse clips a small box to the patient's finger: The device measures his oxygen level all night and sends the numbers to the ward.","sceneCN":"这里 device 是「装置、设备」（第 03 个义项：有特定用途的器械）；句意：这个装置整夜监测他的血氧，并把数据传到病房。画面里可辨识的物件：指夹式血氧仪、导线、床头监护屏。","pos":[{"tag":"n.","zh":"装置；设备；手段；策略；徽章"}],"collocations":[{"phrase":"a handheld device","zh":"手持设备"},{"phrase":"leave somebody to their own devices","zh":"让某人自行其是"},{"phrase":"a rhetorical device","zh":"修辞手法"},{"phrase":"an explosive device","zh":"爆炸装置"},{"phrase":"a device for doing something","zh":"用于做某事的装置"}],"forms":[{"label":"单数","form":"device"},{"label":"复数","form":"devices"}],"derivatives":[{"word":"devise","pos":"vt.","zh":"设计；想出；遗赠"},{"word":"deviser","pos":"n.","zh":"设计者；筹划者"},{"word":"devisable","pos":"adj.","zh":"可设计的；（法律）可遗赠的"},{"word":"devisee","pos":"n.","zh":"（法律）受遗赠人"},{"word":"deviceful","pos":"adj.","zh":"（罕）精巧的；多计谋的"}],"senses":[{"no":"01","title":"A plan: the earliest sense, an arrangement made in portions","titleCN":"计划：最早的义项，按份额分派的安排","definition":"a plan, intention, or arrangement (c. 1300, now archaic)","definitionCN":"计划、意图或安排（约 1300 年，现为古义）","example":"Their device was to divide the estate before any dispute arose.","exampleCN":"他们的打算是在争端出现之前就把产业分开。","why":"Device comes from Old French devis 'division, disposition, wish, desire', from Vulgar Latin *divisare, a frequentative of dividere 'to divide'. The basic sense is 'method by which something is divided', so a device is first a way of splitting a task into parts.","whyCN":"device 来自古法语 devis“划分、处置、愿望”，再往上出自俗拉丁语 *divisare，是 dividere“分开”的反复动词。基本义是“把某物分开的方法”，所以 device 最初是把一件事分成几份来办的办法。"},{"no":"02","title":"A contrivance: the plan turned into an object","titleCN":"巧制物：计划变成了实物","definition":"an invention or constructed thing fitted to a particular purpose (from c. 1400)","definitionCN":"为特定用途而造出的发明或器械（约 1400 年起）","example":"He built a device that opens the gate when the car approaches.","exampleCN":"他做了一个装置，车一靠近门就开。","why":"From the plan sense came 'something invented or fitted to a particular use or purpose'. Once an arrangement is worked out, someone can build it; the plan then stands on the table as an object.","whyCN":"从“计划”义长出了“为特定用途发明或装配的东西”。安排一旦想清楚，就有人能把它造出来；于是计划变成了桌上立着的一件实物。"},{"no":"03","title":"A piece of equipment: one tool with one job","titleCN":"设备：一件工具只做一件事","definition":"a piece of equipment, especially a compact one, made for a specific function","definitionCN":"为特定功能制造的设备，尤指小型器械","example":"The device measures his oxygen level all night.","exampleCN":"这个装置整夜监测他的血氧。","why":"Modern usage narrowed the contrivance to a compact instrument with a single job. The 'fitted to a purpose' idea is now visible in the shape: a device usually does one thing well.","whyCN":"现代用法把“巧制物”缩小为只做一件事的小型器械。“为某个用途而装配”这个想法如今写在了外形上：一件 device 通常只把一件事做好。"},{"no":"04","title":"A stratagem: a plan aimed at people, not matter","titleCN":"策略：对准人而不是物的计划","definition":"a plan, trick, or scheme used to achieve an aim, often by deception","definitionCN":"为达到目的而用的计划、计谋或手段，常含欺骗","example":"Silence was his favourite device for ending an argument.","exampleCN":"沉默是他终止争论最爱用的手段。","why":"A plan can be aimed at people rather than at materials. The same 'arrangement in portions' becomes a manoeuvre: you divide a situation into moves and play them in order.","whyCN":"计划也可以对准人，而不是对准材料。同一套“按份额分派”变成了招法：你把局面分成几步，再按顺序走出来。"},{"no":"05","title":"A rhetorical device: a pattern deliberately built into words","titleCN":"修辞手法：有意写进语言里的结构","definition":"a technique deliberately used in writing or speech to produce an effect","definitionCN":"写作或演说中为产生某种效果而刻意使用的手法","example":"Repetition is a device that makes a speech memorable.","exampleCN":"重复是一种让演讲令人难忘的手法。","why":"From the c. 1400 sense 'artistic design, work of art; ornament', a device became a designed pattern. In rhetoric the material is words, and the design is put in on purpose so the listener can feel it.","whyCN":"从约 1400 年的“艺术设计、艺术作品、装饰”义出发，device 成了有意图的图案。在修辞里材料是词语，这个图案被故意装进去，让听者感觉到它。"},{"no":"06","title":"An explosive device: the object named by its function","titleCN":"爆炸装置：用功能来命名的物件","definition":"a bomb or similar explosive mechanism","definitionCN":"炸弹或类似的爆炸器械","example":"Bomb disposal officers found an unexploded device in the field.","exampleCN":"排爆人员在田里发现了一枚未爆装置。","why":"Military and police writing prefers device to bomb: it names the object by its purpose and keeps the description technical. The contrivance sense is here at its barest—a thing fitted to one effect.","whyCN":"军事和警务文本爱用 device 而不说 bomb：它按用途命名物件，让描述保持技术化。这里“巧制物”义最赤裸——一件只为一种效果装配的东西。"},{"no":"07","title":"A heraldic device: the badge that declares its bearer","titleCN":"徽章：替持有者说话的图案","definition":"an emblem or design, often with a motto, used as a symbol of a person, family, or institution","definitionCN":"常配箴言的图案或标志，用作个人、家族或机构的象征","example":"The shield bears a device of a lion and a motto.","exampleCN":"这面盾上有一个狮形徽记和一句箴言。","why":"The c. 1400 'artistic design' sense became the emblem painted on a shield: a representation with a motto expressing the bearer's principles. A device here declares intent without words.","whyCN":"约 1400 年的“艺术设计”义变成了画在盾上的纹章：一个配着箴言、表达持有者原则的图像。这里的 device 不用言语就宣告了意图。"},{"no":"08","title":"A bequest: property divided by a will","titleCN":"遗赠：由遗嘱分出去的财产","definition":"a gift of property left by a will (mid-15c.)","definitionCN":"通过遗嘱留下的财产赠与（15 世纪中期）","example":"Under the device, the library received the whole collection.","exampleCN":"根据这项遗赠，图书馆得到了全部藏书。","why":"From mid-15c. device could mean 'a bequest in a will'. To devise property is to divide it by will, so the noun kept the old sense of a division—now a division that takes effect after death.","whyCN":"从 15 世纪中期起，device 可指“遗嘱中的遗赠”。devise 财产就是按遗嘱把它分出去，所以名词保留了古老的“划分”义——只是这次划分在身后生效。"},{"no":"09","title":"Their own devices: leaving someone to their own plans","titleCN":"自行其是：把某人交给他自己的安排","definition":"in the phrase 'leave someone to their own devices', to let them act without help or supervision","definitionCN":"在 leave someone to their own devices 中，指让某人无人帮助、无人监管地自行行动","example":"The children were left to their own devices for the afternoon.","exampleCN":"孩子们下午被放任自便。","why":"Here devices are resources or plans, not machines. To leave people to their own devices is to leave them with their own arrangements and withdraw yours—the oldest 'plan' sense surviving inside an idiom.","whyCN":"这里的 devices 指办法或打算，不是机器。leave people to their own devices 就是把人交给他自己的安排、撤回你的安排——最古老的“计划”义活在这个习语里。"},{"no":"10","title":"A mobile device: the same word at a new scale","titleCN":"移动设备：同一个词换了尺度","definition":"a handheld or mobile electronic computing instrument, a use especially common since c. 1996","definitionCN":"手持或移动的电子计算设备，这一用法自约 1996 年起特别常见","example":"The app syncs your notes across all your devices.","exampleCN":"这款应用会在你所有设备之间同步笔记。","why":"Since c. 1996 device has been used especially for handheld computing instruments. Nothing in the sense changed: it is still a contrivance fitted to a purpose, only the purpose is now memory, signal and screen.","whyCN":"自约 1996 年起，device 尤指手持计算设备。义项本身没有变：它仍是为某个用途装配的巧制物，只是用途现在变成了存储、信号和屏幕。"}],"etymology":{"intro":{"en":"Device comes from Old French devis 'division, disposition, wish', from Vulgar Latin *divisare, a frequentative of dividere 'to divide'. The basic sense is 'a method by which something is divided', and every modern sense grows from it.","cn":"device 来自古法语 devis“划分、处置、愿望”，再往上出自俗拉丁语 *divisare，是 dividere“分开”的反复动词。基本义是“把某物分开的方法”，现代所有义项都从这一点长出来。"},"items":[{"era":"PIE (reconstructed)","en":"Dividere is traced to a reconstructed root *(d)uid- 'to separate, distinguish'. Latin lost the initial *d- by dissimilation and reinforced the verb with dis-. No written PIE form survives, so this level is reconstruction only.","cn":"dividere 可追溯到重构词根 *(d)uid-“分开、区分”。拉丁语在相邻齿音前发生异化而丢掉词首的 *d-，又用 dis- 强化了这个动词。原始印欧语没有书面形式留存，所以这一层只是重构。"},{"era":"LATIN","en":"Dividere meant 'to force apart, cleave, distribute', built on dis- 'apart' plus -videre 'to separate'. Vulgar Latin *divisare was its frequentative, used for arranging things in portions.","cn":"dividere 意为“使分开、劈开、分配”，由 dis-“分开”加 -videre“分离”构成。俗拉丁语 *divisare 是它的反复动词，用来表示把东西按份分派。"},{"era":"OLD FRENCH (12c.)","en":"Devis meant 'division, separation; disposition, wish, desire; coat of arms, emblem; a bequest in a will'. Deviser meant 'arrange, plan, contrive', literally 'dispose in portions'.","cn":"devis 意为“划分、分离；处置、愿望；纹章、徽记；遗嘱中的遗赠”。deviser 意为“安排、计划、筹划”，字面是“按份额分派”。"},{"era":"c. 1300 ENGLISH","en":"English device first meant 'intent, desire; an expressed intent; a plan or design; a literary composition'. The plan sense is the trunk from which the object senses branch.","cn":"英语 device 最早意为“意图、愿望；表达出的意图；计划或设计；文学作品”。计划义是主干，物件义都从它分叉。"},{"era":"c. 1400–mid 15c ENGLISH","en":"By c. 1400 device also meant 'artistic design, work of art; ornament' and 'mechanical contrivance' such as a cranked crossbow; mid-15c. added 'a bequest in a will'.","cn":"到约 1400 年，device 也指“艺术设计、艺术作品、装饰”和“机械装置”（如带摇柄的十字弓）；15 世纪中期又添“遗嘱中的遗赠”。"},{"era":"MODERN ENGLISH","en":"Modern English keeps the plan, the machine, the trick, the emblem and the bequest. Since c. 1996 the word has been applied especially to handheld computing instruments.","cn":"现代英语同时保留计划、机器、计谋、徽记和遗赠五种用法。自约 1996 年起，这个词尤用于手持计算设备。"}]},"similar":{"note":{"en":"The first group is chosen for spelling and sound, the second for meaning, so that form and sense stay separate.","cn":"第一组按拼写和读音挑选，第二组按词义挑选，这样词形和词义不会混在一起。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"devise","ipa":"/dɪˈvaɪz/","tag":"same family, verb","definition":"to plan or invent; to leave property by will. It is the verb twin of device and ends in /z/, not /s/.","definitionCN":"设计；想出；遗赠。它是 device 的动词孪生词，结尾读 /z/ 而不是 /s/。"},{"word":"devious","ipa":"/ˈdiːviəs/","tag":"near spelling","definition":"indirect or dishonest. It comes from via 'way', not from dividere, so it is not a relative of device.","definitionCN":"迂回的；不正直的。来自 via“道路”，不是 dividere，因此与 device 并非同源。"},{"word":"advice","ipa":"/ədˈvaɪs/","tag":"near sound","definition":"an opinion offered to help someone decide. It ends like device but begins with ad- and is a noun of a different family.","definitionCN":"建议；忠告。结尾像 device，但开头是 ad-，属于另一个词族的名词。"},{"word":"divisive","ipa":"/dɪˈvaɪsɪv/","tag":"same root, adjective","definition":"causing disagreement. It shares dividere with device and shows the original 'divide' idea openly.","definitionCN":"造成分裂的。与 device 同出 dividere，把“分开”这个原义露在外面。"}]},{"heading":"NEAR MEANING","entries":[{"word":"gadget","ipa":"/ˈɡædʒɪt/","tag":"small tool","definition":"a small, often ingenious tool. It matches device in the 'compact equipment' sense but sounds informal.","definitionCN":"小装置；小玩意。对应 device 表“小型设备”的义项，但更口语。"},{"word":"instrument","ipa":"/ˈɪnstrəmənt/","tag":"precision tool","definition":"a tool used for precise work, especially in science. It is more technical than device.","definitionCN":"仪器；工具。尤指科学上的精密工具，比 device 更专业。"},{"word":"apparatus","ipa":"/ˌæpəˈreɪtəs/","tag":"set of equipment","definition":"a set of equipment used for a particular activity. It is usually larger and more complex than a device.","definitionCN":"器械；设备。通常比单件 device 更大、更复杂。"},{"word":"tool","ipa":"/tuːl/","tag":"general","definition":"anything used to do work. It is the broadest word, while device implies a designed mechanism.","definitionCN":"工具。最宽泛的词，而 device 含有“设计过的机关”之意。"},{"word":"mechanism","ipa":"/ˈmekənɪzəm/","tag":"working parts","definition":"the working parts of a machine, or a process by which something works. It stresses how it works, not what it is for.","definitionCN":"机械装置；机制。强调它怎么运作，而不是它用来做什么。"}]}]},"mnemonics":{"normalIntro":{"en":"These links are real: dividere 'to divide' behind device, its verb twin devise, and the Old French sense 'coat of arms, bequest'.","cn":"这些联想都是真实的：device 背后的 dividere“分开”、动词孪生词 devise，以及古法语里的“纹章、遗赠”义。"},"normal":[{"en":"divide is inside device: Latin dividere 'to divide'. A device is a way of dividing a job into parts and giving each part a piece of metal.","cn":"divide 就在 device 里面：拉丁语 dividere“分开”。device 是把一项任务分成几份、再给每份配一块金属的办法。"},{"en":"device and devise are twins: the noun is the thing arranged, the verb is the arranging. One letter, two parts of speech.","cn":"device 和 devise 是孪生词：名词是被安排好的东西，动词是安排的动作。差一个字母，两个词性。"},{"en":"'Leave someone to their own devices' keeps the oldest sense: devices are plans and resources, not machines.","cn":"leave someone to their own devices 保留着最古老的义项：devices 是打算和办法，不是机器。"},{"en":"Heraldry: a device on a shield is a picture with a motto, saying what the bearer intends. The word still means a declared plan.","cn":"纹章学：盾上的 device 是一幅配着箴言的图，说出持有者的志向。这个词仍然表示“公开宣告的打算”。"},{"en":"An explosive device is a bomb named by its function, not by its material. Official language prefers the purpose to the thing.","cn":"an explosive device 是按功能命名的炸弹，不是按材料命名。官方语言宁愿说用途，不愿说那个东西本身。"}],"abstract":[{"en":"First an arrangement, then an object, then a trick, then a badge: each is a division made visible.","cn":"先是安排，再是物件，再是计谋，再是徽记：每一样都是被看得见的“划分”。"},{"en":"A device is always 'fitted to a purpose'. That phrase is the thread that runs through the plan, the machine, the rhetorical trick, the emblem and the bequest.","cn":"device 永远是“为某个用途而装配”。这句话就是那根线，串起计划、机器、修辞手法、徽记和遗赠。"},{"en":"So a scheme, a phone, a metaphor, a coat of arms, and a clause in a will are one act of dividing at five surfaces.","cn":"所以一个计策、一部手机、一个隐喻、一枚纹章、遗嘱里的一条，都是同一个“划分”动作落在五种表面上。"}]},"examples":[{"en":"The device fits in a pocket and runs for a week on one charge.","cn":"这个装置能放进口袋，充一次电可用一周。"},{"en":"They left him to his own devices and he finished the report his way.","cn":"他们让他自行其是，他就按自己的方式写完了报告。"},{"en":"Irony is a device that lets a writer say one thing and mean another.","cn":"反讽是一种让作者说一件事、却意指另一件事的手法。"}],"dict_mnemonic":{"note":"词根拆解 · 有词源依据","text":"de（分开）+ vis（分）+ e：把用途一份份分派下去的东西——device 装置、手段","word":"device"},"root":"源自拉丁语 dividere“分开”（dis 分开 + -videre 分离），经俗拉丁语 *divisare、古法语 devis 于约 1300 年进入英语；核心是“按份额分派的安排”，由此引申出装置、手段、徽章、遗赠。","sensesIntro":{"en":"Ten senses of device, all built on one idea: an arrangement made by dividing something into parts. A plan, a machine, a trick, an emblem and a bequest are that division applied to time, metal, people, cloth and property.","cn":"device 的十个义项都建立在一个想法上：把某物分成几份后作出的安排。计划、机器、计谋、徽记、遗赠，就是这个“划分”分别落在时间、金属、人、布帛和财产上。"},"semanticMap":{"core":{"en":"CORE IMAGE: a handful of parts, each assigned to one job, assembled into a single thing.","cn":"核心意象：几样零件，每样各管一件事，被装配成同一个东西。"},"chain":["DIVIDE","ARRANGE IN PORTIONS","PLAN","BUILD A CONTRIVANCE","TURN IT ON PEOPLE","DECLARE AND BEQUEATH"],"branches":[{"senses":"S01 · S09","en":"THE PLAN: an intention arranged in steps, which survives in 'their own devices'.","cn":"计划：按步骤排好的意图，仍活在 their own devices 里。"},{"senses":"S02 · S03 · S10","en":"THE OBJECT: the plan built into metal, shrunk to a pocket tool, then into a phone.","cn":"物件：计划被造成金属，缩成口袋工具，再变成手机。"},{"senses":"S04 · S05","en":"THE TRICK IN WORDS AND IN PEOPLE: a stratagem aimed at a person, and a pattern aimed at an audience.","cn":"人与词里的招法：对准某个人的计谋，与对准听众的语言结构。"},{"senses":"S06","en":"THE NAMED FUNCTION: an explosive device is called by what it does, not by what it is.","cn":"按功能命名：爆炸装置按它做的事得名，而不是按它是什么。"},{"senses":"S07 · S08","en":"THE DECLARATION AND THE WILL: an emblem that states principles, and property divided after death.","cn":"宣告与遗嘱：陈述原则的徽记，与身后分出去的财产。"}]},"affixes":{"intro":{"en":"Device is built on the Latin divide family: divis-, vid- 'separate'. Its relatives are divide, division, individual, subdivide and divisible, plus the verb twin devise.","cn":"device 建立在拉丁语 divide 词族上：divis-、vid-“分开”。亲属有 divide、division、individual、subdivide、divisible，以及动词孪生词 devise。"},"latinIntro":{"en":"Latin dividere 'to divide' (dis- 'apart' + -videre 'separate') gives divisio and the frequentative *divisare, which becomes Old French devis and English device and devise.","cn":"拉丁语 dividere“分开”（dis-“分开”+ -videre“分离”）构成 divisio 和反复动词 *divisare，后者变成古法语 devis，再变成英语 device 和 devise。"},"items":[{"word":"device","structure":"de- (apart) + vis- (separate) + -e","meaning":"a plan arranged in parts; hence a contrivance","meaningCN":"按份安排的计划；由此引申为装置","example":"The device tracks the package from door to door.","exampleCN":"这个装置全程追踪包裹的运送。"},{"word":"devise","structure":"de- + vis- + -e (verb)","meaning":"to arrange, plan, contrive; to leave by will","meaningCN":"设计；筹划；遗赠","example":"They devised a simple test for the water.","exampleCN":"他们设计了一个简单的水质测试。"},{"word":"deviser","structure":"devise + -er (agent noun)","meaning":"one who plans or contrives","meaningCN":"设计者；筹划者","example":"The deviser of the scheme kept his name secret.","exampleCN":"这个方案的筹划者没有公开姓名。"},{"word":"devisable","structure":"devise + -able (can be)","meaning":"able to be planned; able to be left by will","meaningCN":"可设计的；（法律）可遗赠的","example":"The land is devisable under the new will.","exampleCN":"根据新遗嘱，这块地可以遗赠。"},{"word":"devisee","structure":"devise + -ee (person receiving)","meaning":"a person to whom property is left by will","meaningCN":"（法律）受遗赠人","example":"The devisee signed the deed in the lawyer's office.","exampleCN":"受遗赠人在律师事务所签了契据。"},{"word":"divide","structure":"dis- (apart) + vid- (separate) + -e","meaning":"to separate into parts","meaningCN":"分开；划分","example":"Divide the class into four groups.","exampleCN":"把全班分成四组。"},{"word":"division","structure":"divis- (divide) + -ion (noun)","meaning":"the act of separating; a part of an organization","meaningCN":"分开；除法；部门","example":"The division of labour sped up the work.","exampleCN":"分工加快了工作进度。"},{"word":"individual","structure":"in- (not) + divid- (divide) + -ual","meaning":"not divisible; a single person","meaningCN":"不可分割的；个体","example":"Each individual receives a different schedule.","exampleCN":"每个人都会收到不同的时间表。"},{"word":"subdivide","structure":"sub- (under, further) + divide","meaning":"to divide again into smaller parts","meaningCN":"再分；细分成更小的部分","example":"The land was subdivided into six plots.","exampleCN":"这块地被细分成六小块。"},{"word":"divisible","structure":"divis- (divide) + -ible (can be)","meaning":"able to be divided","meaningCN":"可分割的；可整除的","example":"Twelve is divisible by three.","exampleCN":"十二可以被三整除。"}],"latinEntries":[{"word":"dividere","structure":"dis- + -videre (verb)","meaning":"to force apart, cleave, distribute","meaningCN":"分开；劈开；分配"},{"word":"divisare","structure":"frequentative of dividere","meaning":"to divide repeatedly; to dispose in portions","meaningCN":"反复分开；按份额分派"},{"word":"divisio","structure":"divis- + -io (noun)","meaning":"a division, distribution","meaningCN":"划分；分配"}]}}]);
